window.EXPERIMENTS = [
{"id":"titration","name":"酸碱中和滴定","category":"基础操作","hazard":1,"duration":"25 分钟","summary":"用已知浓度的氢氧化钠标准液标定盐酸。滴定操作、终点判断和数据处理，是定量分析的基本功。","principle":["HCl + NaOH  →  NaCl + H₂O","c(HCl) = c(NaOH) × V(NaOH) ÷ V(HCl)"],"reagents":["0.1000 mol/L 氢氧化钠标准溶液","待测盐酸","酚酞指示剂","蒸馏水"],"steps":["检漏：给滴定管装满水，静置 2 分钟观察是否漏水，旋转活塞是否灵活。","洗涤：滴定管用蒸馏水洗后再用待装液润洗 2–3 次；锥形瓶只用水洗，不能润洗。","装液：把标准液装入滴定管，排尽尖嘴处气泡，调节液面并记录初读数。","移取 20.00 mL 待测盐酸于锥形瓶，加入 2 滴酚酞，溶液无色。","滴定：左手控制活塞，右手不断摇动锥形瓶，眼睛注视锥形瓶内颜色变化。","当滴入最后一滴标准液，溶液由无色变为浅红色且半分钟内不褪色，即为终点，记录末读数。","重复滴定 3 次，取体积平均值代入公式计算。"],"tags":["高中","大学"],"difficulty":2},
{"id":"flame-test","name":"焰色试验","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"用铂丝蘸取金属盐在火焰上灼烧，通过特征颜色判断金属元素。钾的紫色需透过蓝色钴玻璃观察。","principle":["原子吸收能量后电子跃迁到激发态，回到基态时以光的形式释放能量","不同元素的发射光谱不同，因此焰色具有特征性"],"reagents":["氯化钠","氯化钾","氯化钙","硫酸铜","氯化钡","浓盐酸"],"steps":["把铂丝蘸取浓盐酸，在酒精灯外焰上灼烧，反复几次直到火焰不再有杂色。","蘸取少量氯化钠固体（或溶液），置于外焰灼烧，观察火焰颜色。","每换一种试剂前，都要重新用盐酸洗净铂丝并灼烧至无色。","观察钾盐时，透过蓝色钴玻璃滤去钠的黄光。","依次检验钙、铜、钡等盐，记录颜色。"],"tags":["高中"],"difficulty":2},
{"id":"electrolysis-water","name":"电解水","category":"电化学","hazard":2,"duration":"20 分钟","summary":"直流电通入加有少量电解质的水，阴极得氢气、阳极得氧气，体积比约为 2:1。","principle":["2H₂O  --通电-->  2H₂↑ + O₂↑","阴极：2H₂O + 2e⁻ → H₂↑ + 2OH⁻","阳极：2H₂O − 4e⁻ → O₂↑ + 4H⁺"],"reagents":["蒸馏水","少量硫酸钠或氢氧化钠（增强导电性）"],"steps":["向水中加入少量硫酸钠或氢氧化钠，搅拌溶解。","把水注入电解器，排出管内空气，记下初始液面。","接通 6–12 V 直流电源，观察两极产生气泡的速率。","通电一段时间后，比较两极收集到的气体体积。","检验阴极气体：点燃，淡蓝色火焰；检验阳极气体：带火星木条复燃。"],"tags":["初中"],"difficulty":2},
{"id":"iodine-clock","name":"碘钟反应","category":"趣味演示","hazard":2,"duration":"10 分钟","summary":"无色溶液静置片刻后突然变成深蓝色，像被按下了开关。本质是碘酸盐与亚硫酸氢盐的竞争反应。","principle":["IO₃⁻ + 3HSO₃⁻  →  I⁻ + 3SO₄²⁻ + 3H⁺","IO₃⁻ + 5I⁻ + 6H⁺  →  3I₂ + 3H₂O","I₂ + 淀粉  →  蓝色包合物（蓝色出现即计时终点）"],"reagents":["碘酸钾","亚硫酸氢钠","可溶性淀粉","稀硫酸","蒸馏水"],"steps":["配制 A 液：碘酸钾、稀硫酸和淀粉溶液混合，加蒸馏水稀释。","配制 B 液：亚硫酸氢钠溶液。","把 A、B 两液同时倒入同一烧杯并开始计时，轻轻搅匀。","静置观察，记录溶液突然变蓝的时间。","改变亚硫酸氢钠浓度重复实验，比较变色时间的差异。"],"tags":["高中"],"difficulty":3},
{"id":"elephant-toothpaste","name":"大象牙膏","category":"趣味演示","hazard":2,"duration":"8 分钟","summary":"过氧化氢在碘化钾催化下剧烈分解放出氧气，被洗洁精捕获形成大量泡沫，像牙膏一样喷涌而出。","principle":["2H₂O₂  --KI-->  2H₂O + O₂↑","放热反应使部分水汽化，泡沫迅速膨胀"],"reagents":["30% 过氧化氢","饱和碘化钾溶液","洗洁精","食用色素","蒸馏水"],"steps":["把量筒放在托盘上，加入 30% 过氧化氢和几滴洗洁精、少量色素，摇匀。","快速倒入饱和碘化钾溶液。","立即后退观察泡沫喷涌。","反应结束后用大量水稀释残液再处理。"],"tags":["初中","高中"],"difficulty":2},
{"id":"blue-bottle","name":"蓝瓶子实验","category":"趣味演示","hazard":1,"duration":"10 分钟","summary":"振荡变蓝、静置褪色，可以反复多次。亚甲基蓝在葡萄糖与氧气之间充当可逆的氧化还原指示剂。","principle":["亚甲基蓝（氧化态，蓝色）+ 葡萄糖  →  还原态亚甲基蓝（无色）","还原态亚甲基蓝 + O₂  →  氧化态亚甲基蓝（蓝色）"],"reagents":["亚甲基蓝溶液","葡萄糖","氢氧化钠","蒸馏水"],"steps":["在瓶中加入蒸馏水和葡萄糖，溶解后加入几滴亚甲基蓝溶液。","加入氢氧化钠溶液，塞紧瓶塞，摇匀。","静置观察颜色逐渐变浅直至无色。","用力振荡，溶液重新变蓝；再静置又褪色。","重复多次，观察可逆性。"],"tags":["初中"],"difficulty":2},
{"id":"silver-mirror","name":"银镜反应","category":"有机","hazard":3,"duration":"20 分钟","summary":"醛基被托伦试剂氧化，银离子还原为金属银附着在试管内壁，形成光亮银镜。","principle":["RCHO + 2[Ag(NH₃)₂]OH  --Δ-->  RCOONH₄ + 2Ag↓ + 3NH₃ + H₂O","银氨溶液：AgNO₃ + NH₃·H₂O → AgOH↓ → [Ag(NH₃)₂]OH"],"reagents":["2% 硝酸银溶液","2% 稀氨水","乙醛（或葡萄糖溶液）","蒸馏水"],"steps":["试管先用氢氧化钠溶液煮沸洗净，再用蒸馏水冲洗，确保内壁无油污。","配制托伦试剂：1 mL 硝酸银溶液，逐滴加稀氨水至沉淀恰好溶解。","加入 3–5 滴乙醛（或少量葡萄糖溶液），摇匀。","放入 60–70 ℃ 水浴中静置加热 5–10 分钟，不要摇动。","观察试管内壁生成的银镜，实验后立即处理残液。"],"tags":["高中"],"difficulty":2},
{"id":"thermite","name":"铝热反应","category":"物质性质","hazard":3,"duration":"10 分钟","summary":"铝粉与氧化铁在高温下发生置换反应，放出大量热，生成熔融的铁。极强的放热演示，禁止自行尝试。","principle":["2Al + Fe₂O₃  --高温-->  Al₂O₃ + 2Fe","反应放热使温度可达 2000 ℃ 以上"],"reagents":["氧化铁（Fe₂O₃）","铝粉","镁条","氯酸钾","细沙"],"steps":["在沙盘上放置坩埚，周围铺满细沙。","把氧化铁与铝粉按约 3:1 混合均匀，装入纸漏斗。","在混合物顶部铺少量氯酸钾，插入镁条作引燃剂。","人员退至安全距离，戴好防护面罩，点燃镁条。","观察剧烈反应，熔融铁落入沙中冷却后回收。"],"tags":["高中"],"difficulty":3},
{"id":"sodium-water","name":"钠与水反应","category":"物质性质","hazard":3,"duration":"8 分钟","summary":"绿豆大的钠投入水中，出现“浮、熔、游、响、红”，直观展示钠的强还原性与低熔点。","principle":["2Na + 2H₂O  →  2NaOH + H₂↑","生成的 NaOH 使酚酞变红"],"reagents":["金属钠","蒸馏水","酚酞溶液","煤油"],"steps":["用镊子从煤油中取出钠，用滤纸吸干表面煤油。","在玻璃片上用小刀切下绿豆大小的一块，其余立即放回煤油中。","烧杯中加入水并滴入几滴酚酞，把钠块投入水中，迅速盖上玻璃片。","观察现象，反应结束后检验溶液酸碱性。"],"tags":["高中"],"difficulty":3},
{"id":"iron-burning","name":"铁丝在氧气中燃烧","category":"物质性质","hazard":2,"duration":"10 分钟","summary":"螺旋状铁丝末端系火柴，点燃后伸入氧气瓶，火星四射生成四氧化三铁。","principle":["3Fe + 2O₂  --点燃-->  Fe₃O₄"],"reagents":["细铁丝","氧气","火柴","细沙或水"],"steps":["集气瓶底铺一层细沙或留少量水。","把细铁丝绕成螺旋状，末端系一根火柴。","点燃火柴，待火柴快燃尽时，把铁丝伸入盛有氧气的集气瓶中。","观察燃烧现象，反应结束后取出铁丝。"],"tags":["初中"],"difficulty":2},
{"id":"paper-chromatography","name":"纸上层析分离色素","category":"分离提纯","hazard":1,"duration":"30 分钟","summary":"利用各组分在固定相与流动相中分配系数的差异，把墨水或叶绿体色素在滤纸上分离成不同色带。","principle":["分配系数不同 → 随展开剂移动的速率不同","Rf 值 = 斑点移动距离 ÷ 展开剂前沿移动距离"],"reagents":["滤纸条","黑墨水或叶绿体色素提取液","展开剂（水、乙醇、丙酮混合）"],"steps":["在滤纸条一端距底边 1 cm 处用铅笔轻画一条起点线。","用毛细管在起点线中央点样，晾干后重复点样 2–3 次，使斑点小而浓。","把滤纸条悬挂在层析缸中，使下端浸入展开剂，但液面必须低于样点。","密封层析缸，静置展开 20–30 分钟。","待展开剂前沿接近顶端时取出，立即用铅笔标出前沿位置，晾干观察。"],"tags":["高中"],"difficulty":1},
{"id":"starch-iodine","name":"淀粉与碘的显色","category":"物质性质","hazard":1,"duration":"8 分钟","summary":"淀粉遇碘变深蓝，加热褪色、冷却复蓝，是可逆的包合物形成过程。","principle":["淀粉螺旋结构把 I₂ 包合在空腔内，形成蓝色包合物","加热使螺旋松散，蓝色消失；冷却后恢复"],"reagents":["可溶性淀粉","碘液","蒸馏水"],"steps":["配制淀粉溶液：淀粉加少量冷水调成糊，再倒入沸水中煮沸至透明。","取 2 mL 淀粉溶液，滴入 1–2 滴碘液，观察颜色。","加热试管，观察颜色变化。","冷却后再观察颜色是否恢复。"],"tags":["初中"],"difficulty":1},
{"id":"protein-denaturation","name":"蛋白质变性","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"加热、重金属盐、强酸强碱、乙醇都能破坏蛋白质的空间结构，使其凝固或沉淀，且变性不可逆。","principle":["变性：氢键、二硫键、疏水作用被破坏，空间结构改变","肽键未断裂，一级结构不变，但生物活性丧失"],"reagents":["鸡蛋清稀释液","硫酸铜溶液","乙醇","浓盐酸","氢氧化钠溶液"],"steps":["取 5 支试管，各加入 2 mL 鸡蛋清稀释液。","第 1 支加热至沸腾；第 2 支加硫酸铜溶液；第 3 支加乙醇；第 4 支加浓盐酸；第 5 支加氢氧化钠溶液。","摇匀后静置，观察各管的凝固或沉淀现象。","向凝固的蛋白质中加水，观察能否重新溶解。"],"tags":["初中","高中"],"difficulty":1},
{"id":"extraction","name":"萃取与分液","category":"分离提纯","hazard":2,"duration":"20 分钟","summary":"用四氯化碳把碘从碘水中萃取出来，再通过分液漏斗分离两层液体，是分离提纯的基本操作。","principle":["碘在 CCl₄ 中的溶解度远大于在水中","萃取剂与原溶剂互不相溶，且密度不同"],"reagents":["碘水","四氯化碳（或煤油）","蒸馏水"],"steps":["检查分液漏斗是否漏水，关闭下端旋塞。","把碘水从上部倒入分液漏斗，再加入约 1/3 体积的四氯化碳。","塞紧上口塞子，右手压住塞子、左手握住旋塞，倒转漏斗用力振荡。","振荡过程中不时打开旋塞放气（漏斗口朝无人处）。","把漏斗放回铁圈静置，待液体分层清晰。","打开旋塞，下层液体从下口放出；上层液体从上口倒出。"],"tags":["高中"],"difficulty":3},
{"id":"distillation","name":"蒸馏分离乙醇与水","category":"分离提纯","hazard":2,"duration":"30 分钟","summary":"利用沸点差异，把乙醇-水混合物加热汽化再冷凝，收集 77–79 ℃ 的馏分。","principle":["乙醇沸点约 78.3 ℃，水沸点 100 ℃","汽化—冷凝实现组分分离"],"reagents":["乙醇-水混合液","沸石（碎瓷片）"],"steps":["检查装置气密性，把混合液加入蒸馏烧瓶，体积不超过容积的 2/3。","加入几粒沸石，防止暴沸。","温度计水银球与支管口下沿齐平。","冷凝水从下口进、上口出，先通水再加热。","小火加热，弃去开始馏出的少量液体（含低沸点杂质）。","收集 77–79 ℃ 的馏分，观察温度计读数是否稳定。"],"tags":["高中"],"difficulty":3},
{"id":"galvanic-cell","name":"原电池与电镀","category":"电化学","hazard":2,"duration":"25 分钟","summary":"锌-铜稀硫酸原电池让电流表指针偏转；再用铜片作阳极给铁片镀铜，理解电解池的工作原理。","principle":["原电池：Zn − 2e⁻ → Zn²⁺（负极）；2H⁺ + 2e⁻ → H₂↑（正极）","电镀：阳极 Cu − 2e⁻ → Cu²⁺；阴极 Cu²⁺ + 2e⁻ → Cu"],"reagents":["锌片","铜片","铁片","稀硫酸","硫酸铜电镀液","砂纸"],"steps":["用砂纸打磨锌片、铜片和铁片，除去氧化膜和油污。","把锌片和铜片插入盛有稀硫酸的烧杯中，用导线连接并串入电流表，观察指针。","观察铜片表面是否产生气泡，锌片是否逐渐溶解。","电镀：以硫酸铜溶液为电镀液，铁片接电源负极、铜片接正极，接通低压直流电。","电镀数分钟后取出铁片，观察表面颜色变化。"],"tags":["高中"],"difficulty":2},
{"id":"recrystallization","name":"重结晶提纯苯甲酸","category":"分离提纯","hazard":1,"duration":"35 分钟","summary":"利用苯甲酸溶解度随温度显著变化的特性，热水溶解、活性炭脱色、趁热过滤、冷却结晶，得到纯白色晶体。","principle":["苯甲酸在热水中溶解度大，冷水中溶解度小","冷却使溶质以晶体形式析出，杂质留在母液中"],"reagents":["粗苯甲酸","蒸馏水","活性炭","冰水"],"steps":["称取粗苯甲酸，加入约 60 mL 蒸馏水，加热至沸腾并搅拌至全部溶解。","加入少量活性炭，煮沸 5 分钟脱色。","趁热用预热过的漏斗过滤，滤液收集在烧杯中。","滤液自然冷却至室温，再用冰水浴冷却使晶体充分析出。","抽滤，用少量冰水洗涤晶体 2 次，压干。","把晶体转移到表面皿上，自然晾干后称重，计算回收率。"],"tags":["高中","大学"],"difficulty":2},
{"id":"heat-neutralization","name":"中和反应热的测定","category":"定量测量","hazard":1,"duration":"30 分钟","summary":"用保温杯式简易量热计测定稀盐酸与氢氧化钠中和放出的热量，计算中和热，理解“量热”这套定量思路。","principle":["H⁺(aq) + OH⁻(aq)  →  H₂O(l)   ΔH ≈ −57.3 kJ/mol","Q = c · m · ΔT，中和热 ΔH = −Q ÷ n(H₂O)"],"reagents":["1.0 mol/L 盐酸","1.0 mol/L 氢氧化钠溶液","蒸馏水"],"steps":["量取 50 mL 1.0 mol/L 盐酸倒入保温杯，盖上盖子，插入温度计，记录初始温度 t₁。","另量取 50 mL 1.0 mol/L 氢氧化钠溶液，测其温度，应与酸液相同（不足时用温水浴调平）。","把碱液迅速一次倒入保温杯，立即盖好，用搅拌棒上下匀速搅拌。","每隔 30 秒记录一次温度，读到温度上升到最高点并开始下降为止，取最高温度 t₂。","换用蒸馏水代替碱液重复一次，作为对照，比较温升差异。","计算 ΔT = t₂ − t₁，近似取溶液质量 100 g、比热容 4.18 J/(g·℃)，求 Q 与中和热。"],"tags":["高中","大学"],"difficulty":2},
{"id":"salt-purification","name":"粗盐提纯","category":"分离提纯","hazard":1,"duration":"25 分钟","summary":"粗盐里混着泥沙和少量可溶性盐。通过溶解、过滤、蒸发结晶，把不溶性杂质去掉，得到较纯的氯化钠晶体，并计算产率。","principle":["不溶性杂质：加水溶解后过滤除去","可溶性杂质：蒸发时大部分留在母液中，晶体表面再用少量蒸馏水洗涤"],"reagents":["粗盐约 5 g","蒸馏水约 20 mL"],"steps":["称取约 5 g 粗盐，倒入烧杯，加入约 20 mL 蒸馏水，用玻璃棒搅拌至不再溶解。","把滤纸对折两次，展开成圆锥形，放入漏斗，用蒸馏水润湿并轻压，使滤纸紧贴漏斗内壁。","漏斗下端管口紧靠烧杯内壁，玻璃棒斜靠在三层滤纸处，倾倒液体，液面低于滤纸边缘。","过滤后，滤纸上留下泥沙，滤液应澄清。","把滤液倒入蒸发皿，放在铁架台的泥三角上，用酒精灯加热，边加热边用玻璃棒搅拌。","出现大量晶体时停止加热，利用余热蒸干，避免晶体飞溅。","晶体冷却后称量，计算产率 = 所得晶体质量 ÷ 粗盐质量 × 100%。"],"tags":["初中","高中"],"difficulty":3},
{"id":"solution-prep","name":"配制一定物质的量浓度的溶液","category":"基础操作","hazard":1,"duration":"25 分钟","summary":"以配制 100 mL 0.100 mol/L 氯化钠溶液为例，练习计算、称量、溶解、转移、定容和摇匀这一整套容量瓶操作。","principle":["n = c × V；m(NaCl) = 0.100 mol/L × 0.100 L × 58.5 g/mol ≈ 0.585 g","定容后溶液的物质的量浓度由溶质的物质的量和溶液体积共同决定"],"reagents":["氯化钠（分析纯）","蒸馏水"],"steps":["计算：配制 100 mL 0.100 mol/L 溶液需要 NaCl 0.585 g。","用分析天平准确称取 0.585 g 氯化钠，倒入烧杯。","加约 30 mL 蒸馏水，用玻璃棒搅拌至完全溶解，冷却至室温。","把溶液沿玻璃棒小心转移进 100 mL 容量瓶，玻璃棒下端靠在瓶颈内壁。","用少量蒸馏水洗涤烧杯内壁和玻璃棒 2–3 次，洗涤液全部转入容量瓶，轻轻摇动。","继续加蒸馏水，至液面距刻度线 1–2 cm 时改用胶头滴管逐滴加入，直到凹液面最低处与刻度线相切。","盖紧瓶塞，倒转摇匀，装入试剂瓶并贴好标签。"],"tags":["高中","大学"],"difficulty":2},
{"id":"ion-tests","name":"常见离子的检验","category":"物质性质","hazard":1,"duration":"20 分钟","summary":"用一组对照实验区分氯离子、硫酸根、碳酸根和三价铁离子，理解“先排除干扰、再看特征现象”的检验逻辑。","principle":["Cl⁻ + Ag⁺  →  AgCl↓（白色，不溶于稀硝酸）","SO₄²⁻ + Ba²⁺  →  BaSO₄↓（白色，不溶于稀盐酸）","CO₃²⁻ + 2H⁺  →  CO₂↑ + H₂O，CO₂ 使澄清石灰水变浑浊","Fe³⁺ + 3SCN⁻  ⇌  Fe(SCN)₃（血红色）"],"reagents":["0.1 mol/L 氯化钠溶液","0.1 mol/L 硫酸钠溶液","0.1 mol/L 碳酸钠溶液","0.1 mol/L 氯化铁溶液","稀硝酸","稀盐酸","硝酸银溶液","氯化钡溶液","硫氰化钾溶液","澄清石灰水"],"steps":["取三支试管，分别加入少量氯化钠、硫酸钠、碳酸钠溶液。","第一支滴加硝酸银溶液和稀硝酸，出现白色沉淀且不溶解，说明含 Cl⁻。","第二支先加稀盐酸酸化，再滴加氯化钡溶液，出现白色沉淀，说明含 SO₄²⁻。","第三支滴加稀盐酸，把产生的气体通入澄清石灰水，石灰水变浑浊，说明含 CO₃²⁻。","取氯化铁溶液滴加硫氰化钾溶液，溶液变血红色，证明 Fe³⁺。","另取氯化亚铁溶液，滴加硫氰化钾无明显变化，再滴加氯水后变红，说明 Fe²⁺ 被氧化为 Fe³⁺。"],"tags":["高中","大学"],"difficulty":2},
{"id":"fe-steam","name":"铁与水蒸气的反应","category":"物质性质","hazard":2,"duration":"20 分钟","summary":"把红热的铁粉与水蒸气反应，用肥皂液收集生成的氢气并点燃，验证高温下铁与水也能反应。","principle":["3Fe + 4H₂O(g)  --高温-->  Fe₃O₄ + 4H₂↑","铁在常温下与水不反应，高温下才与水蒸气反应"],"reagents":["还原铁粉","蒸馏水","肥皂液"],"steps":["在硬质玻璃管底部放一团湿棉花，中部铺少量还原铁粉。","按图连接装置，导管末端伸入盛有肥皂液的蒸发皿中。","先均匀预热玻璃管，再集中加热铁粉处至红热。","湿棉花受热产生水蒸气，通过红热铁粉后进入肥皂液，吹出肥皂泡。","用燃着的火柴靠近肥皂泡，点燃收集到的气体。","反应结束后先撤导管，再停止加热，冷却后观察管内固体。"],"tags":["高中","大学"],"difficulty":3},
{"id":"al-naoh","name":"铝与氢氧化钠溶液的反应","category":"物质性质","hazard":2,"duration":"15 分钟","summary":"铝片在氢氧化钠溶液中持续冒出气泡并逐渐溶解，用点燃法确认气体是氢气，理解铝的两性。","principle":["2Al + 2NaOH + 2H₂O  →  2NaAlO₂ + 3H₂↑","铝表面的氧化铝膜同样能与强碱反应，因此铝没有“耐碱”的保护膜"],"reagents":["铝片","2 mol/L 氢氧化钠溶液","蒸馏水"],"steps":["取一片铝片，用砂纸打磨表面，除去氧化膜。","把铝片放入试管，加入约 5 mL 氢氧化钠溶液，微热。","观察铝片表面产生大量气泡，并逐渐变薄、溶解。","用排水法收集一试管气体，管口向下靠近火焰，检验纯度后点燃。","反应结束后，把剩余溶液稀释后处理。"],"tags":["高中","大学"],"difficulty":2},
{"id":"aloh3-amphoteric","name":"氢氧化铝的两性","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"用氨水制得氢氧化铝白色胶状沉淀，再分别加入盐酸和氢氧化钠，观察沉淀在酸、碱中都溶解。","principle":["AlCl₃ + 3NH₃·H₂O  →  Al(OH)₃↓ + 3NH₄Cl","Al(OH)₃ + 3HCl  →  AlCl₃ + 3H₂O","Al(OH)₃ + NaOH  →  NaAlO₂ + 2H₂O"],"reagents":["0.5 mol/L 氯化铝溶液","稀氨水","2 mol/L 盐酸","2 mol/L 氢氧化钠溶液"],"steps":["取两支试管，各加入约 2 mL 氯化铝溶液。","逐滴加入稀氨水并振荡，直到不再产生沉淀，得到白色胶状沉淀。","第一支试管中滴加稀盐酸，边加边振荡，观察沉淀是否溶解。","第二支试管中滴加氢氧化钠溶液，边加边振荡，观察沉淀是否溶解。","对比两支试管中沉淀溶解所需试剂的量。"],"tags":["高中","大学"],"difficulty":1},
{"id":"ammonia-fountain","name":"氨气的喷泉实验","category":"气体与燃烧","hazard":2,"duration":"15 分钟","summary":"把充满氨气的干燥烧瓶倒扣在酚酞溶液中，挤入少量水后打开止水夹，水迅速喷入瓶内形成红色喷泉。","principle":["NH₃ 极易溶于水，常温常压下 1 体积水约可溶解 700 体积氨","NH₃ + H₂O  ⇌  NH₃·H₂O  ⇌  NH₄⁺ + OH⁻，溶液显碱性"],"reagents":["浓氨水","碱石灰","酚酞溶液","蒸馏水"],"steps":["用浓氨水与碱石灰制取并收集一烧瓶干燥氨气，用向下排空气法，瓶口塞紧。","把烧瓶倒扣固定在铁架台上，尖嘴玻璃管伸入盛有酚酞溶液的烧杯中。","挤压胶头滴管，使少量蒸馏水进入烧瓶。","打开止水夹，观察烧杯中的水沿玻璃管上升并喷入烧瓶。","水进入烧瓶后变成红色，形成喷泉。"],"tags":["高中","大学"],"difficulty":2},
{"id":"hcl-nh3-smoke","name":"氯化氢与氨气的“白烟”","category":"气体与燃烧","hazard":2,"duration":"10 分钟","summary":"两根玻璃棒分别蘸取浓盐酸和浓氨水，在空气中靠近，挥发出的气体化合成氯化铵，产生大量白烟。","principle":["NH₃(g) + HCl(g)  →  NH₄Cl(s)","浓盐酸和浓氨水都易挥发，在空气中相遇即反应"],"reagents":["浓盐酸","浓氨水"],"steps":["在通风橱内取两根干净玻璃棒。","一根蘸取少量浓盐酸，另一根蘸取少量浓氨水。","把两根玻璃棒慢慢靠近，但不要接触。","观察两根玻璃棒之间出现的白烟。","实验结束后把玻璃棒洗净，废液回收。"],"tags":["高中"],"difficulty":2},
{"id":"h2-combustion","name":"氢气的验纯与燃烧","category":"气体与燃烧","hazard":2,"duration":"10 分钟","summary":"用排水法收集一试管氢气，通过点燃时的声音判断纯度，再点燃导管口氢气，用干冷烧杯收集燃烧产物。","principle":["2H₂ + O₂  --点燃-->  2H₂O","氢气与空气混合达到爆炸极限时点燃会剧烈爆鸣"],"reagents":["锌粒","稀硫酸","蒸馏水"],"steps":["用锌粒与稀硫酸反应制取氢气，排水法收集一试管。","用拇指堵住试管口，移近火焰，松开拇指，听声音。","若发出尖锐爆鸣声，说明氢气不纯，需重新收集；声音很小则较纯。","验纯后，在导管口点燃氢气，观察火焰颜色。","在火焰上方罩一个干冷烧杯，观察烧杯内壁。"],"tags":["初中","高中"],"difficulty":2},
{"id":"ethanol-oxidation","name":"乙醇的催化氧化","category":"有机","hazard":2,"duration":"15 分钟","summary":"把铜丝在酒精灯上灼烧变黑，再插入乙醇中变红，反复几次后闻到刺激性气味，验证乙醇被氧化成乙醛。","principle":["2Cu + O₂  --Δ-->  2CuO","CH₃CH₂OH + CuO  --Δ-->  CH₃CHO + Cu + H₂O","总反应：2CH₃CH₂OH + O₂  --Cu/Δ-->  2CH₃CHO + 2H₂O"],"reagents":["无水乙醇","铜丝"],"steps":["把铜丝一端绕成螺旋状，用坩埚钳夹住另一端。","在酒精灯外焰上加热铜丝，表面变黑。","迅速把红热的铜丝插入盛有少量乙醇的试管中，观察铜丝颜色变化。","取出铜丝再次灼烧、插入，重复 3–5 次。","取下试管，用手轻轻扇动，闻气味。"],"tags":["高中","大学"],"difficulty":2},
{"id":"glucose-fehlings","name":"葡萄糖的还原性","category":"有机","hazard":1,"duration":"20 分钟","summary":"新制氢氧化铜悬浊液与葡萄糖溶液共热，蓝色悬浊液变成砖红色氧化亚铜沉淀，证明葡萄糖含醛基。","principle":["CH₂OH(CHOH)₄CHO + 2Cu(OH)₂  --Δ-->  CH₂OH(CHOH)₄COOH + Cu₂O↓ + 2H₂O","醛基能被弱氧化剂氢氧化铜氧化，生成砖红色 Cu₂O"],"reagents":["10% 葡萄糖溶液","5% 氢氧化钠溶液","5% 硫酸铜溶液"],"steps":["取一支试管，加入约 2 mL 氢氧化钠溶液。","滴加几滴硫酸铜溶液，振荡，得到蓝色氢氧化铜悬浊液（氢氧化钠要过量）。","加入约 1 mL 葡萄糖溶液，振荡混匀。","用酒精灯加热试管底部，观察颜色变化。","记录沉淀颜色和出现的时间。"],"tags":["高中"],"difficulty":1},
{"id":"sucrose-hydrolysis","name":"蔗糖的水解","category":"有机","hazard":1,"duration":"25 分钟","summary":"蔗糖本身不是还原糖，用稀硫酸水解后先中和酸，再用新制氢氧化铜检验，出现砖红色沉淀说明生成了葡萄糖和果糖。","principle":["C₁₂H₂₂O₁₁ + H₂O  --H₂SO₄/Δ-->  C₆H₁₂O₆（葡萄糖）+ C₆H₁₂O₆（果糖）","蔗糖无醛基，水解产物含醛基，可用新制氢氧化铜检验"],"reagents":["10% 蔗糖溶液","稀硫酸","5% 氢氧化钠溶液","5% 硫酸铜溶液"],"steps":["取两支试管，各加入约 2 mL 蔗糖溶液。","第一支直接加新制氢氧化铜悬浊液，加热，观察现象。","第二支加入约 1 mL 稀硫酸，水浴加热约 5 分钟。","冷却后，向第二支试管中逐滴加入氢氧化钠溶液，直到溶液呈碱性。","加入新制氢氧化铜悬浊液，加热，观察现象。"],"tags":["高中"],"difficulty":1},
{"id":"protein-salting","name":"蛋白质的盐析与变性","category":"有机","hazard":1,"duration":"15 分钟","summary":"向鸡蛋清中加入饱和硫酸铵溶液，蛋白质析出白色沉淀，加水后又重新溶解；对比加热后的沉淀不能再溶解，区分盐析与变性。","principle":["盐析：加入高浓度轻金属盐，降低蛋白质溶解度而析出，是可逆的物理过程","变性：加热、重金属盐、强酸强碱等破坏蛋白质空间结构，是不可逆的化学过程"],"reagents":["鸡蛋清稀释液","饱和硫酸铵溶液","蒸馏水"],"steps":["取两支试管，各加入约 2 mL 稀释鸡蛋清。","第一支逐滴加入饱和硫酸铵溶液，振荡，观察白色沉淀。","向第一支试管中加水并振荡，观察沉淀是否重新溶解。","第二支用酒精灯加热，观察蛋白质凝固。","向第二支试管中加水，观察沉淀是否溶解。"],"tags":["高中"],"difficulty":1},
{"id":"ester-hydrolysis","name":"乙酸乙酯的水解","category":"有机","hazard":1,"duration":"20 分钟","summary":"三支试管分别用水、稀硫酸和氢氧化钠溶液与乙酸乙酯共热，比较酯层消失的快慢，理解酯水解的可逆性与碱的促进作用。","principle":["CH₃COOC₂H₅ + H₂O  ⇌  CH₃COOH + C₂H₅OH（酸催化，可逆）","CH₃COOC₂H₅ + NaOH  →  CH₃COONa + C₂H₅OH（碱性条件，趋于完全）"],"reagents":["乙酸乙酯","稀硫酸","2 mol/L 氢氧化钠溶液","蒸馏水"],"steps":["取三支试管，分别加入 2 mL 蒸馏水、稀硫酸、氢氧化钠溶液。","向每支试管中滴加约 0.5 mL 乙酸乙酯，轻轻振荡，观察酯层。","把三支试管同时放入约 70 ℃ 水浴中加热 5 分钟。","取出试管，比较酯层剩余量和气味变化。","记录哪支试管中酯层消失得最快。"],"tags":["高中","大学"],"difficulty":1},
{"id":"electrolysis-brine","name":"电解饱和食盐水","category":"电化学","hazard":2,"duration":"25 分钟","summary":"用石墨和铁作电极电解饱和食盐水，阳极产生氯气、阴极产生氢气，阴极区溶液变红，复现氯碱工业的基本原理。","principle":["2NaCl + 2H₂O  --通电-->  2NaOH + H₂↑ + Cl₂↑","阳极：2Cl⁻ − 2e⁻ → Cl₂↑；阴极：2H₂O + 2e⁻ → H₂↑ + 2OH⁻"],"reagents":["饱和食盐水","酚酞溶液","淀粉碘化钾试纸"],"steps":["向 U 形管中加入饱和食盐水，滴入几滴酚酞。","一侧插入石墨电极接电源正极，另一侧插入铁电极接电源负极。","接通 12 V 直流电，观察两极现象。","用湿润的淀粉碘化钾试纸靠近阳极上方，观察颜色变化。","用倒扣的小试管在阴极收集气体，验纯后点燃。"],"tags":["高中","大学"],"difficulty":2},
{"id":"sacrificial-anode","name":"牺牲阳极的阴极保护","category":"电化学","hazard":1,"duration":"20 分钟","summary":"在含酚酞和铁氰化钾的琼脂凝胶中，铁钉与锌接触处不受腐蚀、与铜接触处明显腐蚀，直观演示牺牲阳极保护法。","principle":["原电池中较活泼金属作负极被氧化，较不活泼金属作正极被保护","Fe²⁺ 与 [Fe(CN)₆]³⁻ 生成蓝色沉淀；OH⁻ 使酚酞变红"],"reagents":["琼脂","饱和食盐水","酚酞溶液","铁氰化钾溶液","铁钉","锌片","铜片"],"steps":["用砂纸把铁钉、锌片、铜片表面打磨干净。","在培养皿中放好铁钉，一端缠锌片，另一端缠铜片，彼此接触。","把琼脂与食盐水加热溶解，加入少量酚酞和铁氰化钾溶液，搅匀。","趁热把凝胶倒入培养皿，浸没金属，冷却凝固。","静置 10–20 分钟，观察各处的颜色变化。"],"tags":["高中","大学"],"difficulty":1},
{"id":"pbi2-equilibrium","name":"碘化铅的沉淀溶解平衡","category":"沉淀溶解平衡","hazard":2,"duration":"20 分钟","summary":"制备黄色碘化铅沉淀，通过加热溶解、冷却析出金色晶体，观察沉淀溶解平衡随温度移动，顺便收获“黄金雨”。","principle":["Pb²⁺ + 2I⁻  ⇌  PbI₂(s)","碘化铅的溶解度随温度升高明显增大，冷却时重新析出晶体"],"reagents":["0.1 mol/L 硝酸铅溶液","0.1 mol/L 碘化钾溶液","蒸馏水"],"steps":["取一支试管，加入约 3 mL 硝酸铅溶液。","逐滴加入碘化钾溶液，边加边振荡，观察黄色沉淀。","继续滴加碘化钾至沉淀不再增多，静置。","用酒精灯水浴加热试管，观察沉淀逐渐溶解。","把试管放入冷水中冷却，观察金黄色片状晶体析出。"],"tags":["高中","大学"],"difficulty":2},
{"id":"cuammine","name":"铜氨配合物的形成","category":"配位化学","hazard":2,"duration":"15 分钟","summary":"向硫酸铜溶液中滴加氨水，先出现蓝色沉淀，氨水过量后沉淀溶解成深蓝色溶液，加乙醇析出深蓝色晶体。","principle":["CuSO₄ + 2NH₃·H₂O  →  Cu(OH)₂↓ + (NH₄)₂SO₄","Cu(OH)₂ + 4NH₃  →  [Cu(NH₃)₄]²⁺ + 2OH⁻（深蓝色）"],"reagents":["0.2 mol/L 硫酸铜溶液","2 mol/L 氨水","95% 乙醇"],"steps":["取一支试管，加入约 2 mL 硫酸铜溶液。","逐滴加入氨水，振荡，观察蓝色沉淀生成。","继续滴加氨水至过量，观察沉淀溶解、溶液变深蓝。","向深蓝色溶液中加入约 2 mL 乙醇，静置。","观察析出的深蓝色晶体。"],"tags":["高中","大学"],"difficulty":2},
{"id":"kmno4-h2o2","name":"高锰酸钾滴定双氧水","category":"定量测量","hazard":2,"duration":"25 分钟","summary":"用稀硫酸酸化的高锰酸钾标准液滴定稀释后的双氧水，利用高锰酸钾自身的紫红色判断终点，测定过氧化氢的浓度。","principle":["2MnO₄⁻ + 5H₂O₂ + 6H⁺  →  2Mn²⁺ + 5O₂↑ + 8H₂O","n(H₂O₂) = 5/2 × n(KMnO₄)"],"reagents":["0.0200 mol/L 高锰酸钾标准溶液","待测双氧水","3 mol/L 硫酸","蒸馏水"],"steps":["用移液管移取 10.00 mL 双氧水，定容稀释到 100 mL。","再移取 20.00 mL 稀释液于锥形瓶，加入约 5 mL 3 mol/L 硫酸酸化。","用高锰酸钾标准液滴定，边滴边振荡，溶液紫红色逐渐褪去。","当滴入最后一滴后溶液呈浅粉红色且 30 秒不褪色，即为终点。","记录消耗的高锰酸钾体积，重复滴定 2–3 次。","计算双氧水的物质的量浓度。"],"tags":["高中","大学"],"difficulty":3},
{"id":"fruit-battery","name":"水果电池","category":"电化学","hazard":1,"duration":"15 分钟","summary":"把锌片和铜片插入柠檬或苹果中，用导线连接电压表或发光二极管，观察化学能转化为电能。","principle":["锌比铜活泼，作负极：Zn − 2e⁻ → Zn²⁺","铜作正极，果汁中的氢离子等得电子；电子经外电路从锌流向铜"],"reagents":["柠檬或苹果"],"steps":["用砂纸把锌片和铜片打磨光亮。","把两种金属片相隔约 1 cm 插入同一个水果中。","用导线把锌片和铜片分别接到电压表的两端，观察读数。","把 3–4 个水果电池串联，接发光二极管，观察是否发光。","改变金属片间距、插入深度，比较电压变化。"],"tags":["初中","高中"],"difficulty":1},
{"id":"hydrogen-burn","name":"氢气的燃烧","category":"气体与燃烧","hazard":2,"duration":"10 min","summary":"点燃纯净氢气，观察淡蓝色火焰并检验产物。","principle":["2H₂ + O₂ →(点燃) 2H₂O"],"reagents":["锌粒","稀硫酸","无水硫酸铜"],"steps":["制取氢气并验纯。","在尖嘴导管口点燃氢气。","将干燥烧杯罩在火焰上方。","观察烧杯内壁并加入无水硫酸铜。"],"tags":["燃烧","验纯","产物检验"],"difficulty":2},
{"id":"co2-extinguish","name":"二氧化碳灭火","category":"气体与燃烧","hazard":1,"duration":"10 min","summary":"向阶梯蜡烛倾倒二氧化碳，观察低处蜡烛先熄灭。","principle":["CO₂ 密度大于空气，不燃烧也不支持燃烧。"],"reagents":["大理石","稀盐酸","蜡烛"],"steps":["制取并收集满二氧化碳。","点燃阶梯蜡烛。","将二氧化碳沿烧杯壁缓慢倒入。","观察两支蜡烛的熄灭顺序。"],"tags":["灭火","密度","阶梯蜡烛"],"difficulty":1},
{"id":"oxygen-glow","name":"氧气的助燃性","category":"气体与燃烧","hazard":2,"duration":"10 min","summary":"把带火星木条伸入氧气中，观察复燃。","principle":["氧气支持燃烧，使带火星木条复燃。"],"reagents":["高锰酸钾","带火星木条"],"steps":["加热高锰酸钾制取氧气。","排水法收集一瓶氧气。","将带火星木条伸入瓶中。","观察木条燃烧情况。"],"tags":["助燃","检验","制氧"],"difficulty":2},
{"id":"so2-bleach","name":"二氧化硫的漂白性","category":"气体与燃烧","hazard":2,"duration":"15 min","summary":"将二氧化硫通入品红溶液，观察褪色及加热复色。","principle":["SO₂ 与品红结合生成不稳定无色物质，加热后分解。"],"reagents":["亚硫酸钠","稀硫酸","品红溶液"],"steps":["亚硫酸钠与稀硫酸反应制取二氧化硫。","将气体通入品红溶液。","观察颜色变化。","加热褪色后的溶液。"],"tags":["漂白","可逆","尾气吸收"],"difficulty":2},
{"id":"chlorine-bleach","name":"氯水的漂白性","category":"气体与燃烧","hazard":2,"duration":"15 min","summary":"将氯水滴在有色布条上，观察褪色。","principle":["Cl₂ + H₂O ⇌ HCl + HClO，HClO 具有强氧化性。"],"reagents":["氯水","红布条","蓝色石蕊试纸"],"steps":["取少量新制氯水。","滴在红布条上。","另取蓝色石蕊试纸滴加氯水。","观察颜色变化。"],"tags":["漂白","次氯酸","不可逆"],"difficulty":2},
{"id":"no2-dimer","name":"二氧化氮与四氧化二氮","category":"气体与燃烧","hazard":2,"duration":"10 min","summary":"观察二氧化氮气体在冷热条件下的颜色变化。","principle":["2NO₂ ⇌ N₂O₄，正反应放热。"],"reagents":["铜片","浓硝酸"],"steps":["铜与浓硝酸反应制取二氧化氮。","收集气体于圆底烧瓶中密封。","将烧瓶浸入热水，观察颜色。","再浸入冰水，观察颜色。"],"tags":["平衡移动","颜色变化","有毒气体"],"difficulty":2},
{"id":"h2s-precip","name":"硫化氢的沉淀反应","category":"气体与燃烧","hazard":3,"duration":"15 min","summary":"将硫化氢通入硫酸铜溶液，生成黑色硫化铜沉淀。","principle":["H₂S + CuSO₄ → CuS↓ + H₂SO₄"],"reagents":["硫化亚铁","稀硫酸","硫酸铜溶液"],"steps":["硫化亚铁与稀硫酸反应制取硫化氢。","将气体通入硫酸铜溶液。","观察沉淀颜色。","尾气用氢氧化钠溶液吸收。"],"tags":["硫化物","沉淀","剧毒"],"difficulty":3},
{"id":"co-reduction","name":"一氧化碳还原氧化铜","category":"气体与燃烧","hazard":3,"duration":"20 min","summary":"一氧化碳通过灼热氧化铜，观察黑色固体变红。","principle":["CO + CuO →(Δ) Cu + CO₂"],"reagents":["甲酸","浓硫酸","氧化铜"],"steps":["甲酸与浓硫酸反应制取一氧化碳。","先通一氧化碳排尽空气，再加热氧化铜。","观察固体颜色变化。","尾气点燃或用气球收集。"],"tags":["还原","一氧化碳","尾气处理"],"difficulty":3},
{"id":"carbonate-test","name":"碳酸根离子的检验","category":"物质性质","hazard":1,"duration":"10 min","summary":"向待测液加稀盐酸，产生能使石灰水变浑浊的气体。","principle":["CO₃²⁻ + 2H⁺ → H₂O + CO₂↑","CO₂ + Ca(OH)₂ → CaCO₃↓ + H₂O"],"reagents":["碳酸钠溶液","稀盐酸","澄清石灰水"],"steps":["取少量待测液于试管中。","加入稀盐酸。","将产生的气体通入澄清石灰水。","观察石灰水变化。"],"tags":["离子检验","二氧化碳","碳酸盐"],"difficulty":1},
{"id":"sulfate-test","name":"硫酸根离子的检验","category":"物质性质","hazard":1,"duration":"10 min","summary":"向待测液加氯化钡溶液和稀盐酸，生成白色沉淀。","principle":["Ba²⁺ + SO₄²⁻ → BaSO₄↓"],"reagents":["硫酸钠溶液","氯化钡溶液","稀盐酸"],"steps":["取少量待测液。","先加稀盐酸酸化。","再加氯化钡溶液。","观察沉淀生成。"],"tags":["离子检验","硫酸根","钡盐"],"difficulty":1},
{"id":"chloride-test","name":"氯离子的检验","category":"物质性质","hazard":1,"duration":"10 min","summary":"向待测液加硝酸银溶液和稀硝酸，生成白色沉淀。","principle":["Ag⁺ + Cl⁻ → AgCl↓"],"reagents":["氯化钠溶液","硝酸银溶液","稀硝酸"],"steps":["取少量待测液。","加入稀硝酸酸化。","滴加硝酸银溶液。","观察沉淀并避光。"],"tags":["离子检验","氯离子","卤化银"],"difficulty":1},
{"id":"ammonium-test","name":"铵根离子的检验","category":"物质性质","hazard":1,"duration":"10 min","summary":"向待测液加氢氧化钠溶液并加热，用湿润红色石蕊试纸检验氨气。","principle":["NH₄⁺ + OH⁻ →(Δ) NH₃↑ + H₂O"],"reagents":["氯化铵溶液","氢氧化钠溶液","红色石蕊试纸"],"steps":["取少量待测液。","加入氢氧化钠溶液。","加热试管。","用湿润红色石蕊试纸靠近管口。"],"tags":["离子检验","铵根","氨气"],"difficulty":1},
{"id":"fe3-scn","name":"铁离子的硫氰化钾检验","category":"物质性质","hazard":1,"duration":"10 min","summary":"向氯化铁溶液滴加硫氰化钾溶液，溶液变血红色。","principle":["Fe³⁺ + 3SCN⁻ ⇌ Fe(SCN)₃"],"reagents":["氯化铁溶液","硫氰化钾溶液"],"steps":["取少量氯化铁溶液。","滴加硫氰化钾溶液。","观察颜色变化。","与氯化亚铁溶液对比。"],"tags":["离子检验","铁离子","配位"],"difficulty":1},
{"id":"fe2-fe3","name":"亚铁离子与铁离子的转化","category":"物质性质","hazard":1,"duration":"15 min","summary":"用氯水和铁粉实现亚铁离子与铁离子的相互转化。","principle":["2Fe²⁺ + Cl₂ → 2Fe³⁺ + 2Cl⁻","2Fe³⁺ + Fe → 3Fe²⁺"],"reagents":["硫酸亚铁溶液","氯水","铁粉","硫氰化钾溶液"],"steps":["取硫酸亚铁溶液，滴加硫氰化钾，观察。","加入少量氯水，观察颜色。","另取铁离子溶液，加入铁粉振荡。","再次用硫氰化钾检验。"],"tags":["氧化还原","铁离子","转化"],"difficulty":1},
{"id":"halogen-displacement","name":"卤素单质的置换","category":"物质性质","hazard":2,"duration":"15 min","summary":"氯水分别加入溴化钠和碘化钾溶液，观察颜色变化。","principle":["Cl₂ + 2Br⁻ → Br₂ + 2Cl⁻","Cl₂ + 2I⁻ → I₂ + 2Cl⁻"],"reagents":["氯水","溴化钠溶液","碘化钾溶液","四氯化碳"],"steps":["取溴化钠溶液，滴加氯水。","加入四氯化碳振荡，观察有机层。","另取碘化钾溶液重复实验。","比较颜色。"],"tags":["置换","卤素","萃取"],"difficulty":2},
{"id":"metal-activity","name":"金属活动性顺序","category":"物质性质","hazard":1,"duration":"15 min","summary":"将锌、铁、铜分别放入稀盐酸和硫酸铜溶液，比较反应现象。","principle":["金属活动性：Zn > Fe > Cu"],"reagents":["锌粒","铁钉","铜片","稀盐酸","硫酸铜溶液"],"steps":["三种金属分别加入稀盐酸。","观察气泡产生速率。","另取三种金属加入硫酸铜溶液。","观察置换现象。"],"tags":["活动性","置换","对比实验"],"difficulty":1},
{"id":"nahco3-thermal","name":"碳酸氢钠的热稳定性","category":"物质性质","hazard":1,"duration":"15 min","summary":"分别加热碳酸钠和碳酸氢钠，用石灰水检验产物。","principle":["2NaHCO₃ →(Δ) Na₂CO₃ + H₂O + CO₂↑"],"reagents":["碳酸钠","碳酸氢钠","澄清石灰水"],"steps":["按套管装置分别装入两种固体。","同时加热。","将气体分别通入石灰水。","比较现象。"],"tags":["热稳定性","对比","碳酸盐"],"difficulty":1},
{"id":"kmno4-thermal","name":"高锰酸钾的热分解","category":"物质性质","hazard":1,"duration":"10 min","summary":"加热高锰酸钾，观察紫色晶体变为黑色并放出氧气。","principle":["2KMnO₄ →(Δ) K₂MnO₄ + MnO₂ + O₂↑"],"reagents":["高锰酸钾"],"steps":["取少量高锰酸钾于试管中。","加热试管底部。","将带火星木条伸入管口。","观察固体颜色变化。"],"tags":["热分解","制氧","氧化剂"],"difficulty":1},
{"id":"na2o2-water","name":"过氧化钠与水反应","category":"物质性质","hazard":2,"duration":"10 min","summary":"将过氧化钠加入水中，用带火星木条检验氧气。","principle":["2Na₂O₂ + 2H₂O → 4NaOH + O₂↑"],"reagents":["过氧化钠","蒸馏水","酚酞"],"steps":["取少量过氧化钠于试管中。","加入蒸馏水。","迅速用带火星木条检验气体。","滴加酚酞观察溶液酸碱性。"],"tags":["过氧化物","氧气","强氧化剂"],"difficulty":2},
{"id":"na2o2-co2","name":"过氧化钠与二氧化碳反应","category":"物质性质","hazard":2,"duration":"10 min","summary":"将二氧化碳通入盛有过氧化钠的装置，检验生成的氧气。","principle":["2Na₂O₂ + 2CO₂ → 2Na₂CO₃ + O₂↑"],"reagents":["过氧化钠","大理石","稀盐酸"],"steps":["制取并干燥二氧化碳。","将气体通过盛有过氧化钠的干燥管。","收集出口气体。","用带火星木条检验。"],"tags":["供氧","过氧化物","二氧化碳"],"difficulty":2},
{"id":"al-oxide-film","name":"铝表面的氧化膜","category":"物质性质","hazard":1,"duration":"15 min","summary":"对比铝片与打磨铝片在硫酸铜溶液中的反应。","principle":["Al₂O₃ 致密氧化膜保护铝；除去后铝可置换铜。"],"reagents":["铝片","砂纸","硫酸铜溶液","氯化汞溶液"],"steps":["取一片铝片直接放入硫酸铜溶液。","另取铝片用砂纸打磨后放入。","观察表面变化。","比较反应速率。"],"tags":["氧化膜","铝","对比"],"difficulty":1},
{"id":"electrolysis-cuso4","name":"电解硫酸铜溶液","category":"电化学","hazard":2,"duration":"20 min","summary":"用石墨电极电解硫酸铜溶液，观察两极产物。","principle":["阴极：2Cu²⁺ + 4e⁻ → 2Cu","阳极：2H₂O - 4e⁻ → O₂↑ + 4H⁺"],"reagents":["硫酸铜溶液","石墨电极"],"steps":["硫酸铜溶液倒入电解槽。","插入两根石墨电极，连接直流电源。","通电 10 分钟，观察两极。","检验阳极气体。"],"tags":["电解","铜","氧气"],"difficulty":2},
{"id":"electroplating-copper","name":"电镀铜","category":"电化学","hazard":2,"duration":"20 min","summary":"以铜片为阳极、铁片为阴极，在硫酸铜溶液中电镀铜。","principle":["阳极：Cu - 2e⁻ → Cu²⁺","阴极：Cu²⁺ + 2e⁻ → Cu"],"reagents":["硫酸铜溶液","铜片","铁片","砂纸"],"steps":["铁片用砂纸打磨除锈，水洗。","铜片接电源正极，铁片接负极。","浸入硫酸铜溶液，通电 10 分钟。","取出铁片，观察镀层。"],"tags":["电镀","电解","铜"],"difficulty":2},
{"id":"fuel-cell","name":"氢氧燃料电池","category":"电化学","hazard":2,"duration":"20 min","summary":"用吸附氢和氧的电极组装燃料电池，驱动小风扇。","principle":["负极：2H₂ - 4e⁻ → 4H⁺","正极：O₂ + 4e⁻ + 4H⁺ → 2H₂O"],"reagents":["稀硫酸","氢气","氧气"],"steps":["向燃料电池电极分别通入氢气和氧气。","连接小风扇。","观察风扇转动。","记录电压。"],"tags":["燃料电池","能量转化","氢气"],"difficulty":2},
{"id":"corrosion-oxygen","name":"铁的吸氧腐蚀","category":"电化学","hazard":1,"duration":"20 min","summary":"铁钉在氯化钠溶液中生锈，观察液面上升。","principle":["负极：Fe - 2e⁻ → Fe²⁺","正极：O₂ + 2H₂O + 4e⁻ → 4OH⁻"],"reagents":["铁钉","氯化钠溶液","琼脂","酚酞","铁氰化钾"],"steps":["铁钉置于培养皿中，加入含酚酞和铁氰化钾的琼脂。","密封后观察。","记录液面变化和颜色。","放置数小时。"],"tags":["腐蚀","吸氧","电化学"],"difficulty":1},
{"id":"corrosion-acid","name":"铁的析氢腐蚀","category":"电化学","hazard":1,"duration":"15 min","summary":"铁钉在稀盐酸中产生气泡，观察腐蚀速率。","principle":["负极：Fe - 2e⁻ → Fe²⁺","正极：2H⁺ + 2e⁻ → H₂↑"],"reagents":["铁钉","稀盐酸","氯化钠"],"steps":["铁钉放入稀盐酸中。","观察气泡产生。","比较加氯化钠后的速率。","记录现象。"],"tags":["腐蚀","析氢","酸"],"difficulty":1},
{"id":"electrolysis-ki","name":"电解碘化钾溶液","category":"电化学","hazard":2,"duration":"15 min","summary":"电解碘化钾溶液，阳极析出碘，阴极产生氢气。","principle":["阳极：2I⁻ - 2e⁻ → I₂","阴极：2H₂O + 2e⁻ → H₂↑ + 2OH⁻"],"reagents":["碘化钾溶液","淀粉溶液","石墨电极"],"steps":["碘化钾溶液加入少量淀粉。","插入石墨电极，通电。","观察两极现象。","检验阴极气体。"],"tags":["电解","碘","淀粉"],"difficulty":2},
{"id":"filtration","name":"过滤操作","category":"基础操作","hazard":1,"duration":"10 min","summary":"用漏斗和滤纸分离不溶性固体与液体。","principle":["利用滤纸孔隙截留固体颗粒。"],"reagents":["浑浊的碳酸钙悬浊液"],"steps":["滤纸对折两次，放入漏斗，用水润湿。","漏斗下端管口紧靠烧杯内壁。","玻璃棒引流，将悬浊液缓慢倒入。","用少量蒸馏水洗涤烧杯和滤纸。"],"tags":["过滤","分离","基本操作"],"difficulty":1},
{"id":"evaporation","name":"蒸发结晶","category":"基础操作","hazard":1,"duration":"15 min","summary":"加热食盐水，蒸发溶剂得到食盐晶体。","principle":["溶剂挥发使溶液达到过饱和而结晶。"],"reagents":["饱和食盐水"],"steps":["食盐水倒入蒸发皿，不超过容积的三分之二。","加热并用玻璃棒不断搅拌。","出现较多固体时停止加热。","利用余热蒸干，冷却称量。"],"tags":["蒸发","结晶","基本操作"],"difficulty":1},
{"id":"decantation","name":"倾析法分离","category":"基础操作","hazard":1,"duration":"10 min","summary":"静置后倾出上层清液，与沉淀分离。","principle":["利用密度差使固体沉降，倾出清液。"],"reagents":["氢氧化铁悬浊液"],"steps":["悬浊液静置至沉淀沉降。","沿玻璃棒缓慢倾出上层清液。","再加入蒸馏水洗涤沉淀。","重复倾析。"],"tags":["倾析","分离","洗涤"],"difficulty":1},
{"id":"precipitate-washing","name":"沉淀的洗涤","category":"基础操作","hazard":1,"duration":"15 min","summary":"用蒸馏水洗涤硫酸钡沉淀，检验洗涤是否完全。","principle":["洗涤除去沉淀表面吸附的可溶性杂质。"],"reagents":["含氯化钠的硫酸钡沉淀","硝酸银溶液"],"steps":["沉淀转入漏斗，加入蒸馏水。","让水自然流下。","收集最后一次洗涤液。","滴加硝酸银溶液检验氯离子。"],"tags":["洗涤","检验","沉淀"],"difficulty":1},
{"id":"weighing","name":"托盘天平称量","category":"基础操作","hazard":1,"duration":"10 min","summary":"用托盘天平称取一定质量的氯化钠。","principle":["等臂天平通过砝码与游码平衡称量。"],"reagents":["氯化钠"],"steps":["天平放平，游码归零，调节平衡螺母。","左盘放称量纸，右盘放砝码。","用药匙加减药品至平衡。","记录质量，清理天平。"],"tags":["称量","天平","基本操作"],"difficulty":1},
{"id":"volumetric-flask","name":"容量瓶配制溶液","category":"基础操作","hazard":1,"duration":"20 min","summary":"配制 100 mL 0.1 mol/L 氯化钠溶液。","principle":["溶质物质的量浓度等于溶质物质的量除以溶液体积。"],"reagents":["氯化钠","蒸馏水"],"steps":["计算并称取 0.585 g 氯化钠。","在烧杯中溶解，冷却至室温。","转移至容量瓶，洗涤烧杯和玻璃棒 2–3 次。","加水至刻度线 1–2 cm 处，改用滴管定容，摇匀。"],"tags":["容量瓶","定容","浓度"],"difficulty":1},
{"id":"pipette","name":"移液管的使用","category":"基础操作","hazard":1,"duration":"15 min","summary":"用移液管准确移取 25.00 mL 溶液。","principle":["移液管容积固定，用于准确移取一定体积液体。"],"reagents":["待测溶液"],"steps":["移液管用待取液润洗 2–3 次。","用洗耳球吸取溶液至刻度线以上。","松开食指，让液面降至刻度线。","将液体放入烧杯，管尖靠壁。"],"tags":["移液管","准确量取","基本操作"],"difficulty":1},
{"id":"burette","name":"滴定管的使用","category":"基础操作","hazard":1,"duration":"20 min","summary":"练习酸式滴定管的润洗、排气、读数与滴加。","principle":["滴定管可精确控制滴加体积，用于滴定分析。"],"reagents":["待装溶液"],"steps":["检查活塞是否漏水。","用待装液润洗 2–3 次。","装液至零刻度以上，排出气泡。","调节液面至零刻度，记录初读数。"],"tags":["滴定管","滴定","基本操作"],"difficulty":1},
{"id":"gas-collection","name":"气体的收集方法","category":"基础操作","hazard":1,"duration":"15 min","summary":"用排水法、向上排空气法和向下排空气法收集不同气体。","principle":["根据气体密度和溶解性选择收集方法。"],"reagents":["氧气","二氧化碳","氢气"],"steps":["排水法收集氧气。","向上排空气法收集二氧化碳。","向下排空气法收集氢气。","比较收集方法的适用条件。"],"tags":["收集","气体","方法选择"],"difficulty":1},
{"id":"sublimation","name":"升华法提纯碘","category":"分离提纯","hazard":2,"duration":"15 min","summary":"加热碘与杂质的混合物，碘升华后冷凝得到纯碘。","principle":["碘易升华，杂质不升华。"],"reagents":["粗碘"],"steps":["粗碘置于蒸发皿中。","盖上盛冷水的圆底烧瓶。","小火加热蒸发皿。","碘蒸气冷凝在烧瓶底部。"],"tags":["升华","提纯","碘"],"difficulty":2},
{"id":"fractional-distillation","name":"分馏","category":"分离提纯","hazard":2,"duration":"25 min","summary":"用分馏柱分离乙醇和水的混合物。","principle":["利用组分沸点不同，多次气化冷凝实现分离。"],"reagents":["乙醇水溶液"],"steps":["混合液加入蒸馏烧瓶，装分馏柱。","加热，控制馏出速度。","收集 78 ℃ 左右的乙醇馏分。","温度上升后更换接收瓶。"],"tags":["分馏","沸点","分离"],"difficulty":2},
{"id":"steam-distillation","name":"水蒸气蒸馏","category":"分离提纯","hazard":2,"duration":"25 min","summary":"用水蒸气蒸馏从混合物中分离挥发性有机物。","principle":["水蒸气降低组分分压，使有机物在低于其沸点时随水蒸气馏出。"],"reagents":["含苯胺的水溶液"],"steps":["水蒸气发生器加热产生蒸汽。","蒸汽通入蒸馏烧瓶，与混合物共热。","馏出物冷凝收集。","分液分离有机层。"],"tags":["水蒸气蒸馏","分离","有机物"],"difficulty":2},
{"id":"salting-out","name":"盐析","category":"分离提纯","hazard":1,"duration":"15 min","summary":"向肥皂液中加入饱和食盐水，使肥皂析出。","principle":["电解质降低蛋白质或皂胶体的溶解度。"],"reagents":["肥皂液","饱和食盐水"],"steps":["肥皂液加热。","加入饱和食盐水，搅拌。","静置分层。","过滤收集肥皂。"],"tags":["盐析","胶体","肥皂"],"difficulty":1},
{"id":"dialysis","name":"渗析","category":"分离提纯","hazard":1,"duration":"20 min","summary":"用半透膜分离淀粉胶体与氯化钠。","principle":["半透膜允许小分子和离子通过，阻止胶体颗粒。"],"reagents":["淀粉溶液","氯化钠溶液","碘液","硝酸银溶液"],"steps":["淀粉与氯化钠混合液装入半透膜袋。","置于蒸馏水中。","一段时间后检验袋外液体。","用碘液和硝酸银分别检验。"],"tags":["渗析","胶体","半透膜"],"difficulty":1},
{"id":"centrifugation","name":"离心分离","category":"分离提纯","hazard":1,"duration":"10 min","summary":"用离心机加速悬浊液中固体的沉降。","principle":["离心力使密度较大的固体颗粒快速沉降。"],"reagents":["硫酸钡悬浊液"],"steps":["悬浊液装入离心管，对称放置。","设定转速，离心 3 分钟。","取出离心管，观察分层。","用滴管吸出上层清液。"],"tags":["离心","分离","悬浊液"],"difficulty":1},
{"id":"acid-base-standard","name":"盐酸标准溶液的标定","category":"定量测量","hazard":1,"duration":"25 min","summary":"用基准无水碳酸钠标定盐酸溶液的浓度。","principle":["Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂↑"],"reagents":["无水碳酸钠","待标定盐酸","甲基橙指示剂"],"steps":["准确称取无水碳酸钠，配成标准溶液。","取 25.00 mL 碳酸钠溶液，加甲基橙。","用盐酸滴定至橙色。","平行滴定三次，计算浓度。"],"tags":["标定","滴定","基准物质"],"difficulty":1},
{"id":"redox-titration","name":"高锰酸钾滴定","category":"定量测量","hazard":2,"duration":"25 min","summary":"用高锰酸钾标准溶液滴定草酸溶液。","principle":["2MnO₄⁻ + 5H₂C₂O₄ + 6H⁺ → 2Mn²⁺ + 10CO₂↑ + 8H₂O"],"reagents":["高锰酸钾标准溶液","草酸溶液","稀硫酸"],"steps":["草酸溶液加稀硫酸酸化。","加热至 70–80 ℃。","用高锰酸钾滴定至微红色。","平行滴定，计算浓度。"],"tags":["氧化还原滴定","高锰酸钾","定量"],"difficulty":2},
{"id":"edta-titration","name":"EDTA 配位滴定","category":"定量测量","hazard":1,"duration":"25 min","summary":"用 EDTA 标准溶液滴定水中的钙镁离子。","principle":["EDTA 与 Ca²⁺、Mg²⁺ 形成 1∶1 稳定配合物。"],"reagents":["EDTA 标准溶液","水样","铬黑 T 指示剂","氨缓冲溶液"],"steps":["取水样，加氨缓冲溶液调 pH 至 10。","加入铬黑 T 指示剂。","用 EDTA 滴定至蓝色。","记录体积，计算硬度。"],"tags":["配位滴定","硬度","EDTA"],"difficulty":1},
{"id":"mohr-method","name":"莫尔法测定氯离子","category":"定量测量","hazard":1,"duration":"25 min","summary":"用硝酸银标准溶液滴定氯离子，铬酸钾作指示剂。","principle":["Ag⁺ + Cl⁻ → AgCl↓","2Ag⁺ + CrO₄²⁻ → Ag₂CrO₄↓（砖红色）"],"reagents":["硝酸银标准溶液","氯化钠溶液","铬酸钾指示剂"],"steps":["取氯化钠溶液，加铬酸钾指示剂。","用硝酸银滴定，剧摇。","至出现砖红色沉淀。","计算氯离子含量。"],"tags":["沉淀滴定","氯离子","硝酸银"],"difficulty":1},
{"id":"density-measure","name":"密度的测定","category":"定量测量","hazard":1,"duration":"15 min","summary":"用比重瓶或量筒测量液体的密度。","principle":["密度等于质量除以体积。"],"reagents":["待测液体","蒸馏水"],"steps":["称量空比重瓶质量。","装满蒸馏水称量。","装满待测液称量。","计算密度。"],"tags":["密度","测量","比重瓶"],"difficulty":1},
{"id":"melting-point","name":"熔点的测定","category":"定量测量","hazard":1,"duration":"20 min","summary":"用毛细管法测定苯甲酸的熔点。","principle":["纯净有机物有固定熔点，杂质使熔点降低且范围变宽。"],"reagents":["苯甲酸","液体石蜡"],"steps":["苯甲酸研细，装入毛细管。","毛细管附在温度计旁，放入熔点管。","缓慢加热，观察熔化。","记录初熔和全熔温度。"],"tags":["熔点","纯度","测量"],"difficulty":1},
{"id":"ph-measure","name":"pH 的测定","category":"定量测量","hazard":1,"duration":"15 min","summary":"用 pH 试纸和 pH 计测定不同溶液的 pH。","principle":["pH 等于氢离子浓度的负对数。"],"reagents":["盐酸","氢氧化钠溶液","氯化钠溶液","pH 试纸"],"steps":["用玻璃棒蘸取溶液点在 pH 试纸上。","与标准比色卡对照。","用 pH 计校准后测量。","比较两种方法结果。"],"tags":["pH","测量","酸碱"],"difficulty":1},
{"id":"water-hardness","name":"水的硬度测定","category":"定量测量","hazard":1,"duration":"25 min","summary":"用 EDTA 滴定法测定自来水与井水的硬度。","principle":["EDTA 与钙镁离子形成稳定配合物。"],"reagents":["EDTA 标准溶液","水样","铬黑 T","氨缓冲液"],"steps":["分别取等体积水样。","加缓冲液和指示剂。","用 EDTA 滴定至蓝色。","比较消耗体积，计算硬度。"],"tags":["硬度","滴定","水样"],"difficulty":1},
{"id":"esterification","name":"乙酸乙酯的制备","category":"有机","hazard":2,"duration":"25 min","summary":"乙酸与乙醇在浓硫酸催化下酯化，收集乙酸乙酯。","principle":["CH₃COOH + C₂H₅OH ⇌(浓H₂SO₄, Δ) CH₃COOC₂H₅ + H₂O"],"reagents":["冰醋酸","无水乙醇","浓硫酸","饱和碳酸钠溶液"],"steps":["乙酸与乙醇混合，缓慢加入浓硫酸。","回流 30 分钟。","蒸馏收集馏分。","用饱和碳酸钠溶液洗涤，分液，干燥。"],"tags":["酯化","回流","香料"],"difficulty":2},
{"id":"saponification","name":"肥皂的制备","category":"有机","hazard":2,"duration":"20 min","summary":"油脂与氢氧化钠溶液皂化，盐析后得到肥皂。","principle":["油脂 + 3NaOH → 甘油 + 3脂肪酸钠"],"reagents":["植物油","氢氧化钠溶液","饱和食盐水"],"steps":["油脂与氢氧化钠溶液混合。","水浴加热并搅拌至皂化完全。","加入饱和食盐水盐析。","纱布过滤，压制成型。"],"tags":["皂化","油脂","肥皂"],"difficulty":2},
{"id":"biuret-test","name":"双缩脲检验蛋白质","category":"有机","hazard":1,"duration":"10 min","summary":"向蛋白质溶液加入双缩脲试剂，观察紫色。","principle":["碱性条件下 Cu²⁺ 与肽键形成紫色配合物。"],"reagents":["鸡蛋清溶液","氢氧化钠溶液","硫酸铜溶液"],"steps":["取鸡蛋清溶液。","加入氢氧化钠溶液。","滴加硫酸铜溶液。","观察颜色。"],"tags":["蛋白质","显色","检验"],"difficulty":1},
{"id":"cellulose-hydrolysis","name":"纤维素的水解","category":"有机","hazard":2,"duration":"20 min","summary":"纤维素在浓硫酸中水解，检验生成的葡萄糖。","principle":["(C₆H₁₀O₅)n + nH₂O →(H⁺, Δ) nC₆H₁₂O₆"],"reagents":["脱脂棉","70% 硫酸","氢氧化钠溶液","斐林试剂"],"steps":["脱脂棉加入浓硫酸，搅拌成糊。","水浴加热至溶解。","加水稀释并中和。","加入斐林试剂水浴加热。"],"tags":["水解","纤维素","还原糖"],"difficulty":2},
{"id":"fermentation","name":"乙醇发酵","category":"有机","hazard":1,"duration":"25 min","summary":"葡萄糖溶液在酵母作用下发酵产生乙醇和二氧化碳。","principle":["C₆H₁₂O₆ →(酶) 2C₂H₅OH + 2CO₂↑"],"reagents":["葡萄糖溶液","干酵母","澄清石灰水"],"steps":["葡萄糖溶液加入干酵母。","连接导管，通入石灰水。","置于 30 ℃ 水浴中。","观察气泡和石灰水变化。"],"tags":["发酵","酶","乙醇"],"difficulty":1},
{"id":"bromine-unsaturation","name":"溴水检验不饱和键","category":"有机","hazard":2,"duration":"15 min","summary":"向植物油和苯中分别滴加溴水，比较褪色情况。","principle":["碳碳双键与溴发生加成反应，使溴水褪色。"],"reagents":["植物油","苯","溴水"],"steps":["两支试管分别加入植物油和苯。","各滴加溴水，振荡。","观察褪色情况。","比较现象。"],"tags":["不饱和键","加成","鉴别"],"difficulty":2},
{"id":"golden-rain","name":"黄金雨","category":"趣味演示","hazard":2,"duration":"15 min","summary":"加热碘化钾与硝酸铅溶液，冷却后析出金黄色片状晶体。","principle":["Pb²⁺ + 2I⁻ → PbI₂↓"],"reagents":["硝酸铅溶液","碘化钾溶液"],"steps":["硝酸铅与碘化钾溶液混合，生成黄色沉淀。","加热至沉淀溶解。","缓慢冷却。","观察晶体析出。"],"tags":["结晶","碘化铅","演示"],"difficulty":2},
{"id":"silver-tree","name":"银树","category":"趣味演示","hazard":2,"duration":"15 min","summary":"将铜丝放入硝酸银溶液，析出银白色晶体。","principle":["Cu + 2Ag⁺ → Cu²⁺ + 2Ag"],"reagents":["硝酸银溶液","铜丝"],"steps":["硝酸银溶液倒入试管。","放入弯成树状的铜丝。","静置观察。","记录现象。"],"tags":["置换","银","演示"],"difficulty":2},
{"id":"oscillating-reaction","name":"化学振荡反应","category":"趣味演示","hazard":2,"duration":"20 min","summary":"BZ 反应中溶液颜色在无色与蓝色之间周期变化。","principle":["丙二酸在溴酸盐氧化下发生非线性振荡反应。"],"reagents":["丙二酸","溴酸钾","硫酸铈铵","邻菲罗啉亚铁"],"steps":["配制丙二酸、溴酸钾和催化剂溶液。","混合后置于搅拌器上。","观察颜色变化。","记录振荡周期。"],"tags":["振荡","动力学","演示"],"difficulty":2},
{"id":"milk-rainbow","name":"牛奶彩虹","category":"趣味演示","hazard":1,"duration":"10 min","summary":"在牛奶表面滴加色素和洗洁精，观察颜色扩散。","principle":["洗洁精降低表面张力，破坏脂肪膜，形成对流。"],"reagents":["牛奶","食用色素","洗洁精"],"steps":["牛奶倒入浅盘。","滴加不同颜色色素。","棉签蘸洗洁精点在中心。","观察颜色扩散。"],"tags":["表面张力","扩散","演示"],"difficulty":1},
{"id":"sodium-acetate-crystal","name":"醋酸钠过饱和结晶","category":"趣味演示","hazard":1,"duration":"15 min","summary":"醋酸钠过饱和溶液遇晶种迅速结晶并放热。","principle":["过饱和溶液不稳定，加入晶种后迅速结晶。"],"reagents":["三水醋酸钠","蒸馏水"],"steps":["醋酸钠加水加热溶解至饱和。","冷却至室温形成过饱和溶液。","投入一粒醋酸钠晶体。","观察结晶并触摸杯壁。"],"tags":["过饱和","结晶","放热"],"difficulty":1},
{"id":"luminol","name":"鲁米诺发光","category":"趣味演示","hazard":2,"duration":"20 min","summary":"鲁米诺在碱性过氧化氢和催化剂作用下发出蓝光。","principle":["鲁米诺被氧化为激发态产物，跃迁回基态时发光。"],"reagents":["鲁米诺","氢氧化钠溶液","过氧化氢","铁氰化钾"],"steps":["配制鲁米诺碱性溶液。","加入过氧化氢和催化剂。","在暗处观察。","记录发光持续时间。"],"tags":["化学发光","氧化","演示"],"difficulty":2},
{"id":"flame-dry-tube","name":"试管的预热与均匀加热","category":"基础操作","hazard":1,"duration":"10 min","summary":"练习试管加热时先预热、后集中加热，避免局部骤热炸裂。","principle":["玻璃受热不均产生内应力，骤热骤冷易炸裂","预热使受热区域温度梯度减小"],"reagents":["蒸馏水"],"steps":["试管中加入 1/3 体积水，用试管夹夹住中上部。","在火焰外焰处来回移动试管预热。","再集中加热液体中下部，管口不对人。","加热完毕在石棉网上自然冷却。"],"tags":["基本操作","加热","安全"],"difficulty":1},
{"id":"glass-cutting-bending","name":"玻璃管的切割与弯曲","category":"基础操作","hazard":2,"duration":"20 min","summary":"用三角锉刻痕、折断并烧圆玻璃管，弯制实验用导管。","principle":["玻璃在刻痕处应力集中而断裂","火焰软化玻璃，可塑形并烧圆锐边"],"reagents":["无需化学试剂（仅物理加工）"],"steps":["用三角锉在玻璃管上单向刻出深痕。","双手拇指抵住刻痕背面，轻轻掰断。","断口在火焰中烧圆，避免割伤。","需弯曲时在火焰上均匀加热至软化，缓慢弯成所需角度。"],"tags":["玻璃加工","仪器制作"],"difficulty":2},
{"id":"cork-boring","name":"橡胶塞打孔与导管装配","category":"基础操作","hazard":2,"duration":"15 min","summary":"选择合适孔径的打孔器，为橡胶塞打孔并装配气密导管。","principle":["打孔器孔径略小于导管外径，利用橡胶弹性密封","孔道应与塞子轴线平行"],"reagents":["甘油"],"steps":["按导管外径选择打孔器，孔径略小 0.5 mm。","打孔器蘸甘油，从塞子小端垂直钻入。","取出孔中胶芯，插入导管并旋转推进。","将装置浸入水中检查气密性。"],"tags":["气密性","仪器装配"],"difficulty":2},
{"id":"crucible-use","name":"坩埚的使用与高温加热","category":"基础操作","hazard":2,"duration":"30 min","summary":"用坩埚进行固体高温灼烧，练习坩埚钳取放与干燥器冷却。","principle":["坩埚可承受 1000 ℃ 以上高温","灼烧后需在干燥器中冷却，防止吸湿"],"reagents":["碳酸钙"],"steps":["将碳酸钙粉末装入坩埚，不超过 2/3。","马弗炉升温至 900 ℃，灼烧 30 min。","用预热过的坩埚钳取出，放入干燥器。","冷却后称量，观察失重。"],"tags":["高温","灼烧","重量分析"],"difficulty":2},
{"id":"thermometer-calibration","name":"温度计的校准","category":"基础操作","hazard":1,"duration":"25 min","summary":"用冰水浴与沸水浴两点法校准温度计，绘制校正曲线。","principle":["冰水共存体系为 0 ℃，常压沸水为 100 ℃","线性内插可校正刻度误差"],"reagents":["冰","蒸馏水"],"steps":["将碎冰与水混合成冰水浴，插入温度计读数。","加热水至沸腾，插入温度计读数并记录气压。","计算两点误差，绘制校正曲线。","对中间温度点进行内插校正。"],"tags":["校准","温度测量"],"difficulty":1},
{"id":"ph-meter-calibration","name":"pH 计的两点校准","category":"基础操作","hazard":1,"duration":"20 min","summary":"用 pH 4.00 与 6.86 标准缓冲液校准 pH 计，测量未知溶液。","principle":["玻璃电极电位与 pH 呈线性关系","两点校准确定斜率与零点"],"reagents":["pH 4.00 缓冲液","pH 6.86 缓冲液","未知水样"],"steps":["开机预热 30 min，用蒸馏水冲洗电极。","浸入 pH 6.86 缓冲液，调定位旋钮。","浸入 pH 4.00 缓冲液，调斜率旋钮。","冲洗电极后测量水样，记录稳定读数。"],"tags":["pH","校准","仪器"],"difficulty":1},
{"id":"balance-tare","name":"电子天平的去皮与准确称量","category":"基础操作","hazard":1,"duration":"15 min","summary":"练习电子天平水平调节、去皮、增量法与减量法称量。","principle":["电磁力平衡传感器将质量转为电信号","去皮可扣除容器质量"],"reagents":["氯化钠","称量纸"],"steps":["检查天平水平泡，开机预热。","放上称量纸，按去皮键归零。","用药匙缓慢加入氯化钠至目标质量。","记录读数，清理天平盘。"],"tags":["称量","分析天平"],"difficulty":1},
{"id":"volumetric-transfer","name":"移液与定容操作","category":"基础操作","hazard":1,"duration":"20 min","summary":"用移液管准确移取溶液，在容量瓶中定容，练习视线与凹液面。","principle":["容量瓶容积在标定温度下准确","凹液面最低点与刻度线相切"],"reagents":["氯化钠溶液","蒸馏水"],"steps":["移液管用待取液润洗 2–3 次。","用洗耳球吸液至刻度线上方，食指控制放液至刻度。","将液体放入容量瓶，洗涤烧杯与玻璃棒 3 次。","加水至近刻度，改用滴管定容，摇匀。"],"tags":["移液","定容","溶液配制"],"difficulty":1},
{"id":"reflux-water-separator","name":"分水器回流操作","category":"基础操作","hazard":2,"duration":"40 min","summary":"用分水器在回流过程中移出生成的水，推动酯化反应进行。","principle":["酯化生成水，分水器使水与有机相分离","移出产物水使平衡右移"],"reagents":["乙酸","正丁醇","浓硫酸","甲苯"],"steps":["按装置图安装烧瓶、分水器与冷凝管。","加入反应物与带水剂甲苯，加热回流。","观察分水器中水层逐渐增多。","反应结束冷却，分出有机层。"],"tags":["回流","分水","酯化"],"difficulty":3},
{"id":"vacuum-distillation","name":"减压蒸馏","category":"基础操作","hazard":2,"duration":"45 min","summary":"在减压条件下蒸馏高沸点或热敏物质，降低沸点避免分解。","principle":["液体沸点随外压降低而下降","减压可保护热敏物质"],"reagents":["粗甘油"],"steps":["安装减压蒸馏装置，检查气密性。","加入粗甘油与沸石，开通冷凝水。","启动真空泵，调节压力至 10 mmHg 左右。","加热蒸馏，收集稳定馏分。"],"tags":["减压","蒸馏","提纯"],"difficulty":3},
{"id":"electrolyte-conductivity","name":"电解质溶液导电性比较","category":"物质性质","hazard":1,"duration":"15 min","summary":"用导电性装置比较盐酸、醋酸、氯化钠溶液与蔗糖溶液的导电能力。","principle":["导电能力取决于自由移动离子的浓度","强电解质完全电离，弱电解质部分电离"],"reagents":["盐酸","醋酸","氯化钠溶液","蔗糖溶液"],"steps":["将电极分别插入四种溶液。","观察灯泡亮度或电流计读数。","用同浓度溶液重复比较。","记录并排序导电能力。"],"tags":["导电性","强弱电解质"],"difficulty":1},
{"id":"sugar-charring","name":"蔗糖的炭化","category":"物质性质","hazard":2,"duration":"15 min","summary":"浓硫酸使蔗糖脱水炭化，体积膨胀并放出刺激性气体。","principle":["C₁₂H₂₂O₁₁ —浓硫酸→ 12C + 11H₂O","浓硫酸的脱水性使有机物炭化"],"reagents":["蔗糖","浓硫酸"],"steps":["烧杯中加入少量蔗糖。","滴加几滴浓硫酸，轻轻搅拌。","观察颜色与体积变化。","反应结束后加水稀释并中和。"],"tags":["浓硫酸","脱水性","炭化"],"difficulty":2},
{"id":"iodine-starch-complex","name":"碘与淀粉的包合显色","category":"物质性质","hazard":1,"duration":"15 min","summary":"碘分子进入淀粉螺旋空腔形成蓝色包合物，加热褪色、冷却复蓝。","principle":["I₂ 与直链淀粉形成蓝色包合物","包合物受热解离，冷却重新形成"],"reagents":["淀粉溶液","碘液","蒸馏水"],"steps":["试管中加入淀粉溶液与一滴碘液。","观察蓝色出现。","水浴加热至蓝色褪去。","冷却后观察蓝色恢复。"],"tags":["淀粉","碘","包合物"],"difficulty":1},
{"id":"milk-emulsion","name":"牛奶的乳化与破乳","category":"物质性质","hazard":1,"duration":"20 min","summary":"观察牛奶的乳浊液性质，用酸或盐使其破乳分层。","principle":["牛奶是蛋白质稳定的水包油乳浊液","酸化使酪蛋白凝聚，破坏乳化"],"reagents":["牛奶","乙酸","氯化钠","苏丹Ⅲ染液"],"steps":["取牛奶观察外观，滴加苏丹Ⅲ染液染色。","显微镜下观察油滴分布。","加入乙酸，观察凝聚与分层。","另取牛奶加盐，比较盐析效果。"],"tags":["乳浊液","乳化","蛋白质"],"difficulty":1},
{"id":"salt-freezing-mixture","name":"冰盐冷冻混合物","category":"物质性质","hazard":1,"duration":"20 min","summary":"冰与氯化钠混合使温度降至约 −21 ℃，用于低温浴。","principle":["盐使冰点降低，熔化吸热使体系降温","低共熔点约 −21 ℃（NaCl 23%）"],"reagents":["碎冰","氯化钠"],"steps":["烧杯中装入碎冰，插入温度计。","加入氯化钠并搅拌。","每 2 min 记录温度。","观察最低温度并绘制降温曲线。"],"tags":["冰点降低","低温浴"],"difficulty":1},
{"id":"vapor-pressure-demo","name":"蒸发吸热与蒸气压","category":"物质性质","hazard":1,"duration":"15 min","summary":"比较水、乙醇、乙醚在皮肤上的蒸发冷却效果，理解蒸气压与分子间作用力。","principle":["蒸发吸收汽化热，蒸气压越大蒸发越快","分子间作用力越弱，蒸气压越高"],"reagents":["水","乙醇","乙醚"],"steps":["在温度计感温泡上包湿棉花，记录初始温度。","分别蘸取水、乙醇、乙醚，记录温度下降。","比较三种液体降温速率。","用分子间作用力解释差异。"],"tags":["蒸气压","分子间作用力","汽化热"],"difficulty":1},
{"id":"capillary-action","name":"毛细现象与表面张力","category":"物质性质","hazard":1,"duration":"15 min","summary":"观察水与乙醇在毛细管中的上升高度，比较表面张力与润湿性。","principle":["毛细上升高度 h = 2γcosθ/(ρgr)","表面张力越大、接触角越小，上升越高"],"reagents":["水","乙醇","洗涤剂溶液"],"steps":["将毛细管插入水中，测量上升高度。","换用乙醇与洗涤剂溶液重复。","比较三种液体的上升高度。","分析表面张力与接触角的影响。"],"tags":["毛细现象","表面张力"],"difficulty":1},
{"id":"crystal-growth-alum","name":"明矾晶体的生长","category":"物质性质","hazard":1,"duration":"60 min","summary":"配制饱和明矾溶液，用晶种缓慢生长出规则八面体晶体。","principle":["溶解度随温度升高而增大","缓慢冷却使溶质在晶种上有序沉积"],"reagents":["明矾","蒸馏水","细线"],"steps":["配制 60 ℃ 饱和明矾溶液，过滤。","系一小颗晶种于细线上，悬入溶液。","缓慢降温，静置 24 h。","取出晶体，观察外形并测量。"],"tags":["结晶","晶体生长","明矾"],"difficulty":2},
{"id":"cobalt-chloride-humidity","name":"氯化钴的变色与湿度指示","category":"物质性质","hazard":2,"duration":"15 min","summary":"无水氯化钴呈蓝色，吸水后变为粉红色，可用于硅胶湿度指示。","principle":["CoCl₂ + 6H₂O ⇌ CoCl₂·6H₂O","无水物蓝色，六水合物粉红色"],"reagents":["氯化钴","蒸馏水","硅胶"],"steps":["取少量氯化钴溶液蒸干，观察颜色。","加热脱水至蓝色。","滴加水，观察变为粉红色。","将蓝色硅胶置于潮湿环境，观察变色。"],"tags":["结晶水","变色","湿度指示"],"difficulty":2},
{"id":"deliquescence","name":"潮解现象观察","category":"物质性质","hazard":1,"duration":"30 min","summary":"比较氯化钙、氢氧化钠、氯化钠在潮湿空气中的吸湿行为。","principle":["易溶盐吸收空气中的水形成溶液","蒸气压低于空气中水蒸气分压时潮解"],"reagents":["氯化钙","氢氧化钠","氯化钠"],"steps":["将三种固体分别放在表面皿上。","置于湿度 80% 的密闭容器中。","每 10 min 观察并称量。","记录质量变化与外观。"],"tags":["潮解","吸湿性"],"difficulty":1},
{"id":"efflorescence","name":"结晶水合物的风化","category":"物质性质","hazard":1,"duration":"30 min","summary":"碳酸钠晶体在干燥空气中失去结晶水，表面变为白色粉末。","principle":["Na₂CO₃·10H₂O → Na₂CO₃ + 10H₂O↑","结晶水蒸气压高于空气中水蒸气分压时风化"],"reagents":["十水碳酸钠","无水氯化钙"],"steps":["取透明十水碳酸钠晶体，称量。","放入盛有无水氯化钙的干燥器中。","每天观察并称量。","记录质量损失与外观变化。"],"tags":["风化","结晶水"],"difficulty":1},
{"id":"gas-diffusion","name":"气体的扩散","category":"物质性质","hazard":2,"duration":"20 min","summary":"氨气与氯化氢气体在长管两端扩散，相遇生成氯化铵白烟。","principle":["NH₃ + HCl → NH₄Cl（白烟）","扩散速率与摩尔质量平方根成反比"],"reagents":["浓氨水","浓盐酸"],"steps":["在长玻璃管两端分别塞入蘸有浓氨水与浓盐酸的棉花。","迅速封住两端。","观察白烟出现的位置。","比较白烟位置靠近哪一端。"],"tags":["扩散","氨","氯化氢"],"difficulty":2},
{"id":"colloidal-tyndall","name":"丁达尔效应与胶体","category":"物质性质","hazard":1,"duration":"15 min","summary":"用激光笔照射氢氧化铁胶体、硫酸铜溶液与泥水，观察光路差异。","principle":["胶体粒子尺寸与可见光波长相当，产生散射","真溶液无丁达尔效应"],"reagents":["氢氧化铁胶体","硫酸铜溶液","泥水"],"steps":["分别取三种液体于烧杯中。","在暗背景下用激光笔从侧面照射。","观察是否出现明亮光路。","记录现象并分类。"],"tags":["胶体","丁达尔效应"],"difficulty":1},
{"id":"emulsion-test","name":"乳浊液与溶液、悬浊液的鉴别","category":"物质性质","hazard":1,"duration":"15 min","summary":"通过静置、过滤与丁达尔效应区分三种分散系。","principle":["溶液均一稳定，悬浊液会沉降，乳浊液会分层","分散质粒径决定光学与过滤行为"],"reagents":["食盐水","泥水","植物油与水"],"steps":["三种样品分别静置 10 min。","观察是否分层或沉降。","分别过滤，观察滤液是否澄清。","用激光笔照射比较光路。"],"tags":["分散系","鉴别"],"difficulty":1},
{"id":"suspension-sedimentation","name":"悬浊液的沉降与沉降体积","category":"物质性质","hazard":1,"duration":"30 min","summary":"比较碳酸钙与黏土悬浊液的沉降速率，理解粒径与沉降的关系。","principle":["斯托克斯沉降速率与粒径平方成正比","颗粒越细沉降越慢"],"reagents":["碳酸钙","黏土","蒸馏水"],"steps":["配制等质量分数的两种悬浊液。","摇匀后静置，记录沉降界面高度。","每 5 min 记录一次。","绘制沉降曲线并比较。"],"tags":["沉降","悬浊液"],"difficulty":1},
{"id":"solution-conductivity","name":"溶液导电性与浓度的关系","category":"物质性质","hazard":1,"duration":"20 min","summary":"测量不同浓度氯化钠溶液的导电性，绘制电导率-浓度曲线。","principle":["电导率随离子浓度增加而增大","高浓度时离子间相互作用使曲线偏离线性"],"reagents":["氯化钠","蒸馏水"],"steps":["配制 0.01–0.5 mol/L 系列氯化钠溶液。","用电导率仪依次测量。","记录温度并校正。","绘制电导率对浓度的曲线。"],"tags":["电导率","浓度"],"difficulty":1},
{"id":"acid-rain-simulation","name":"模拟酸雨对大理石的影响","category":"物质性质","hazard":2,"duration":"30 min","summary":"用稀硫酸模拟酸雨，观察其对大理石表面的腐蚀。","principle":["CaCO₃ + H₂SO₄ → CaSO₄ + CO₂↑ + H₂O","硫酸钙微溶，覆盖表面后反应减慢"],"reagents":["大理石碎片","稀硫酸","pH 试纸"],"steps":["称量大理石碎片，记录质量。","浸入 pH 3 的稀硫酸中。","每 10 min 观察气泡与表面变化。","24 h 后取出洗净干燥称量。"],"tags":["酸雨","碳酸钙","腐蚀"],"difficulty":2},
{"id":"hard-water-scum","name":"硬水水垢的生成与清除","category":"物质性质","hazard":2,"duration":"30 min","summary":"煮沸硬水使碳酸氢钙分解生成水垢，再用稀盐酸溶解水垢。","principle":["Ca(HCO₃)₂ —Δ→ CaCO₃↓ + CO₂↑ + H₂O","CaCO₃ + 2HCl → CaCl₂ + CO₂↑ + H₂O"],"reagents":["暂时硬水","稀盐酸","肥皂水"],"steps":["取硬水加热煮沸 10 min，观察白色沉淀。","过滤得到水垢，干燥称量。","向水垢中滴加稀盐酸，观察气泡。","比较煮沸前后肥皂起泡情况。"],"tags":["水垢","硬度","碳酸氢钙"],"difficulty":2},
{"id":"ammonia-solubility","name":"氨气的溶解性与喷泉实验","category":"气体与燃烧","hazard":2,"duration":"15 min","summary":"干燥圆底烧瓶收集氨气后滴入水，形成红色喷泉。","principle":["NH₃ + H₂O ⇌ NH₃·H₂O ⇌ NH₄⁺ + OH⁻","氨极易溶，瓶内压强骤降形成喷泉"],"reagents":["浓氨水","酚酞溶液","蒸馏水"],"steps":["用排空气法收集干燥氨气。","滴管中吸入酚酞水溶液，插入烧瓶。","挤压滴管使少量水进入烧瓶。","打开止水夹，观察喷泉与颜色。"],"tags":["喷泉实验","氨","溶解性"],"difficulty":2},
{"id":"chlorine-solubility","name":"氯气的溶解性与氯水性质","category":"气体与燃烧","hazard":3,"duration":"20 min","summary":"氯气溶于水得到黄绿色氯水，检验其酸性、漂白性与氧化性。","principle":["Cl₂ + H₂O ⇌ HCl + HClO","HClO 具有强氧化性与漂白性"],"reagents":["氯水","石蕊溶液","品红溶液","硝酸银溶液"],"steps":["观察氯水颜色，用 pH 试纸测酸碱性。","滴入石蕊溶液，观察先变红后褪色。","滴入品红溶液，观察褪色。","滴加硝酸银溶液，观察白色沉淀。"],"tags":["氯水","漂白","次氯酸"],"difficulty":3},
{"id":"co2-density","name":"二氧化碳的密度与倾倒实验","category":"气体与燃烧","hazard":1,"duration":"10 min","summary":"将二氧化碳从高处倾倒到阶梯蜡烛上，低处蜡烛先熄灭。","principle":["CO₂ 密度大于空气，不支持燃烧","CO₂ + Ca(OH)₂ → CaCO₃↓ + H₂O"],"reagents":["大理石","稀盐酸","澄清石灰水"],"steps":["用大理石与稀盐酸制取并收集二氧化碳。","将集气瓶中的气体缓慢倾倒入阶梯蜡烛。","观察两支蜡烛的熄灭顺序。","将气体通入澄清石灰水验证。"],"tags":["二氧化碳","密度","灭火"],"difficulty":1},
{"id":"hydrogen-diffusion","name":"氢气的扩散与渗透","category":"气体与燃烧","hazard":3,"duration":"15 min","summary":"氢气通过多孔材料扩散，点燃时产生爆鸣，理解气体分子运动。","principle":["氢气密度最小，扩散速率最快","2H₂ + O₂ —点燃→ 2H₂O"],"reagents":["锌粒","稀硫酸","肥皂水"],"steps":["用锌与稀硫酸制取氢气。","将导管口蘸肥皂水，吹出氢气泡。","点燃肥皂泡，观察爆鸣与火球。","比较纯氢与混空气氢气的燃烧现象。"],"tags":["氢气","爆鸣","扩散"],"difficulty":3},
{"id":"gas-molar-volume","name":"气体摩尔体积的测定","category":"气体与燃烧","hazard":2,"duration":"40 min","summary":"用镁条与稀硫酸反应，排水法收集氢气，计算标准状况下气体摩尔体积。","principle":["Mg + H₂SO₄ → MgSO₄ + H₂↑","V_m = V(H₂)/n(Mg)，标准状况约 22.4 L/mol"],"reagents":["镁条","稀硫酸","蒸馏水"],"steps":["称量约 0.02 g 镁条，记录质量。","按装置连接量气管，加入稀硫酸。","反应完全后冷却，调节水准瓶使液面相平。","读取气体体积，换算为标准状况。"],"tags":["摩尔体积","定量","镁"],"difficulty":3},
{"id":"combustion-oxygen-conc","name":"氧气浓度对燃烧剧烈程度的影响","category":"气体与燃烧","hazard":2,"duration":"20 min","summary":"比较木炭在空气与纯氧中的燃烧现象。","principle":["C + O₂ —点燃→ CO₂","氧浓度越高，燃烧速率越快"],"reagents":["木炭","氧气","澄清石灰水"],"steps":["将红热木炭放入空气集气瓶，观察现象。","另取红热木炭放入纯氧集气瓶。","比较发光与燃烧剧烈程度。","反应后加入石灰水验证产物。"],"tags":["燃烧","氧气","浓度"],"difficulty":2},
{"id":"candle-composition","name":"蜡烛燃烧产物的检验","category":"气体与燃烧","hazard":1,"duration":"15 min","summary":"用干冷烧杯与内壁涂石灰水的烧杯检验蜡烛燃烧生成水和二氧化碳。","principle":["石蜡 + O₂ → CO₂ + H₂O","CO₂ 使石灰水变浑浊，水使无水硫酸铜变蓝"],"reagents":["蜡烛","澄清石灰水","无水硫酸铜"],"steps":["点燃蜡烛，将干冷烧杯罩在火焰上方。","观察烧杯内壁的水雾。","换用涂有石灰水的烧杯，观察浑浊。","用无水硫酸铜检验水的生成。"],"tags":["燃烧产物","石蜡"],"difficulty":1},
{"id":"wood-distillation","name":"木材的干馏","category":"气体与燃烧","hazard":3,"duration":"30 min","summary":"隔绝空气加热木屑，得到木炭、木焦油与可燃性气体。","principle":["木材 —隔绝空气, Δ→ 木炭 + 木焦油 + 木煤气","干馏是热分解过程"],"reagents":["木屑"],"steps":["将木屑装入硬质试管，连接导管。","加热试管，观察产物。","用集气瓶收集气体并点燃。","冷却后取出木炭观察。"],"tags":["干馏","热分解","木炭"],"difficulty":3},
{"id":"sulfur-burn","name":"硫在空气与氧气中的燃烧","category":"气体与燃烧","hazard":2,"duration":"15 min","summary":"点燃硫粉，比较其在空气与纯氧中的火焰颜色与产物。","principle":["S + O₂ —点燃→ SO₂","纯氧中燃烧更剧烈，火焰呈蓝紫色"],"reagents":["硫粉","氧气","氢氧化钠溶液"],"steps":["将少量硫粉放在燃烧匙中点燃。","观察空气中淡蓝色火焰。","伸入纯氧集气瓶，观察蓝紫色火焰。","尾气用氢氧化钠溶液吸收。"],"tags":["硫","燃烧","二氧化硫"],"difficulty":2},
{"id":"phosphorus-burn","name":"红磷的燃烧与白烟","category":"气体与燃烧","hazard":3,"duration":"15 min","summary":"红磷在氧气中燃烧生成五氧化二磷白烟，可用于测定空气中氧气含量。","principle":["4P + 5O₂ —点燃→ 2P₂O₅","P₂O₅ 白色固体小颗粒形成白烟"],"reagents":["红磷","氧气"],"steps":["将少量红磷置于燃烧匙，点燃。","迅速伸入集气瓶并塞紧。","观察白烟与瓶内水位变化。","冷却后测量进入瓶内水的体积。"],"tags":["红磷","白烟","空气组成"],"difficulty":3},
{"id":"magnesium-co2","name":"镁在二氧化碳中的燃烧","category":"气体与燃烧","hazard":3,"duration":"15 min","summary":"点燃镁条后伸入二氧化碳集气瓶，镁继续燃烧并生成氧化镁与碳。","principle":["2Mg + CO₂ —点燃→ 2MgO + C","镁的还原性强于碳"],"reagents":["镁条","二氧化碳","稀盐酸"],"steps":["用大理石与盐酸制取并收集二氧化碳。","点燃镁条，迅速伸入集气瓶。","观察燃烧与瓶壁附着物。","反应后加稀盐酸检验氧化镁。"],"tags":["镁","二氧化碳","金属火灾"],"difficulty":3},
{"id":"no2-water","name":"二氧化氮与水的反应","category":"气体与燃烧","hazard":3,"duration":"20 min","summary":"二氧化氮溶于水生成硝酸与一氧化氮，观察红棕色褪去与气体体积变化。","principle":["3NO₂ + H₂O → 2HNO₃ + NO","NO 无色，遇空气重新变为 NO₂"],"reagents":["二氧化氮","蒸馏水","紫色石蕊"],"steps":["收集一瓶二氧化氮，倒扣在水中。","轻轻摇动，观察颜色与水位变化。","取出瓶内溶液，滴加石蕊观察变红。","将剩余气体接触空气，观察颜色恢复。"],"tags":["二氧化氮","歧化","硝酸"],"difficulty":3},
{"id":"electrolysis-na2so4","name":"硫酸钠溶液的电解","category":"电化学","hazard":2,"duration":"25 min","summary":"电解硫酸钠溶液，在阴极与阳极分别收集氢气和氧气。","principle":["阴极：2H₂O + 2e⁻ → H₂↑ + 2OH⁻","阳极：2H₂O − 4e⁻ → O₂↑ + 4H⁺"],"reagents":["硫酸钠溶液","紫色石蕊"],"steps":["按装置连接电极与电源。","加入硫酸钠溶液，开始电解。","用试管分别收集两极气体。","检验气体并观察溶液 pH 变化。"],"tags":["电解","水","气体"],"difficulty":2},
{"id":"electrolysis-hcl","name":"盐酸的电解","category":"电化学","hazard":3,"duration":"20 min","summary":"电解盐酸溶液，阴极析出氢气，阳极析出氯气。","principle":["阴极：2H⁺ + 2e⁻ → H₂↑","阳极：2Cl⁻ − 2e⁻ → Cl₂↑"],"reagents":["稀盐酸","淀粉碘化钾试纸"],"steps":["电解槽中加入稀盐酸，插入石墨电极。","通电，观察两极气泡。","用湿润淀粉碘化钾试纸检验阳极气体。","收集阴极气体并验纯。"],"tags":["电解","盐酸","氯气"],"difficulty":3},
{"id":"electroplating-zinc","name":"电镀锌","category":"电化学","hazard":2,"duration":"30 min","summary":"以锌片为阳极、铁片为阴极，在氯化锌镀液中电镀锌层。","principle":["阳极：Zn − 2e⁻ → Zn²⁺","阴极：Zn²⁺ + 2e⁻ → Zn"],"reagents":["氯化锌","氯化铵","硼酸","铁片","锌片"],"steps":["铁片打磨除锈，用碱液除油。","配制氯化锌镀液，调节 pH 4–5。","连接锌阳极与铁阴极，通电 0.2 A/dm²。","电镀 20 min 后取出，观察镀层。"],"tags":["电镀","锌","防腐"],"difficulty":2},
{"id":"electroplating-nickel","name":"电镀镍","category":"电化学","hazard":2,"duration":"30 min","summary":"在瓦特镀镍液中以镍片为阳极，在铜片上电镀镍层。","principle":["阳极：Ni − 2e⁻ → Ni²⁺","阴极：Ni²⁺ + 2e⁻ → Ni"],"reagents":["硫酸镍","氯化镍","硼酸","铜片","镍片"],"steps":["铜片打磨、除油、活化。","配制瓦特镀液，加热至 50 ℃。","连接镍阳极与铜阴极，通电 0.3 A/dm²。","电镀 20 min，取出水洗干燥。"],"tags":["电镀","镍","瓦特镀液"],"difficulty":2},
{"id":"electroplating-silver","name":"电镀银","category":"电化学","hazard":2,"duration":"30 min","summary":"以银片为阳极，在银氰化物替代镀液中给铜片镀银。","principle":["阳极：Ag − e⁻ → Ag⁺","阴极：Ag⁺ + e⁻ → Ag"],"reagents":["硝酸银","硫代硫酸钠","亚硫酸钠","铜片","银片"],"steps":["铜片打磨除油。","配制无氰镀银液，避光保存。","连接银阳极与铜阴极，通电 0.2 A/dm²。","电镀 15 min 后取出，水洗干燥。"],"tags":["电镀","银","无氰"],"difficulty":2},
{"id":"electrolytic-polishing","name":"铝的电解抛光","category":"电化学","hazard":2,"duration":"30 min","summary":"铝片在磷酸-硫酸抛光液中作阳极，表面变得光亮。","principle":["阳极溶解使微观凸起优先溶解","形成黏性液膜抑制凹处溶解"],"reagents":["磷酸","硫酸","铝片"],"steps":["配制磷酸-硫酸抛光液。","铝片作阳极，铅板作阴极。","控制电压 10–15 V，抛光 5 min。","取出水洗，观察表面光亮度。"],"tags":["电解抛光","铝","表面处理"],"difficulty":2},
{"id":"impressed-current","name":"外加电流阴极保护","category":"电化学","hazard":2,"duration":"30 min","summary":"用直流电源保护铁片不被腐蚀，比较保护前后的锈蚀情况。","principle":["外加电子使铁成为阴极，抑制 Fe − 2e⁻ → Fe²⁺","牺牲阳极或外加电流均可实现阴极保护"],"reagents":["铁片","碳棒","氯化钠溶液","直流电源"],"steps":["铁片打磨，放入氯化钠溶液。","铁片接电源负极，碳棒接正极。","通电保护 20 min，同时设置无保护对照。","取出观察两片铁片的锈蚀程度。"],"tags":["阴极保护","腐蚀","电化学"],"difficulty":2},
{"id":"voltaic-pile","name":"伏打电堆的制作","category":"电化学","hazard":1,"duration":"25 min","summary":"用铜片、锌片与浸盐水的纸片交替堆叠，制作伏打电堆点亮 LED。","principle":["锌为负极：Zn − 2e⁻ → Zn²⁺","铜为正极，电子经外电路流动"],"reagents":["铜片","锌片","食盐水","滤纸"],"steps":["将铜片、锌片与浸盐水的滤纸依次叠放。","重复堆叠 10 层。","用导线连接两端，接上 LED。","用电压表测量电堆电压。"],"tags":["原电池","伏打电堆","串联"],"difficulty":1},
{"id":"lead-acid-battery","name":"铅蓄电池的充放电","category":"电化学","hazard":3,"duration":"45 min","summary":"用小铅蓄电池演示放电与充电过程，理解二次电池的可逆性。","principle":["放电：Pb + PbO₂ + 2H₂SO₄ → 2PbSO₄ + 2H₂O","充电为逆反应"],"reagents":["铅蓄电池","稀硫酸","蒸馏水"],"steps":["测量电池初始电压。","接灯泡放电，记录电压下降。","接充电器充电，记录电压回升。","比较放电与充电前后的电解液密度。"],"tags":["二次电池","铅蓄电池","充放电"],"difficulty":3},
{"id":"conductivity-titration","name":"电导滴定","category":"电化学","hazard":1,"duration":"40 min","summary":"用盐酸滴定氢氧化钠溶液，监测电导率变化确定终点。","principle":["H⁺ 与 OH⁻ 迁移率高，中和后电导率下降","过量酸使电导率重新上升"],"reagents":["盐酸标准溶液","氢氧化钠溶液","蒸馏水"],"steps":["测定氢氧化钠溶液初始电导率。","每加入 0.5 mL 盐酸记录一次电导率。","绘制电导率-体积曲线。","由曲线折点确定终点体积。"],"tags":["电导滴定","滴定曲线"],"difficulty":2},
{"id":"galvanic-corrosion","name":"电偶腐蚀","category":"电化学","hazard":2,"duration":"30 min","summary":"铜片与铁片接触放入盐水，观察接触处铁优先腐蚀。","principle":["铁为负极被氧化，铜为正极","接触处形成短路的原电池"],"reagents":["铁片","铜片","氯化钠溶液","琼脂-酚酞指示剂"],"steps":["铁片与铜片打磨后紧贴放入培养皿。","倒入含酚酞的氯化钠琼脂。","静置 30 min 观察颜色变化。","比较接触处与远离处的锈蚀。"],"tags":["电偶腐蚀","原电池","金属"],"difficulty":2},
{"id":"methane-chlorination","name":"甲烷的氯代反应","category":"有机","hazard":3,"duration":"20 min","summary":"甲烷与氯气在光照下发生自由基取代，生成一氯甲烷至四氯化碳的混合物。","principle":["CH₄ + Cl₂ —hν→ CH₃Cl + HCl","自由基链式取代，产物为混合物"],"reagents":["甲烷","氯气","饱和食盐水"],"steps":["用排水法收集甲烷，再通入氯气。","将混合气体置于强光下照射。","观察黄绿色褪去与瓶壁油状物。","用湿润石蕊试纸检验氯化氢。"],"tags":["自由基取代","甲烷","氯代"],"difficulty":3},
{"id":"ethylene-prep","name":"乙烯的实验室制备","category":"有机","hazard":3,"duration":"25 min","summary":"乙醇与浓硫酸共热至 170 ℃，脱水生成乙烯，用排水法收集。","principle":["CH₃CH₂OH —浓硫酸, 170 ℃→ CH₂=CH₂↑ + H₂O","140 ℃ 时主要生成乙醚"],"reagents":["乙醇","浓硫酸","氢氧化钠溶液"],"steps":["将乙醇与浓硫酸按 1∶3 混合，加入沸石。","迅速升温至 170 ℃，收集气体。","气体先通过氢氧化钠溶液除去杂质。","用排水法收集乙烯，检验其燃烧与加成。"],"tags":["脱水","乙烯","温度控制"],"difficulty":3},
{"id":"acetylene-prep","name":"乙炔的制备与性质","category":"有机","hazard":3,"duration":"25 min","summary":"电石与水反应生成乙炔，检验其燃烧与溴水加成。","principle":["CaC₂ + 2H₂O → Ca(OH)₂ + C₂H₂↑","2C₂H₂ + 5O₂ —点燃→ 4CO₂ + 2H₂O"],"reagents":["电石","饱和食盐水","溴水","硫酸铜溶液"],"steps":["锥形瓶中加入电石，分液漏斗中加饱和食盐水。","缓慢滴加水，用排水法收集乙炔。","通入溴水观察褪色，点燃观察火焰。","气体先通过硫酸铜溶液除去硫化氢。"],"tags":["乙炔","三键","加成"],"difficulty":3},
{"id":"benzene-nitration","name":"苯的硝化反应","category":"有机","hazard":3,"duration":"40 min","summary":"苯与浓硝酸在浓硫酸催化下发生亲电取代，生成硝基苯。","principle":["C₆H₆ + HNO₃ —浓硫酸, 55 ℃→ C₆H₅NO₂ + H₂O","硝基正离子是亲电试剂"],"reagents":["苯","浓硝酸","浓硫酸","碳酸钠溶液"],"steps":["将浓硝酸与浓硫酸混合冷却。","缓慢加入苯，控制温度 50–55 ℃。","反应 30 min 后倒入冷水，分出有机层。","用碳酸钠溶液洗涤，无水氯化钙干燥。"],"tags":["硝化","亲电取代","苯"],"difficulty":3},
{"id":"toluene-oxidation","name":"甲苯的氧化","category":"有机","hazard":2,"duration":"35 min","summary":"甲苯被酸性高锰酸钾氧化为苯甲酸，证明侧链被氧化。","principle":["C₆H₅CH₃ + 3[O] → C₆H₅COOH + H₂O","苯环侧链的 α-氢被氧化"],"reagents":["甲苯","高锰酸钾","稀硫酸","氢氧化钠溶液"],"steps":["甲苯与高锰酸钾、稀硫酸混合。","回流 30 min 至紫色褪去。","冷却后抽滤除去二氧化锰。","滤液酸化析出苯甲酸，抽滤干燥。"],"tags":["侧链氧化","甲苯","苯甲酸"],"difficulty":2},
{"id":"ethanol-dehydration","name":"乙醇的脱水","category":"有机","hazard":3,"duration":"25 min","summary":"比较乙醇在 140 ℃ 与 170 ℃ 的脱水产物，理解温度对反应方向的影响。","principle":["2C₂H₅OH —140 ℃→ C₂H₅OC₂H₅ + H₂O","C₂H₅OH —170 ℃→ C₂H₄↑ + H₂O"],"reagents":["乙醇","浓硫酸"],"steps":["乙醇与浓硫酸混合，加入沸石。","缓慢升温至 140 ℃，收集馏出液。","继续升温至 170 ℃，排水法收集气体。","分别检验乙醚与乙烯。"],"tags":["脱水","温度","乙醚"],"difficulty":3},
{"id":"acetic-acid-fermentation","name":"醋酸发酵","category":"有机","hazard":1,"duration":"60 min","summary":"乙醇在醋酸菌作用下被空气氧化为醋酸，观察酸度变化。","principle":["C₂H₅OH + O₂ —醋酸菌→ CH₃COOH + H₂O","需充足氧气与适宜温度"],"reagents":["米酒","醋酸菌","pH 试纸"],"steps":["米酒稀释后接入醋酸菌。","用纱布封口，30 ℃ 静置。","每天测 pH 并闻气味。","一周后过滤得到醋液。"],"tags":["发酵","醋酸","微生物"],"difficulty":2},
{"id":"soap-salting","name":"皂化与盐析","category":"有机","hazard":2,"duration":"40 min","summary":"油脂与氢氧化钠皂化后加食盐盐析，分离肥皂与甘油。","principle":["油脂 + 3NaOH → 3RCOONa + 甘油","加入 NaCl 降低肥皂溶解度使其析出"],"reagents":["植物油","氢氧化钠溶液","氯化钠","乙醇"],"steps":["植物油与氢氧化钠乙醇溶液混合，水浴加热 40 min。","加入饱和食盐水，搅拌后静置。","肥皂浮于上层，冷却后取出。","下层滤液含甘油，可回收。"],"tags":["皂化","盐析","肥皂"],"difficulty":3},
{"id":"aspirin-synthesis","name":"阿司匹林的合成","category":"有机","hazard":2,"duration":"45 min","summary":"水杨酸与乙酸酐在浓硫酸催化下乙酰化，制得乙酰水杨酸。","principle":["C₆H₄(OH)COOH + (CH₃CO)₂O → C₆H₄(OCOCH₃)COOH + CH₃COOH","酚羟基被乙酰化"],"reagents":["水杨酸","乙酸酐","浓硫酸","碳酸氢钠溶液"],"steps":["水杨酸与乙酸酐混合，加入 2 滴浓硫酸。","70 ℃ 水浴加热 15 min。","冷却后加水，抽滤得到粗品。","用碳酸氢钠溶液重结晶，测熔点。"],"tags":["乙酰化","阿司匹林","药物合成"],"difficulty":3},
{"id":"azo-dye","name":"偶氮染料的合成","category":"有机","hazard":3,"duration":"40 min","summary":"苯胺重氮化后与酚偶合，生成橙红色偶氮染料。","principle":["C₆H₅NH₂ + NaNO₂ + 2HCl → C₆H₅N₂⁺Cl⁻ + NaCl + 2H₂O","重氮盐与酚偶合生成偶氮化合物"],"reagents":["苯胺","亚硝酸钠","盐酸","苯酚","氢氧化钠"],"steps":["苯胺溶于稀盐酸，冰水浴冷却至 0–5 ℃。","缓慢加入亚硝酸钠溶液，制得重氮盐。","将重氮盐加入苯酚的氢氧化钠溶液。","搅拌 10 min，抽滤得到橙红色染料。"],"tags":["重氮化","偶合","染料"],"difficulty":3},
{"id":"enzyme-amylase","name":"唾液淀粉酶的催化作用","category":"有机","hazard":1,"duration":"25 min","summary":"唾液淀粉酶在不同温度与 pH 下分解淀粉，用碘液检验剩余淀粉。","principle":["淀粉 —淀粉酶→ 麦芽糖","酶活性受温度与 pH 影响"],"reagents":["淀粉溶液","唾液","碘液","盐酸","氢氧化钠"],"steps":["收集唾液稀释，分别置于 0 ℃、37 ℃、80 ℃。","加入淀粉溶液，计时 5 min。","各取一滴在滴板上加碘液。","比较蓝色深浅判断酶活性。"],"tags":["酶","淀粉","温度"],"difficulty":1},
{"id":"starch-gelatinization","name":"淀粉的糊化与老化","category":"有机","hazard":1,"duration":"25 min","summary":"加热淀粉悬浊液使其糊化，冷却后观察老化回生现象。","principle":["淀粉颗粒吸水膨胀破裂，形成糊状物","冷却后直链淀粉重结晶发生老化"],"reagents":["淀粉","蒸馏水","碘液"],"steps":["淀粉加水配成 5% 悬浊液。","水浴加热至 80 ℃ 并搅拌，观察黏度变化。","显微镜下观察颗粒膨胀。","冷却静置 24 h，观察析水与硬度。"],"tags":["淀粉","糊化","老化"],"difficulty":1},
{"id":"protein-isoelectric","name":"蛋白质等电点的测定","category":"有机","hazard":1,"duration":"30 min","summary":"调节酪蛋白溶液 pH，观察不同 pH 下浊度变化，确定等电点。","principle":["等电点时蛋白质净电荷为零，溶解度最低","酪蛋白等电点约 pH 4.6"],"reagents":["酪蛋白","乙酸","氢氧化钠","缓冲液"],"steps":["配制一系列 pH 2–7 的缓冲液。","各加入等量酪蛋白溶液，摇匀静置。","测定浊度或观察沉淀量。","绘制浊度-pH 曲线确定等电点。"],"tags":["等电点","蛋白质","酪蛋白"],"difficulty":1},
{"id":"oil-hydrogenation","name":"油脂的氢化","category":"有机","hazard":2,"duration":"40 min","summary":"植物油在镍催化下加氢，由液态变为半固态，理解人造奶油原理。","principle":["—CH=CH— + H₂ —Ni, Δ→ —CH₂—CH₂—","不饱和脂肪酸甘油酯被饱和"],"reagents":["植物油","氢气","镍催化剂"],"steps":["植物油与镍催化剂加入反应釜。","通入氢气，保持 0.2 MPa、180 ℃。","反应 1 h 后冷却，过滤除去催化剂。","观察产物状态与碘值变化。"],"tags":["氢化","油脂","催化"],"difficulty":3},
{"id":"biodiesel","name":"生物柴油的制备","category":"有机","hazard":2,"duration":"40 min","summary":"植物油与甲醇在碱催化下酯交换，生成脂肪酸甲酯即生物柴油。","principle":["甘油三酯 + 3CH₃OH —NaOH→ 3RCOOCH₃ + 甘油","酯交换降低黏度"],"reagents":["植物油","甲醇","氢氧化钠","饱和食盐水"],"steps":["配制甲醇钠溶液。","植物油加热至 60 ℃，加入甲醇钠。","回流 1 h，冷却静置分层。","分出上层甲酯，水洗干燥。"],"tags":["酯交换","生物柴油","甲醇"],"difficulty":3},
{"id":"fingerprint-iodine","name":"碘熏法显现指纹","category":"有机","hazard":2,"duration":"20 min","summary":"加热碘晶体产生碘蒸气，指纹中的油脂吸附碘而显色。","principle":["碘蒸气溶于指纹油脂形成棕色痕迹","碘的升华与凝华可逆"],"reagents":["碘","指纹样本"],"steps":["在干净玻璃片上按压指纹。","将玻璃片与碘晶体放入密闭容器。","40 ℃ 水浴加热使碘升华。","取出玻璃片，观察棕色指纹。"],"tags":["指纹","碘升华","显影"],"difficulty":2},
{"id":"paper-making","name":"手工造纸与纤维观察","category":"有机","hazard":1,"duration":"50 min","summary":"废纸打浆后抄纸、压榨、干燥，制作再生纸并观察纤维。","principle":["纤维素纤维经打浆分丝后交织成纸","氢键结合使纸张具有强度"],"reagents":["废纸","水"],"steps":["废纸撕碎浸泡，搅拌成纸浆。","抄纸框捞取纸浆，均匀铺展。","压榨脱水，揭下湿纸页。","阴干后用显微镜观察纤维。"],"tags":["纤维素","造纸","再生纸"],"difficulty":2},
{"id":"soxhlet-extraction","name":"索氏提取法提取油脂","category":"分离提纯","hazard":2,"duration":"60 min","summary":"用索氏提取器以石油醚循环萃取花生中的油脂。","principle":["溶剂回流与虹吸循环使固体被反复萃取","相似相溶原理"],"reagents":["花生粉","石油醚"],"steps":["花生粉装入滤纸筒，放入提取器。","烧瓶中加入石油醚，水浴加热回流。","循环萃取 8–10 次。","回收溶剂，称量油脂。"],"tags":["萃取","索氏提取","油脂"],"difficulty":3},
{"id":"rotary-evaporation","name":"旋转蒸发浓缩","category":"分离提纯","hazard":2,"duration":"30 min","summary":"用旋转蒸发仪在减压下快速除去溶剂，浓缩溶液。","principle":["减压降低沸点，旋转增大蒸发面积","冷凝回收溶剂"],"reagents":["含溶剂提取液"],"steps":["将溶液装入蒸发瓶，安装到仪器上。","开启冷凝水与真空泵。","设置水浴 40 ℃，旋转蒸发。","浓缩至所需体积后解除真空。"],"tags":["减压","浓缩","旋转蒸发"],"difficulty":2},
{"id":"hot-filtration","name":"热过滤操作","category":"分离提纯","hazard":2,"duration":"25 min","summary":"用预热漏斗趁热过滤，除去不溶性杂质，防止晶体提前析出。","principle":["溶解度随温度升高而增大","热过滤保持溶液温度，避免溶质结晶"],"reagents":["含杂质的饱和明矾溶液"],"steps":["将漏斗预热，折叠滤纸并润湿。","加热溶液至近沸腾。","趁热过滤，收集滤液。","滤液缓慢冷却结晶。"],"tags":["热过滤","重结晶","提纯"],"difficulty":2},
{"id":"crystallization-seeding","name":"晶种法结晶","category":"分离提纯","hazard":1,"duration":"40 min","summary":"在过饱和溶液中加入晶种，控制结晶获得较大晶体。","principle":["过饱和溶液处于亚稳态","晶种提供成核位点，降低成核能垒"],"reagents":["明矾","蒸馏水"],"steps":["配制 50 ℃ 饱和明矾溶液。","缓慢冷却至室温形成过饱和溶液。","加入一颗小晶种，静置。","观察晶体生长并测量尺寸。"],"tags":["结晶","晶种","过饱和"],"difficulty":2},
{"id":"ion-exchange","name":"离子交换法软化硬水","category":"分离提纯","hazard":1,"duration":"30 min","summary":"让硬水通过阳离子交换树脂，钙镁离子被钠离子交换，水被软化。","principle":["2R-SO₃Na + Ca²⁺ → (R-SO₃)₂Ca + 2Na⁺","树脂可再生"],"reagents":["硬水","阳离子交换树脂","氯化钠溶液"],"steps":["将树脂装入交换柱，用食盐水活化。","缓慢通过硬水，收集流出液。","比较流出液与原料水的起泡性。","用浓食盐水再生树脂。"],"tags":["离子交换","硬水","软化"],"difficulty":1},
{"id":"thin-layer-chromatography","name":"薄层色谱分离色素","category":"分离提纯","hazard":2,"duration":"35 min","summary":"用硅胶板分离菠菜色素，计算比移值 Rf。","principle":["不同组分在固定相与流动相间分配系数不同","Rf = 斑点移动距离/展开剂前沿距离"],"reagents":["菠菜提取液","石油醚","丙酮","硅胶板"],"steps":["制备菠菜色素提取液。","在硅胶板基线处点样，吹干。","放入展开剂中展开至前沿接近顶端。","取出晾干，观察斑点并计算 Rf。"],"tags":["色谱","色素","Rf"],"difficulty":2},
{"id":"column-chromatography","name":"柱色谱分离甲基橙与亚甲基蓝","category":"分离提纯","hazard":1,"duration":"45 min","summary":"用氧化铝柱分离两种染料，观察色带展开与洗脱。","principle":["极性组分与固定相吸附较强，洗脱较慢","不同组分迁移速率不同"],"reagents":["甲基橙","亚甲基蓝","氧化铝","乙醇"],"steps":["湿法装柱，压实氧化铝。","加入染料混合物，用乙醇洗脱。","分段收集流出液。","比较各段颜色与成分。"],"tags":["柱色谱","分离","染料"],"difficulty":2},
{"id":"ultrafiltration","name":"超滤分离蛋白质与盐","category":"分离提纯","hazard":1,"duration":"35 min","summary":"用超滤膜分离蛋白质与小分子盐，理解膜分离的选择性。","principle":["超滤膜截留分子量大于孔径的溶质","小分子与离子透过膜"],"reagents":["蛋白质溶液","氯化钠","蒸馏水"],"steps":["将蛋白质与盐的混合液加入超滤管。","离心过滤，收集滤液。","用双缩脲试剂检验滤液是否含蛋白质。","用硝酸银检验滤液中的氯离子。"],"tags":["膜分离","超滤","蛋白质"],"difficulty":1},
{"id":"density-gradient","name":"密度梯度分离","category":"分离提纯","hazard":1,"duration":"30 min","summary":"用蔗糖溶液构建密度梯度，使不同密度的塑料小球悬浮在不同高度。","principle":["物体在与其密度相同的液层悬浮","密度梯度由溶液浓度连续变化形成"],"reagents":["蔗糖","水","不同塑料小球"],"steps":["配制 10%–60% 的蔗糖溶液系列。","沿壁缓慢叠加，形成密度梯度。","放入塑料小球，静置。","观察小球悬浮位置并估测密度。"],"tags":["密度","分离","梯度"],"difficulty":1},
{"id":"magnetic-separation","name":"磁分离四氧化三铁","category":"分离提纯","hazard":1,"duration":"20 min","summary":"利用磁铁将四氧化三铁从混合物中分离，理解磁性材料的分离方法。","principle":["Fe₃O₄ 具有铁磁性，可被磁铁吸引","磁性分离不改变物质化学性质"],"reagents":["四氧化三铁","细砂","蒸馏水"],"steps":["将四氧化三铁与细砂混合。","加水制成悬浊液。","用磁铁贴近烧杯外壁，收集黑色固体。","倾去砂与水，重复纯化。"],"tags":["磁分离","四氧化三铁","混合物分离"],"difficulty":1},
{"id":"titration-curve","name":"酸碱滴定曲线的绘制","category":"定量测量","hazard":2,"duration":"45 min","summary":"用 pH 计记录滴定过程中 pH 变化，绘制滴定曲线并比较指示剂选择。","principle":["等当点附近 pH 突跃","指示剂变色范围应落在突跃范围内"],"reagents":["盐酸标准溶液","氢氧化钠溶液","酚酞","甲基橙"],"steps":["移取氢氧化钠溶液，插入 pH 电极。","逐滴加入盐酸，记录体积与 pH。","等当点附近每 0.1 mL 记录一次。","绘制 pH-V 曲线并比较指示剂终点。"],"tags":["滴定曲线","pH","指示剂"],"difficulty":3},
{"id":"iodometric-vitc","name":"碘量法测定维生素 C","category":"定量测量","hazard":2,"duration":"40 min","summary":"用碘标准溶液滴定维生素 C，根据消耗体积计算含量。","principle":["C₆H₈O₆ + I₂ → C₆H₆O₆ + 2HI","淀粉为指示剂，蓝色出现为终点"],"reagents":["维生素 C 片","碘标准溶液","淀粉指示剂","稀醋酸"],"steps":["将维生素 C 片研碎，溶于稀醋酸并定容。","加入淀粉指示剂。","用碘标准溶液滴定至蓝色不褪。","计算维生素 C 含量并与标称值比较。"],"tags":["碘量法","维生素C","滴定"],"difficulty":3},
{"id":"gravimetric-chloride","name":"重量法测定氯离子","category":"定量测量","hazard":3,"duration":"60 min","summary":"用硝酸银沉淀氯离子，过滤、灼烧、称量氯化银，计算氯含量。","principle":["Ag⁺ + Cl⁻ → AgCl↓","氯化银摩尔质量 143.32 g/mol"],"reagents":["氯化钠样品","硝酸银溶液","稀硝酸"],"steps":["称取样品，溶解后加稀硝酸酸化。","缓慢加入过量硝酸银溶液。","避光静置陈化，过滤洗涤沉淀。","灼烧至恒重，称量计算。"],"tags":["重量法","氯离子","沉淀"],"difficulty":3},
{"id":"dissolved-oxygen","name":"水中溶解氧的测定","category":"定量测量","hazard":2,"duration":"45 min","summary":"用温克勒法固定水中溶解氧，碘量法滴定计算溶解氧含量。","principle":["Mn²⁺ + 2OH⁻ → Mn(OH)₂；2Mn(OH)₂ + O₂ → 2MnO(OH)₂","MnO(OH)₂ 氧化碘离子，用硫代硫酸钠滴定"],"reagents":["水样","硫酸锰","氢氧化钠-碘化钾","硫酸","硫代硫酸钠标准溶液"],"steps":["水样装满溶解氧瓶，依次加入硫酸锰与碱液。","盖紧颠倒混匀，静置沉淀。","加入硫酸溶解沉淀，析出碘。","用硫代硫酸钠滴定至蓝色消失。"],"tags":["溶解氧","碘量法","水质"],"difficulty":3},
{"id":"colorimetry-iron","name":"比色法测定铁含量","category":"定量测量","hazard":2,"duration":"45 min","summary":"铁离子与邻二氮菲形成橙红色配合物，用分光光度计测定吸光度。","principle":["Fe²⁺ + 3phen → [Fe(phen)₃]²⁺","朗伯-比尔定律 A = εbc"],"reagents":["铁标准溶液","邻二氮菲","盐酸羟胺","乙酸钠缓冲液"],"steps":["配制铁标准系列溶液，依次加入显色剂。","调节 pH 至 4–5，显色 15 min。","在 510 nm 处测定吸光度。","绘制标准曲线，计算样品铁含量。"],"tags":["比色法","铁","分光光度"],"difficulty":3},
{"id":"flame-photometry","name":"火焰光度法测定钠钾","category":"定量测量","hazard":2,"duration":"40 min","summary":"用火焰光度计测定钠、钾标准系列，根据发射强度定量。","principle":["碱金属在火焰中受激发，发射特征波长","发射强度与浓度成正比"],"reagents":["氯化钠标准溶液","氯化钾标准溶液"],"steps":["配制钠、钾标准系列溶液。","仪器预热，调节燃气与空气流量。","依次测定标准溶液发射强度。","绘制标准曲线并测定样品。"],"tags":["火焰光度","钠","钾"],"difficulty":3},
{"id":"viscosity-measure","name":"液体黏度的测定","category":"定量测量","hazard":1,"duration":"30 min","summary":"用乌氏黏度计测定水与甘油的流出时间，比较黏度。","principle":["泊肃叶定律，流出时间与黏度成正比","温度对黏度影响显著"],"reagents":["蒸馏水","甘油","乙醇"],"steps":["黏度计垂直固定于恒温水浴。","吸入水至刻度上方，记录流出时间。","同法测定甘油与乙醇。","计算相对黏度并比较。"],"tags":["黏度","乌氏黏度计","温度"],"difficulty":1},
{"id":"surface-tension-measure","name":"表面张力的测定","category":"定量测量","hazard":1,"duration":"30 min","summary":"用吊环法测定水与洗涤剂溶液的表面张力。","principle":["吊环脱离液面所需力与表面张力相关","γ = F/(2πR)"],"reagents":["蒸馏水","洗涤剂溶液","乙醇"],"steps":["仪器调水平，铂环灼烧清洁。","测定纯水的表面张力。","测定不同浓度洗涤剂溶液的表面张力。","绘制表面张力-浓度曲线。"],"tags":["表面张力","表面活性剂"],"difficulty":1},
{"id":"heat-of-combustion","name":"燃烧热的测定","category":"定量测量","hazard":3,"duration":"50 min","summary":"用氧弹量热计测定萘的燃烧热，理解恒容燃烧热与焓变的关系。","principle":["Q = CΔT，C 为量热计热容","ΔH = Q_p，氧弹测得 Q_v"],"reagents":["萘","氧气","苯甲酸标准物质"],"steps":["用苯甲酸标定量热计热容。","称取萘样，装入氧弹并充氧。","点火燃烧，记录温度变化。","计算燃烧热并校正。"],"tags":["燃烧热","量热","热力学"],"difficulty":3},
{"id":"equilibrium-constant","name":"化学平衡常数的测定","category":"定量测量","hazard":2,"duration":"50 min","summary":"用分光光度法测定铁离子与硫氰酸根反应的平衡浓度，计算平衡常数。","principle":["Fe³⁺ + SCN⁻ ⇌ [Fe(SCN)]²⁺","K = c(FeSCN²⁺)/(c(Fe³⁺)c(SCN⁻))"],"reagents":["硝酸铁","硫氰酸钾","硝酸"],"steps":["配制已知浓度配合物测摩尔吸收系数。","配制不同初始浓度的系列溶液。","平衡后测定吸光度，计算平衡浓度。","计算 K 并分析温度影响。"],"tags":["平衡常数","比色","配合物"],"difficulty":3},
{"id":"rate-order","name":"反应级数的测定","category":"定量测量","hazard":2,"duration":"50 min","summary":"用碘钟反应测定反应速率对过氧化氢与碘离子浓度的级数。","principle":["v = k[H₂O₂]ᵐ[I⁻]ⁿ","改变初始浓度测初速率确定级数"],"reagents":["过氧化氢","碘化钾","硫代硫酸钠","淀粉"],"steps":["固定一种反应物浓度，改变另一种浓度。","记录蓝色出现时间作为反应完成标志。","计算初速率并作对数图。","由斜率确定反应级数。"],"tags":["反应速率","级数","碘钟"],"difficulty":3},
{"id":"crystal-garden","name":"硅酸钠晶体花园","category":"趣味演示","hazard":2,"duration":"30 min","summary":"将金属盐晶体投入硅酸钠溶液，生长出彩色“植物”状硅酸盐。","principle":["金属离子与硅酸根生成难溶硅酸盐膜","膜内渗透压使膜破裂并向上生长"],"reagents":["硅酸钠溶液","氯化铜","氯化铁","硫酸锰"],"steps":["配制密度较大的硅酸钠溶液。","将不同金属盐晶体投入溶液不同位置。","静置数小时观察生长。","记录各盐对应颜色。"],"tags":["硅酸盐","渗透","晶体"],"difficulty":2},
{"id":"copper-tree","name":"铜树置换","category":"趣味演示","hazard":2,"duration":"30 min","summary":"锌片放入硫酸铜溶液，置换出红色铜并形成树枝状沉积。","principle":["Zn + CuSO₄ → ZnSO₄ + Cu","锌比铜活泼，发生置换反应"],"reagents":["硫酸铜溶液","锌片","砂纸"],"steps":["锌片打磨除去氧化层。","浸入硫酸铜溶液。","静置 30 min 观察。","取出观察铜的沉积形态。"],"tags":["置换","铜","金属活动性"],"difficulty":2},
{"id":"rubber-egg","name":"鸡蛋的“去壳”与渗透","category":"趣味演示","hazard":1,"duration":"60 min","summary":"鸡蛋浸泡在白醋中，碳酸钙壳被溶解，剩下半透膜包裹的弹性蛋。","principle":["CaCO₃ + 2CH₃COOH → Ca(CH₃COO)₂ + CO₂↑ + H₂O","半透膜允许水分子渗透"],"reagents":["鸡蛋","白醋","清水","糖浆"],"steps":["鸡蛋放入白醋，观察气泡。","浸泡 24 h 后轻轻刷去蛋壳。","将无壳蛋放入清水，观察膨胀。","再放入糖浆，观察皱缩。"],"tags":["渗透","碳酸钙","半透膜"],"difficulty":2},
{"id":"invisible-ink","name":"隐形墨水","category":"趣味演示","hazard":1,"duration":"20 min","summary":"用柠檬汁或小苏打溶液书写，干燥后隐形，加热或显色剂使字迹出现。","principle":["有机物受热碳化显色","酸碱指示剂遇碱变色"],"reagents":["柠檬汁","小苏打","紫甘蓝汁","棉签"],"steps":["用棉签蘸柠檬汁在纸上写字。","吹干，字迹消失。","加热纸面，观察棕色字迹。","另用小苏打书写，喷紫甘蓝汁显色。"],"tags":["隐形墨水","碳化","酸碱指示剂"],"difficulty":1},
{"id":"ph-rainbow","name":"pH 彩虹","category":"趣味演示","hazard":1,"duration":"20 min","summary":"用不同 pH 的溶液与万能指示剂排列出彩虹色阶。","principle":["指示剂在不同 pH 下结构不同，颜色不同","pH 每变化 1 个单位，颜色渐变"],"reagents":["万能指示剂","盐酸","氢氧化钠","缓冲液"],"steps":["配制 pH 1–12 的系列溶液。","各加入等量万能指示剂。","按 pH 顺序排列试管。","观察颜色渐变并拍照。"],"tags":["pH","指示剂","彩虹"],"difficulty":1},
{"id":"pharaoh-snake","name":"法老之蛇","category":"趣味演示","hazard":3,"duration":"15 min","summary":"小苏打与糖粉在酒精燃烧下膨胀成黑色碳柱，形似蛇。","principle":["2NaHCO₃ → Na₂CO₃ + CO₂↑ + H₂O","糖碳化与气体膨胀形成多孔碳柱"],"reagents":["小苏打","糖粉","酒精","细沙"],"steps":["将小苏打与糖粉按 1∶4 混合。","托盘铺沙，堆成小丘，浇少量酒精。","点燃，观察黑色碳柱生长。","冷却后清理残渣。"],"tags":["燃烧","碳酸氢钠","碳化"],"difficulty":3},
{"id":"magnesium-burn","name":"镁条的燃烧","category":"趣味演示","hazard":3,"duration":"10 min","summary":"点燃镁条，观察耀眼白光与白色氧化镁。","principle":["2Mg + O₂ —点燃→ 2MgO","镁燃烧发出强光，可用于闪光粉"],"reagents":["镁条","砂纸"],"steps":["用砂纸打磨镁条表面。","用坩埚钳夹住一端，在酒精灯上点燃。","观察白光与白色固体。","燃烧后收集产物。"],"tags":["镁","燃烧","强光"],"difficulty":3},
{"id":"artificial-snow","name":"人造雪","category":"趣味演示","hazard":2,"duration":"15 min","summary":"聚丙烯酸钠吸水膨胀，形成白色蓬松的人造雪。","principle":["高分子吸水树脂形成三维网络","吸水后体积膨胀数百倍"],"reagents":["聚丙烯酸钠","水","色素"],"steps":["烧杯中加入少量聚丙烯酸钠。","缓慢加水并搅拌。","观察体积膨胀与外观。","加入色素观察染色效果。"],"tags":["高分子","吸水树脂","人造雪"],"difficulty":2},
{"id":"glass-etching","name":"玻璃蚀刻","category":"趣味演示","hazard":3,"duration":"30 min","summary":"用氟化氢铵与硫酸的糊状物蚀刻玻璃表面，形成磨砂图案。","principle":["SiO₂ + 4HF → SiF₄↑ + 2H₂O","氟化物与酸生成氢氟酸腐蚀玻璃"],"reagents":["氟化氢铵","浓硫酸","石蜡","玻璃片"],"steps":["玻璃片表面涂石蜡，刻出图案露出玻璃。","将氟化氢铵与硫酸调成糊状。","涂在刻痕处，静置 10 min。","去除石蜡，洗净观察磨砂图案。"],"tags":["蚀刻","氢氟酸","玻璃"],"difficulty":3},
{"id":"cyanotype","name":"蓝晒法制作影像","category":"趣味演示","hazard":2,"duration":"40 min","summary":"柠檬酸铁铵与铁氰化钾混合液涂布，曝光后水洗显影出蓝色影像。","principle":["Fe³⁺ 被光还原为 Fe²⁺","Fe²⁺ 与铁氰化钾生成普鲁士蓝"],"reagents":["柠檬酸铁铵","铁氰化钾","水彩纸","双氧水"],"steps":["等量混合两种溶液，避光涂布于纸面。","阴干后放上叶片或底片，阳光下曝光 5–10 min。","水洗显影，滴加双氧水加深蓝色。","晾干观察影像。"],"tags":["光化学","普鲁士蓝","蓝晒"],"difficulty":3},
{"id":"lava-lamp","name":"熔岩灯","category":"趣味演示","hazard":1,"duration":"20 min","summary":"油、水与泡腾片在瓶中形成循环上升下沉的彩色“熔岩”。","principle":["油水不相溶且油密度较小","泡腾片产生气体附着使液滴上浮，气体逸出后下沉"],"reagents":["植物油","水","色素","泡腾片"],"steps":["瓶中先加水与色素，再缓慢加入植物油。","静置分层。","投入半片泡腾片。","观察液滴循环运动。"],"tags":["密度","乳化","气体"],"difficulty":1},
{"id":"density-column","name":"糖水密度彩虹柱","category":"趣味演示","hazard":1,"duration":"25 分钟","summary":"用不同浓度的糖水加食用色素，沿杯壁缓慢叠加，得到分层彩虹柱，直观展示密度差异。","principle":["溶液密度随溶质质量分数增大而增大","低密度液体会浮在高密度液体上方"],"reagents":["白砂糖","食用色素 4 种","蒸馏水","洗洁精少许"],"steps":["配制 0%、10%、20%、30%、40% 的糖水各 50 mL，分别加不同色素。","长玻璃杯擦干，先倒入 40% 糖水作为最底层。","用滴管沿杯壁缓慢加入 30% 糖水，避免冲击液面。","依次叠加 20%、10%、0% 层，每层静置 1 分钟。","观察分层，静置 30 分钟后拍照记录。"],"tags":["短视频热门","密度","家庭材料"],"difficulty":1},
{"id":"iodine-fingerprint","name":"碘熏法显现指纹","category":"趣味演示","hazard":2,"duration":"20 分钟","summary":"利用碘蒸气在指纹残留的油脂和汗液中溶解富集，使潜指纹显色，是经典的法庭科学演示。","principle":["碘受热升华成紫色蒸气","碘蒸气在油脂、汗液处溶解并富集，形成棕色指纹"],"reagents":["碘粒 0.5 g","待显指纹的滤纸","蒸馏水"],"steps":["手指在滤纸上轻按，留下潜指纹。","将滤纸悬挂在染色缸内，加入少量碘粒。","水浴 40–50 ℃ 加热使碘升华，观察 1–3 分钟。","指纹呈棕色后立即取出，拍照记录。","通风橱内打开缸盖散尽蒸气，废碘回收。"],"tags":["短视频热门","法庭科学","升华"],"difficulty":2},
{"id":"leaf-vein-bookmark","name":"叶脉书签制作","category":"趣味演示","hazard":2,"duration":"45 分钟","summary":"用稀碱液煮叶片，水解叶肉后刷去，留下耐碱的纤维素叶脉，漂白染色压制成书签。","principle":["碱液水解叶肉细胞中的蛋白质和果胶","纤维素叶脉耐稀碱，得以保留"],"reagents":["桂花叶或白玉兰叶","5% 氢氧化钠溶液 200 mL","3% 过氧化氢","水彩颜料","蒸馏水"],"steps":["选取叶脉粗壮的叶片，洗净。","5% 氢氧化钠溶液加热至微沸，放入叶片煮 10–15 分钟。","镊子取出叶片，清水漂洗，用软毛刷轻刷去叶肉。","3% 过氧化氢浸泡漂白 10 分钟，清水洗净。","水彩染色 5 分钟，压平干燥，塑封成书签。"],"tags":["短视频热门","纤维","手工"],"difficulty":3},
{"id":"tofu-coagulation","name":"豆浆点卤做豆腐","category":"物质性质","hazard":1,"duration":"30 分钟","summary":"加热豆浆后加入钙镁盐卤或葡萄糖酸内酯，使大豆蛋白变性凝固，演示蛋白质的盐析与胶体聚沉。","principle":["大豆蛋白受热变性，空间结构展开","Ca²⁺、Mg²⁺ 或酸使蛋白分子交联、聚沉"],"reagents":["无糖豆浆 500 mL","硫酸钙（石膏）2 g 或葡萄糖酸内酯 3 g","蒸馏水"],"steps":["豆浆加热至 85–90 ℃，保持 5 分钟，不要沸腾溢出。","石膏加少量水调成悬浊液，或葡萄糖酸内酯溶于水。","豆浆降温至 75 ℃，边搅拌边加入凝固剂。","静置 15 分钟，观察絮状凝固。","纱布包好，模具中轻压脱水，得到豆腐。"],"tags":["短视频热门","蛋白质","家庭材料"],"difficulty":1},
{"id":"anthocyanin-ph","name":"紫甘蓝花青素变色","category":"物质性质","hazard":1,"duration":"20 分钟","summary":"从紫甘蓝中提取花青素，分别加入食醋、小苏打等，观察随 pH 变化的连续变色。","principle":["花青素在不同 pH 下结构改变，颜色由红经紫、蓝到绿黄"],"reagents":["紫甘蓝叶片","热水","白醋","小苏打","柠檬汁","肥皂水"],"steps":["紫甘蓝切碎，加热水浸泡 10 分钟，纱布过滤得到紫色提取液。","6 支试管各加 5 mL 提取液。","分别滴加白醋、柠檬汁、清水、小苏打溶液、肥皂水。","摇匀，记录每支试管的颜色。","按 pH 从低到高排列，制成比色卡。"],"tags":["短视频热门","指示剂","家庭材料"],"difficulty":1},
{"id":"leaf-pigment-chromatography","name":"菠菜色素纸层析","category":"分离提纯","hazard":1,"duration":"30 分钟","summary":"用乙醇提取菠菜色素，在滤纸上展开，分离出胡萝卜素、叶黄素和叶绿素。","principle":["不同色素在固定相与流动相中的分配系数不同","胡萝卜素极性最小，随展开剂移动最快"],"reagents":["菠菜叶","无水乙醇 20 mL","层析滤纸","石油醚-丙酮混合展开剂"],"steps":["菠菜叶剪碎，加无水乙醇研磨，过滤得到深绿色提取液。","滤纸剪成长条，距底端 1.5 cm 处用铅笔画起点线。","毛细管点样 3–5 次，每次吹干。","层析缸中加入少量展开剂，滤纸悬挂，底端浸入展开剂但不没过起点线。","展开至前沿距顶端 2 cm，取出晾干，测量各色带位置。"],"tags":["短视频热门","层析","天然产物"],"difficulty":1},
{"id":"water-rocket","name":"水火箭","category":"趣味演示","hazard":1,"duration":"40 分钟","summary":"用饮料瓶、水和压缩空气做反冲实验，理解作用力与反作用力；不涉及任何燃料或燃烧。","principle":["压缩空气把水向后高速喷出，瓶体获得向前的反作用力","动量守恒与反冲运动"],"reagents":["自来水","食用色素少许（可选）"],"steps":["在瓶内装入约三分之一体积的水，可滴入色素便于观察。","把瓶口装到专用发射器上，检查卡箍与密封圈。","把发射架朝向空旷无人的方向，缓慢打气到发射器允许的压力。","释放卡扣，观察瓶体升空与水的喷出方向。","改变水量重复 3 次，记录飞行距离。"],"tags":["安全推进","水火箭","反冲","家庭材料"],"difficulty":1},
{"id":"baking-soda-rocket","name":"小苏打白醋压力实验","category":"气体与燃烧","hazard":2,"duration":"20 分钟","summary":"小苏打与白醋在带盖小容器中反应生成二氧化碳，压力把盖子顶开，演示气体膨胀做功；不涉及燃料。","principle":["NaHCO₃ + CH₃COOH → CH₃COONa + H₂O + CO₂↑","密闭容器内气体增多，压强升高，顶开盖子"],"reagents":["小苏打 2 g","白醋 30 mL"],"steps":["在托盘上操作，戴护目镜。","把小苏打放入容器底部，迅速倒入白醋。","立即扣上盖子，人退到一米以外观察。","听到“啪”的一声后，等待反应结束再打开清理。"],"tags":["安全推进","气体膨胀","小苏打","白醋","家庭材料"],"difficulty":2},
{"id":"balloon-rocket","name":"气球反冲车","category":"趣味演示","hazard":1,"duration":"15 分钟","summary":"把吹胀的气球固定在吸管和小车上，放气时空气向后喷出，小车向前运动，演示反冲。","principle":["气球放气时空气向后喷出，给小车向前的反作用力","作用力与反作用力大小相等、方向相反"],"reagents":["无需化学试剂"],"steps":["把吸管粘在小车顶部，气球口套在吸管一端并用胶带固定。","把细线穿过吸管，拉直作为轨道（也可直接在地面跑）。","吹胀气球，捏住管口，把小车放到起点。","松手放气，观察小车运动方向和距离。","改变气球大小重复实验。"],"tags":["安全推进","反冲","气球","家庭材料"],"difficulty":1},
{"id":"effervescent-rocket","name":"泡腾片压力小实验","category":"趣味演示","hazard":2,"duration":"15 分钟","summary":"泡腾片遇水放出二氧化碳，在带盖小容器中产生压力顶开盖子，演示气体膨胀；不涉及燃料。","principle":["泡腾片中的碳酸氢钠与柠檬酸遇水反应生成 CO₂","密闭空间内压强升高，顶开盖子"],"reagents":["泡腾片 1 片","自来水 20 mL"],"steps":["戴护目镜，在托盘上打开小盒。","加入约 20 mL 水，放入半片泡腾片。","迅速扣好盖子，退到一米外观察。","待反应结束后再打开清理。"],"tags":["安全推进","泡腾片","气体膨胀","家庭材料"],"difficulty":2},
{"id":"ops-glassware-drying","name":"玻璃仪器的洗净与干燥","category":"基础操作","hazard":1,"duration":"20 分钟","summary":"用去离子水与洗涤剂清洗玻璃仪器，判断洗净标准，并按用途选择晾干、烘干或有机溶剂干燥。","principle":["洗净标准是内壁水膜均匀、不挂水珠；残留洗涤剂会改变 pH 或引入杂质。","容量瓶、滴定管等计量仪器不能烘烤，以免体积标定失效。"],"reagents":["去离子水","中性洗涤剂"],"steps":["用洗涤剂与自来水刷洗，再用自来水冲净。","用去离子水润洗三次，观察水膜是否均匀。","计量仪器倒置晾干；烧杯、试管可放入 105 ℃ 烘箱。"],"tags":["基础操作","仪器清洗","实验规范"],"difficulty":1},
{"id":"ops-pipette-calibration","name":"移液管的校准","category":"基础操作","hazard":1,"duration":"30 分钟","summary":"用称量法校准移液管的实际体积，理解温度、读数与挂壁对体积的影响。","principle":["水的质量换算为体积：V = m/ρ，ρ 按水温查表。","校准值可用于修正滴定与配制中的系统误差。"],"reagents":["去离子水"],"steps":["记录水温，查该温度下水的密度。","称量空称量瓶，移取纯水后再次称量。","重复三次，计算平均体积与相对误差。"],"tags":["基础操作","校准","分析化学"],"difficulty":1},
{"id":"ops-burette-cleaning","name":"滴定管的清洗与检漏","category":"基础操作","hazard":1,"duration":"25 分钟","summary":"清洗酸式滴定管、检查旋塞是否漏液，并用待装溶液润洗。","principle":["滴定管残留水会稀释标准溶液，使浓度偏低。","旋塞涂凡士林可密封，但用量过多会堵塞孔道。"],"reagents":["去离子水","待装标准溶液"],"steps":["用洗涤剂与自来水洗净，再用去离子水润洗。","关闭旋塞装水静置 2 分钟，观察是否渗漏。","用待装溶液润洗三次后装液、排气泡、调零。"],"tags":["基础操作","滴定","仪器"],"difficulty":1},
{"id":"ops-desiccator-use","name":"干燥器的使用与干燥剂更换","category":"基础操作","hazard":1,"duration":"20 分钟","summary":"用变色硅胶作干燥剂保存易潮解样品，学习开盖、搬运与干燥剂再生。","principle":["变色硅胶吸湿后由蓝变粉，可烘干再生。","干燥器盖与磨口涂薄层凡士林，靠负压密封。"],"reagents":["变色硅胶"],"steps":["检查硅胶颜色，粉色超过一半时更换。","在磨口涂极薄凡士林，平推盖上盖子。","搬动时一手托底一手扶盖，避免滑落。"],"tags":["基础操作","干燥","样品保存"],"difficulty":1},
{"id":"ops-hot-filtration","name":"热过滤操作","category":"基础操作","hazard":2,"duration":"25 分钟","summary":"用预热漏斗快速过滤热溶液，避免溶质在滤纸上提前结晶。","principle":["溶解度随温度升高而增大，趁热过滤可把不溶杂质与目标产物分离。","漏斗与滤纸预热可减少温差导致的结晶堵塞。"],"reagents":["待过滤热溶液","去离子水"],"steps":["把漏斗放入热水浴预热，折叠滤纸并润湿。","将热溶液沿玻璃棒倒入漏斗，液面不超过滤纸边缘。","滤液自然流下，必要时补充热水减少损失。"],"tags":["基础操作","热过滤","重结晶"],"difficulty":2},
{"id":"ops-weighing-difference","name":"减量法称量","category":"基础操作","hazard":1,"duration":"20 分钟","summary":"用减量法称取易吸湿或易挥发样品，减少转移过程中的质量变化。","principle":["减量法只记录称量瓶前后质量差，样品不必完全倒空。","适用于易吸湿、易挥发或需精确称量的固体。"],"reagents":["待称样品"],"steps":["称量盛有样品的称量瓶，记录质量 m1。","倾斜称量瓶，轻敲瓶壁使样品落入容器。","再次称量称量瓶，记录 m2，样品质量为 m1−m2。"],"tags":["基础操作","称量","分析化学"],"difficulty":1},
{"id":"ops-sample-labeling","name":"样品标签与实验记录","category":"基础操作","hazard":1,"duration":"15 分钟","summary":"规范填写样品名称、浓度、日期、危险性与实验记录，避免混淆与误用。","principle":["标签是化学品追溯的第一道防线；浓度、溶剂、日期缺一不可。","实验记录应实时、可复现，不能事后补写。"],"reagents":["标签纸","记号笔"],"steps":["标签写明名称、化学式、浓度、配制日期与配制人。","危险样品加贴风险标识与注意事项。","同步记录实验条件、现象与异常。"],"tags":["基础操作","实验室管理","安全"],"difficulty":1},
{"id":"ops-reflux-assembly","name":"回流装置的搭建","category":"基础操作","hazard":2,"duration":"30 分钟","summary":"搭建带冷凝管的回流装置，掌握夹持、通水与防暴沸要点。","principle":["回流使挥发性溶剂冷凝后返回烧瓶，可在不损失溶剂的情况下持续加热。","冷凝水必须下进上出，才能充满夹套。"],"reagents":["待回流溶液","沸石"],"steps":["烧瓶中加入溶液与沸石，装冷凝管并用夹子固定。","冷凝水从下口进、上口出，检查是否漏水。","缓慢加热至微沸，控制蒸气不越过冷凝管上口。"],"tags":["基础操作","回流","有机实验"],"difficulty":2},
{"id":"qual-borax-bead","name":"硼砂珠试验","category":"物质性质","hazard":2,"duration":"20 分钟","summary":"用硼砂在铂丝上熔成玻璃珠，观察不同金属氧化物使珠体呈现的特征颜色。","principle":["硼砂受热脱水成玻璃状偏硼酸钠，可溶解金属氧化物形成有色偏硼酸盐。","颜色与金属离子种类和氧化态有关，可用于定性鉴别。"],"reagents":["硼砂","氧化钴","氧化铜","氧化铁"],"steps":["铂丝蘸硼砂在火焰中熔成透明珠。","蘸少量金属氧化物再熔，观察珠体颜色。","冷却后对比钴蓝、铜绿、铁黄等颜色。"],"tags":["物质性质","干法鉴定","焰色"],"difficulty":2},
{"id":"qual-phosphate","name":"磷酸根的检验","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"用硝酸银在中性或弱碱性条件下检验磷酸根，并与卤化银沉淀区分。","principle":["PO₄³⁻ + 3Ag⁺ → Ag₃PO₄↓（黄色）","Ag₃PO₄ 溶于稀硝酸，而 AgCl、AgBr、AgI 不溶。"],"reagents":["磷酸钠溶液","0.1 mol/L 硝酸银","稀硝酸"],"steps":["取磷酸钠溶液，调至中性或弱碱性。","滴加硝酸银，观察黄色沉淀。","加入稀硝酸，沉淀溶解说明为磷酸银。"],"tags":["物质性质","离子检验","磷酸根"],"difficulty":1},
{"id":"qual-bicarbonate","name":"碳酸氢根的检验","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"利用加热分解与氯化钡反应区分碳酸根和碳酸氢根。","principle":["2HCO₃⁻ →(Δ) CO₃²⁻ + CO₂↑ + H₂O","Ba²⁺ 与 CO₃²⁻ 生成 BaCO₃ 沉淀，而 HCO₃⁻ 在稀溶液中不易沉淀。"],"reagents":["碳酸氢钠溶液","氯化钡溶液","稀盐酸","澄清石灰水"],"steps":["取碳酸氢钠溶液加氯化钡，观察是否沉淀。","加热固体碳酸氢钠，将气体通入石灰水。","向原溶液滴加稀盐酸，观察气泡。"],"tags":["物质性质","离子检验","碳酸氢根"],"difficulty":1},
{"id":"qual-sulfite","name":"亚硫酸根的检验","category":"物质性质","hazard":2,"duration":"20 分钟","summary":"用氯化钡沉淀、稀盐酸溶解与品红褪色检验亚硫酸根，并与硫酸根区分。","principle":["SO₃²⁻ + Ba²⁺ → BaSO₃↓（白色）","BaSO₃ 溶于稀盐酸并放出 SO₂，可使品红溶液褪色。"],"reagents":["亚硫酸钠溶液","氯化钡溶液","稀盐酸","品红溶液"],"steps":["取亚硫酸钠溶液加氯化钡，观察白色沉淀。","加稀盐酸，沉淀溶解并有刺激性气体。","将气体通入品红溶液，观察褪色。"],"tags":["物质性质","离子检验","二氧化硫"],"difficulty":2},
{"id":"qual-thiosulfate","name":"硫代硫酸根的检验","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"利用酸化分解生成硫沉淀与二氧化硫，以及使碘水褪色来检验硫代硫酸根。","principle":["S₂O₃²⁻ + 2H⁺ → S↓ + SO₂↑ + H₂O","S₂O₃²⁻ 可还原 I₂：2S₂O₃²⁻ + I₂ → S₄O₆²⁻ + 2I⁻"],"reagents":["硫代硫酸钠溶液","稀盐酸","碘水","淀粉溶液"],"steps":["取硫代硫酸钠溶液加稀盐酸，观察淡黄色沉淀与气体。","另取溶液滴加碘水，观察棕色褪去。","加入淀粉后颜色变化更明显。"],"tags":["物质性质","离子检验","硫代硫酸根"],"difficulty":1},
{"id":"qual-bromide","name":"溴离子的检验","category":"物质性质","hazard":2,"duration":"15 分钟","summary":"用硝酸银生成淡黄色溴化银沉淀，并用氨水与硫代硫酸钠区分氯化银和碘化银。","principle":["Br⁻ + Ag⁺ → AgBr↓（淡黄色）","AgBr 微溶于浓氨水，易溶于硫代硫酸钠溶液。"],"reagents":["溴化钠溶液","硝酸银溶液","浓氨水","硫代硫酸钠溶液"],"steps":["取溴化钠溶液加硝酸银，观察沉淀颜色。","加入少量浓氨水，观察部分溶解。","加入硫代硫酸钠溶液，沉淀完全溶解。"],"tags":["物质性质","离子检验","卤化银"],"difficulty":2},
{"id":"qual-iodide","name":"碘离子的检验","category":"物质性质","hazard":2,"duration":"15 分钟","summary":"用硝酸银生成黄色碘化银沉淀，并观察其在氨水中的难溶性。","principle":["I⁻ + Ag⁺ → AgI↓（黄色）","AgI 不溶于稀硝酸和氨水，可与 AgCl、AgBr 区分。"],"reagents":["碘化钾溶液","硝酸银溶液","稀硝酸","浓氨水"],"steps":["取碘化钾溶液加硝酸银，观察黄色沉淀。","加入稀硝酸，沉淀不溶。","加入浓氨水，沉淀仍不溶。"],"tags":["物质性质","离子检验","碘化银"],"difficulty":2},
{"id":"qual-nitrite","name":"亚硝酸根的检验","category":"物质性质","hazard":2,"duration":"20 分钟","summary":"利用酸化放出红棕色气体与氧化碘离子的性质检验亚硝酸根。","principle":["2NO₂⁻ + 2H⁺ → NO↑ + NO₂↑ + H₂O","2NO₂⁻ + 2I⁻ + 4H⁺ → I₂ + 2NO↑ + 2H₂O"],"reagents":["亚硝酸钠溶液","稀盐酸","碘化钾淀粉试纸"],"steps":["取亚硝酸钠溶液加稀盐酸，观察气体颜色。","用湿润的碘化钾淀粉试纸靠近管口。","试纸变蓝说明生成碘。"],"tags":["物质性质","离子检验","亚硝酸盐"],"difficulty":2},
{"id":"qual-permanganate-media","name":"高锰酸钾在不同介质中的还原产物","category":"物质性质","hazard":2,"duration":"20 分钟","summary":"比较酸性、中性、碱性条件下高锰酸根被还原后的颜色与产物。","principle":["酸性：MnO₄⁻ + 5e⁻ + 8H⁺ → Mn²⁺ + 4H₂O（近无色）","中性：MnO₄⁻ + 3e⁻ + 2H₂O → MnO₂↓ + 4OH⁻（棕色）","强碱：MnO₄⁻ + e⁻ → MnO₄²⁻（绿色）"],"reagents":["高锰酸钾溶液","稀硫酸","亚硫酸钠溶液","氢氧化钠溶液"],"steps":["三支试管分别加酸、水、碱，再各加高锰酸钾。","分别滴加亚硫酸钠至紫色褪去。","比较最终颜色：近无色、棕色浑浊、绿色。"],"tags":["物质性质","氧化还原","高锰酸钾"],"difficulty":2},
{"id":"qual-copper-chloride-complex","name":"氯化铜溶液的颜色与配合物","category":"物质性质","hazard":2,"duration":"15 分钟","summary":"观察氯化铜在不同浓度盐酸中的颜色变化，理解铜氯配合物的形成。","principle":["[Cu(H₂O)₆]²⁺ 呈蓝色，[CuCl₄]²⁻ 呈黄绿色。","增大 Cl⁻ 浓度使平衡向黄色配合物移动。"],"reagents":["氯化铜溶液","浓盐酸","去离子水"],"steps":["观察稀氯化铜溶液的蓝色。","逐滴加入浓盐酸，观察颜色由蓝绿变黄绿。","加水稀释，颜色恢复。"],"tags":["物质性质","配位化学","铜"],"difficulty":2},
{"id":"qual-cobalt-complex","name":"氯化钴的配位平衡与温度效应","category":"物质性质","hazard":2,"duration":"20 分钟","summary":"观察氯化钴在水与浓盐酸中的颜色变化，并研究温度对配位平衡的影响。","principle":["[Co(H₂O)₆]²⁺ 呈粉红色，[CoCl₄]²⁻ 呈蓝色。","CoCl₄²⁻ + 6H₂O ⇌ [Co(H₂O)₆]²⁺ + 4Cl⁻，加热向蓝色移动。"],"reagents":["氯化钴溶液","浓盐酸","去离子水"],"steps":["观察氯化钴稀溶液的粉红色。","加入浓盐酸至变为蓝色。","水浴加热与冰水冷却，观察颜色往返。"],"tags":["物质性质","配位化学","钴"],"difficulty":2},
{"id":"qual-nickel-ammonia","name":"镍氨配合物的生成","category":"物质性质","hazard":2,"duration":"15 分钟","summary":"向镍盐溶液滴加氨水，观察氢氧化镍沉淀生成与过量氨水中的溶解。","principle":["Ni²⁺ + 2NH₃·H₂O → Ni(OH)₂↓ + 2NH₄⁺","Ni(OH)₂ + 6NH₃ → [Ni(NH₃)₆]²⁺ + 2OH⁻（蓝色溶液）"],"reagents":["硫酸镍溶液","稀氨水","浓氨水"],"steps":["取硫酸镍溶液，滴加稀氨水。","观察绿色氢氧化镍沉淀。","继续加过量氨水，沉淀溶解为蓝色溶液。"],"tags":["物质性质","配位化学","镍"],"difficulty":1},
{"id":"qual-iron-oxalate","name":"草酸铁配合物的光敏性","category":"物质性质","hazard":2,"duration":"25 分钟","summary":"制备草酸铁配合物，观察光照后 Fe³⁺ 被还原为 Fe²⁺ 的颜色与检验变化。","principle":["[Fe(C₂O₄)₃]³⁻ 在紫外光或强光下发生配体到金属的电荷转移，生成 Fe²⁺ 与 CO₂。","Fe²⁺ 可用邻二氮菲或铁氰化钾检验。"],"reagents":["氯化铁溶液","草酸钾溶液","铁氰化钾溶液","稀硫酸"],"steps":["混合氯化铁与草酸钾，避光放置。","取一半溶液照光 10 分钟，另一半避光作对照。","分别加入铁氰化钾，比较蓝色沉淀。"],"tags":["物质性质","光化学","铁配合物"],"difficulty":2},
{"id":"qual-potassium-flame","name":"钾的焰色与钴玻璃观察","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"用钴玻璃滤去钠的黄光，观察钾盐的浅紫色焰色。","principle":["钾的焰色为浅紫色，常被钠的黄光掩盖。","钴玻璃吸收黄光，使钾的紫色更易观察。"],"reagents":["氯化钾","浓盐酸"],"steps":["金属丝蘸浓盐酸灼烧至无色。","蘸氯化钾在火焰中灼烧，直接观察。","透过钴玻璃再次观察。"],"tags":["物质性质","焰色反应","钾"],"difficulty":1},
{"id":"qual-copper-flame","name":"铜盐的焰色反应","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"观察铜盐在火焰中呈现的蓝绿色，理解焰色与金属元素的关系。","principle":["铜的原子/离子受热激发，发射特征波长的蓝绿色光。","焰色反应是物理变化，可用于元素定性。"],"reagents":["硫酸铜","浓盐酸"],"steps":["金属丝蘸盐酸灼烧至无色。","蘸少量硫酸铜灼烧。","观察蓝绿色火焰并记录。"],"tags":["物质性质","焰色反应","铜"],"difficulty":1},
{"id":"qual-strontium-flame","name":"锶盐的洋红色焰色","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"观察氯化锶的洋红色焰色，并与钙、钡的焰色对比。","principle":["锶的焰色为洋红色，钙为砖红色，钡为黄绿色。","不同金属元素的发射光谱不同。"],"reagents":["氯化锶","浓盐酸"],"steps":["金属丝洗净灼烧至无色。","蘸氯化锶灼烧，观察洋红色火焰。","与钙盐、钡盐的焰色对比记录。"],"tags":["物质性质","焰色反应","锶"],"difficulty":1},
{"id":"gas-chlorine-water","name":"氯水的性质","category":"气体与燃烧","hazard":2,"duration":"20 分钟","summary":"观察氯水的颜色、酸性与漂白性，理解氯气与水的歧化反应。","principle":["Cl₂ + H₂O ⇌ HCl + HClO","HClO 具有强氧化性，可使有色布条褪色。"],"reagents":["饱和氯水","石蕊溶液","有色布条","硝酸银溶液"],"steps":["观察氯水浅黄绿色与气味。","滴入石蕊，观察先变红后褪色。","放入有色布条，观察褪色；加硝酸银检验氯离子。"],"tags":["气体与燃烧","氯气","漂白"],"difficulty":2},
{"id":"gas-sulfur-dioxide","name":"二氧化硫的性质","category":"气体与燃烧","hazard":3,"duration":"20 分钟","summary":"在通风橱中制取少量 SO₂，观察其漂白性、还原性与酸性。","principle":["S + O₂ →(点燃) SO₂","SO₂ + H₂O ⇌ H₂SO₃；SO₂ 可还原 KMnO₄ 并使品红褪色。"],"reagents":["硫粉","高锰酸钾溶液","品红溶液","紫色石蕊"],"steps":["通风橱内点燃少量硫，收集 SO₂。","通入品红溶液，观察褪色。","通入高锰酸钾与石蕊，观察褪色与变红。"],"tags":["气体与燃烧","二氧化硫","教师演示"],"difficulty":3},
{"id":"gas-hydrogen-chloride-fountain","name":"氯化氢喷泉实验","category":"气体与燃烧","hazard":3,"duration":"20 分钟","summary":"用干燥圆底烧瓶收集 HCl 气体，倒扣入水中形成喷泉，验证其极易溶于水。","principle":["HCl 极易溶于水，1 体积水可溶解约 500 体积 HCl。","瓶内压强骤降，水被压入形成喷泉。"],"reagents":["浓盐酸","浓硫酸","石蕊溶液"],"steps":["浓盐酸滴入浓硫酸干燥，收集 HCl 于干燥烧瓶。","烧瓶倒扣在滴有石蕊的水面上，打开止水夹。","观察水喷入并变红。"],"tags":["气体与燃烧","氯化氢","喷泉实验"],"difficulty":3},
{"id":"gas-carbon-dioxide-density","name":"二氧化碳的密度与阶梯倾倒","category":"气体与燃烧","hazard":1,"duration":"15 分钟","summary":"把 CO₂ 沿烧杯壁倾倒，观察蜡烛自下而上熄灭，理解其密度比空气大。","principle":["CO₂ 相对分子质量 44，密度大于空气。","CO₂ 不助燃，倾倒后可排开空气使火焰熄灭。"],"reagents":["大理石","稀盐酸","蜡烛"],"steps":["制取并收集一瓶 CO₂。","点燃阶梯上的蜡烛。","沿烧杯壁缓慢倾倒 CO₂，观察熄灭顺序。"],"tags":["气体与燃烧","二氧化碳","密度"],"difficulty":1},
{"id":"gas-oxygen-concentration","name":"氧气浓度的检验","category":"气体与燃烧","hazard":1,"duration":"15 分钟","summary":"用带火星木条在空气与纯氧中的复燃程度，比较氧气浓度对燃烧的影响。","principle":["氧气支持燃烧，浓度越高，木条复燃越快、火焰越亮。","带火星木条复燃是检验氧气的常用方法。"],"reagents":["过氧化氢","二氧化锰"],"steps":["用过氧化氢与二氧化锰制取氧气。","收集一瓶氧气，留一瓶空气作对照。","将带火星木条分别伸入两瓶。"],"tags":["气体与燃烧","氧气","燃烧条件"],"difficulty":1},
{"id":"gas-methane-combustion","name":"甲烷燃烧与产物检验","category":"气体与燃烧","hazard":2,"duration":"20 分钟","summary":"点燃甲烷，用干冷烧杯与澄清石灰水检验生成的水和二氧化碳。","principle":["CH₄ + 2O₂ →(点燃) CO₂ + 2H₂O","水蒸气遇冷凝结，CO₂ 使石灰水变浑浊。"],"reagents":["甲烷（或天然气）","澄清石灰水"],"steps":["验纯后点燃甲烷，火焰呈淡蓝色。","将干冷烧杯罩在火焰上方，观察水雾。","将气体通入石灰水，观察浑浊。"],"tags":["气体与燃烧","甲烷","燃烧产物"],"difficulty":2},
{"id":"gas-ethanol-vapor","name":"乙醇蒸气的燃烧","category":"气体与燃烧","hazard":2,"duration":"15 分钟","summary":"加热乙醇使蒸气逸出并点燃，观察淡蓝色火焰与产物。","principle":["C₂H₅OH + 3O₂ →(点燃) 2CO₂ + 3H₂O","蒸气燃烧比液体燃烧更充分，火焰呈淡蓝色。"],"reagents":["无水乙醇"],"steps":["水浴微热乙醇，使蒸气经导管逸出。","在导管口点燃蒸气。","用干冷烧杯与石灰水检验产物。"],"tags":["气体与燃烧","乙醇","燃烧"],"difficulty":2},
{"id":"gas-hydrogen-diffusion","name":"氢气的扩散","category":"气体与燃烧","hazard":2,"duration":"15 分钟","summary":"观察氢气从倒置集气瓶口扩散并与空气混合，理解分子运动与密度差异。","principle":["氢气密度最小，分子运动快，易向上扩散。","氢气与空气混合达到爆炸极限时遇火危险。"],"reagents":["锌粒","稀硫酸","肥皂水"],"steps":["制取并收集一试管氢气，验纯。","将集气瓶倒置，瓶口靠近肥皂泡。","观察气泡上升与扩散。"],"tags":["气体与燃烧","氢气","扩散"],"difficulty":2},
{"id":"gas-effusion","name":"气体扩散速率的比较","category":"气体与燃烧","hazard":2,"duration":"20 分钟","summary":"用氨气与氯化氢在长玻璃管两端扩散，观察白烟生成位置，比较分子运动速率。","principle":["NH₃ + HCl → NH₄Cl（白烟）","相对分子质量越小，扩散越快；NH₃ 比 HCl 扩散快。"],"reagents":["浓氨水","浓盐酸","脱脂棉"],"steps":["两端分别塞入蘸浓氨水与浓盐酸的棉球。","迅速封口，观察白烟出现位置。","测量白烟环偏向 HCl 一端，说明 NH₃ 扩散更快。"],"tags":["气体与燃烧","扩散","氨"],"difficulty":2},
{"id":"gas-nitrogen-dioxide-water","name":"二氧化氮与水的反应","category":"气体与燃烧","hazard":3,"duration":"20 分钟","summary":"观察 NO₂ 溶于水生成硝酸与 NO，理解工业制硝酸的关键步骤。","principle":["3NO₂ + H₂O → 2HNO₃ + NO","2NO + O₂ → 2NO₂，可循环氧化。"],"reagents":["铜片","浓硝酸","石蕊溶液"],"steps":["铜与浓硝酸反应，收集红棕色 NO₂。","将集气瓶倒扣水中，轻摇。","观察红棕色褪去、液面上升，用石蕊检验酸性。"],"tags":["气体与燃烧","氮氧化物","教师演示"],"difficulty":3},
{"id":"elec-nickel-plating","name":"电镀镍","category":"电化学","hazard":2,"duration":"30 分钟","summary":"以镍片为阳极、铜片为阴极，在硫酸镍镀液中电镀出银白色镍层。","principle":["阳极：Ni − 2e⁻ → Ni²⁺","阴极：Ni²⁺ + 2e⁻ → Ni","镀层致密性与电流密度、pH、温度有关。"],"reagents":["硫酸镍","氯化镍","硼酸","除油剂"],"steps":["铜片除油、酸洗、水洗。","配制镀液，控制 pH 4–5、温度 45 ℃。","以 1–2 A/dm² 电镀 10 分钟，水洗干燥。"],"tags":["电化学","电镀","镍"],"difficulty":2},
{"id":"elec-silver-plating","name":"电镀银","category":"电化学","hazard":2,"duration":"30 分钟","summary":"用银电极与银氰化物替代镀液在铜片上镀银，观察镀层光泽。","principle":["阴极：Ag⁺ + e⁻ → Ag","银镀液常用银氨配离子或硫代硫酸银，避免游离氰化物风险。"],"reagents":["硝酸银","硫代硫酸钠","亚硫酸钠","铜片"],"steps":["配制硫代硫酸银镀液，避光。","铜片除油、活化。","小电流电镀 10–15 分钟，水洗抛光。"],"tags":["电化学","电镀","银"],"difficulty":2},
{"id":"elec-polishing","name":"电解抛光","category":"电化学","hazard":2,"duration":"25 分钟","summary":"在不锈钢表面进行阳极电解抛光，观察表面由粗糙变光亮。","principle":["阳极局部溶解速率不同，凸起处优先溶解，使表面平整。","抛光液常用磷酸-硫酸混合体系。"],"reagents":["磷酸","硫酸","不锈钢片"],"steps":["不锈钢片除油、水洗。","以不锈钢为阳极、石墨为阴极，控制电压 5–8 V。","抛光 3–5 分钟后取出，水洗观察。"],"tags":["电化学","电解抛光","金属表面"],"difficulty":2},
{"id":"elec-anodizing","name":"铝的阳极氧化","category":"电化学","hazard":2,"duration":"30 分钟","summary":"以铝片为阳极，在硫酸中氧化生成多孔氧化膜，并用染料染色封孔。","principle":["阳极：2Al + 3H₂O − 6e⁻ → Al₂O₃ + 6H⁺","氧化膜多孔，可吸附染料；沸水封孔后耐蚀性提高。"],"reagents":["硫酸","铝片","染料","去离子水"],"steps":["铝片除油、碱洗、酸洗。","在 15% 硫酸中 15 ℃、1.5 A/dm² 氧化 20 分钟。","染色后沸水封孔 10 分钟。"],"tags":["电化学","阳极氧化","铝"],"difficulty":2},
{"id":"elec-cathodic-protection","name":"阴极保护模拟","category":"电化学","hazard":1,"duration":"20 分钟","summary":"用锌片与铁片连接浸入盐水，比较单独铁片与连接锌片后的腐蚀程度。","principle":["锌比铁活泼，作为牺牲阳极优先失去电子。","铁成为阴极被保护，腐蚀速率显著降低。"],"reagents":["铁片","锌片","食盐水","铁氰化钾"],"steps":["两片铁片打磨除锈，一片连接锌片。","同时浸入盐水，放置 30 分钟。","滴加铁氰化钾，比较蓝色出现程度。"],"tags":["电化学","腐蚀","阴极保护"],"difficulty":1},
{"id":"elec-concentration-cell","name":"浓差电池","category":"电化学","hazard":1,"duration":"25 分钟","summary":"用两个不同浓度的铜离子半电池组成浓差电池，测量电动势并验证能斯特方程。","principle":["浓差电池电动势 E = (0.0592/2)·lg(c₁/c₂)（25 ℃）","浓度差驱动电子从稀侧电极流向浓侧。"],"reagents":["硫酸铜溶液（0.01、1 mol/L）","铜电极","盐桥"],"steps":["搭建两个铜半电池，浓度分别为 0.01 与 1 mol/L。","用盐桥连接，接入电压表。","记录电动势并与理论值比较。"],"tags":["电化学","浓差电池","能斯特方程"],"difficulty":2},
{"id":"elec-saltwater-corrosion","name":"盐水中的腐蚀电池","category":"电化学","hazard":1,"duration":"25 分钟","summary":"把铁钉与铜丝接触后浸入食盐水，观察接触处优先锈蚀，理解电偶腐蚀。","principle":["铁为阳极：Fe − 2e⁻ → Fe²⁺；铜为阴极，发生 O₂ + 2H₂O + 4e⁻ → 4OH⁻。","食盐水提高导电性，加速电偶腐蚀。"],"reagents":["铁钉","铜丝","食盐水","铁氰化钾"],"steps":["铁钉打磨除锈，与铜丝紧密接触。","浸入食盐水，静置 20 分钟。","滴加铁氰化钾，观察蓝色出现位置。"],"tags":["电化学","腐蚀","电偶"],"difficulty":1},
{"id":"elec-coin-battery","name":"硬币电池","category":"电化学","hazard":1,"duration":"20 分钟","summary":"用铜币、锌片与浸盐水的纸片叠成伏打电堆，点亮 LED 并测量电压。","principle":["锌为负极、铜为正极，盐水纸片作电解质。","多个单元串联可提高电压。"],"reagents":["食盐水","白醋","铜币","锌片"],"steps":["纸片浸盐水，夹在铜币与锌片之间。","叠 3–5 组，测量总电压。","接入 LED，观察是否发光。"],"tags":["电化学","原电池","伏打电堆"],"difficulty":1},
{"id":"org-banana-oil","name":"香蕉油的合成与气味","category":"有机","hazard":2,"duration":"40 分钟","summary":"以乙酸与异戊醇在浓硫酸催化下酯化，制取有香蕉气味的乙酸异戊酯。","principle":["CH₃COOH + (CH₃)₂CHCH₂CH₂OH ⇌ CH₃COOCH₂CH₂CH(CH₃)₂ + H₂O","浓硫酸催化并吸水，促进酯化平衡右移。"],"reagents":["冰乙酸","异戊醇","浓硫酸","饱和碳酸钠"],"steps":["按体积比混合异戊醇与冰乙酸，加少量浓硫酸。","回流 30 分钟，冷却。","倒入饱和碳酸钠，分液取有机层，闻气味。"],"tags":["有机","酯化","香蕉油"],"difficulty":2},
{"id":"org-methyl-salicylate","name":"冬青油的水杨酸甲酯合成","category":"有机","hazard":2,"duration":"40 分钟","summary":"水杨酸与甲醇在浓硫酸催化下酯化，制取有冬青气味的无色油状物。","principle":["C₆H₄(OH)COOH + CH₃OH ⇌ C₆H₄(OH)COOCH₃ + H₂O","酚羟基也参与副反应，需控制温度。"],"reagents":["水杨酸","甲醇","浓硫酸","碳酸氢钠"],"steps":["水杨酸与甲醇混合，缓慢加浓硫酸。","水浴回流 40 分钟。","冷却后倒入碳酸氢钠溶液，分液取油层。"],"tags":["有机","酯化","水杨酸甲酯"],"difficulty":2},
{"id":"org-casein-plastic","name":"酪蛋白塑料","category":"有机","hazard":1,"duration":"35 分钟","summary":"从牛奶中提取酪蛋白，用甲醛或加热交联制成可成型的塑料样块。","principle":["酪蛋白在等电点沉淀，甲醛使蛋白质交联硬化。","早期塑料 Galalith 即由酪蛋白制成。"],"reagents":["牛奶","白醋","甲醛溶液（或加热）","碳酸钠"],"steps":["牛奶加热至 50 ℃，加白醋至沉淀。","纱布过滤，收集酪蛋白并压干。","加少量碱与甲醛（或加热）揉捏，压入模具硬化。"],"tags":["有机","蛋白质","塑料"],"difficulty":1},
{"id":"org-starch-plastic","name":"淀粉基可降解塑料","category":"有机","hazard":1,"duration":"35 分钟","summary":"用淀粉、甘油与水加热糊化，压制成可降解薄膜并测试其性能。","principle":["淀粉在加热与水作用下糊化，甘油作增塑剂。","氢键重组形成连续薄膜。"],"reagents":["玉米淀粉","甘油","白醋","蒸馏水"],"steps":["淀粉与水、甘油、少量醋混合。","加热搅拌至透明糊状。","刮涂在玻璃板上，烘干揭膜。"],"tags":["有机","高分子","可降解"],"difficulty":1},
{"id":"org-chlorophyll","name":"叶绿素的提取与荧光","category":"有机","hazard":1,"duration":"30 分钟","summary":"用乙醇提取菠菜叶绿素，在紫外灯下观察红色荧光并分离色素。","principle":["叶绿素溶于乙醇，吸收蓝紫光与红光。","紫外激发后发射红色荧光。"],"reagents":["菠菜叶","无水乙醇","石英砂","碳酸钙"],"steps":["菠菜加乙醇、石英砂研磨，过滤。","滤液在可见光与紫外灯下观察颜色。","用纸层析分离色素并比较荧光。"],"tags":["有机","天然产物","荧光"],"difficulty":1},
{"id":"org-curcumin","name":"姜黄素的提取与酸碱变色","category":"有机","hazard":1,"duration":"30 分钟","summary":"从姜黄粉中提取姜黄素，观察其在酸、碱中的颜色变化与硼酸显色反应。","principle":["姜黄素在碱性条件下由黄色变为红棕色。","与硼酸形成玫瑰红色配合物。"],"reagents":["姜黄粉","乙醇","氢氧化钠溶液","硼酸"],"steps":["姜黄粉用乙醇浸泡、过滤。","滤液分三份，分别加酸、碱、硼酸。","比较颜色并记录。"],"tags":["有机","天然指示剂","姜黄素"],"difficulty":1},
{"id":"org-cellulose-acetate","name":"纤维素醋酸酯的制备","category":"有机","hazard":2,"duration":"40 分钟","summary":"用脱脂棉与乙酸酐在酸催化下乙酰化，制取可成膜的醋酸纤维素。","principle":["纤维素羟基与乙酸酐反应生成醋酸酯。","取代度影响溶解性与成膜性。"],"reagents":["脱脂棉","乙酸酐","冰乙酸","浓硫酸"],"steps":["脱脂棉加冰乙酸润湿，加乙酸酐与少量硫酸。","50 ℃ 水浴反应 30 分钟至透明。","倒入水中沉淀，洗涤干燥，溶于丙酮成膜。"],"tags":["有机","高分子","醋酸纤维素"],"difficulty":2},
{"id":"org-nylon-rope","name":"尼龙纤维的拉丝","category":"有机","hazard":2,"duration":"35 分钟","summary":"界面缩聚制取尼龙 6,10，从界面拉出连续纤维并缠绕。","principle":["己二胺与癸二酰氯在两相界面缩聚生成聚酰胺。","副产 HCl 由碱中和。"],"reagents":["己二胺","癸二酰氯","氢氧化钠","环己烷"],"steps":["下层为己二胺与 NaOH 水溶液，上层为癸二酰氯的环己烷溶液。","在界面处用镊子拉出聚合物丝。","缠绕在玻璃棒上，洗涤干燥。"],"tags":["有机","高分子","缩聚"],"difficulty":2},
{"id":"org-urea-resin","name":"脲醛树脂的固化","category":"有机","hazard":2,"duration":"35 分钟","summary":"尿素与甲醛在酸催化下缩聚固化，观察放热与成型，理解热固性树脂。","principle":["尿素与甲醛生成羟甲基脲，进一步缩聚成网状结构。","固化后不溶不熔。"],"reagents":["尿素","甲醛溶液","氯化铵","氨水"],"steps":["尿素与甲醛按比例混合，调 pH 至弱碱，加热溶解。","加入氯化铵催化，倒入模具。","观察放热、变稠与固化。"],"tags":["有机","高分子","热固性"],"difficulty":2},
{"id":"org-essential-oil","name":"柑橘皮精油的提取","category":"有机","hazard":1,"duration":"30 分钟","summary":"用有机溶剂或冷压法从柑橘皮中提取柠檬烯，观察其气味与溶解性。","principle":["柑橘皮含柠檬烯等萜类，易溶于非极性溶剂。","柠檬烯可使溴水褪色。"],"reagents":["橘子皮","乙醇","石油醚","溴水"],"steps":["橘皮捣碎，用乙醇或石油醚浸泡。","过滤、分液，蒸去溶剂得油状物。","闻气味并滴加溴水观察褪色。"],"tags":["有机","天然产物","精油"],"difficulty":1},
{"id":"sep-froth-flotation","name":"泡沫浮选分离","category":"分离提纯","hazard":1,"duration":"25 分钟","summary":"用表面活性剂泡沫浮选分离亲水与疏水颗粒，模拟矿物浮选。","principle":["疏水颗粒附着气泡上浮，亲水颗粒留在水中。","捕收剂改变颗粒表面润湿性。"],"reagents":["二氧化硅","硫粉","洗洁精","水"],"steps":["混合二氧化硅与硫粉，加水与少量洗洁精。","通入空气产生泡沫。","收集泡沫层，比较上下层成分。"],"tags":["分离提纯","浮选","表面性质"],"difficulty":1},
{"id":"sep-zone-refining","name":"区域熔炼提纯","category":"分离提纯","hazard":1,"duration":"25 分钟","summary":"用萘与少量杂质模拟区域熔炼，观察杂质随熔区向一端富集。","principle":["杂质在固相与液相中分配系数不同。","移动熔区把杂质带到一端。"],"reagents":["萘","油红 O","乙醇"],"steps":["萘与微量油红 O 熔融混匀，装入玻璃管。","用加热环从一端缓慢移动至另一端。","切开分段，比较各段颜色。"],"tags":["分离提纯","区域熔炼","结晶"],"difficulty":1},
{"id":"sep-gel-filtration","name":"凝胶过滤分离蛋白质","category":"分离提纯","hazard":1,"duration":"35 分钟","summary":"用葡聚糖凝胶柱分离蓝色葡聚糖与维生素 B12，理解体积排阻原理。","principle":["大分子不能进入凝胶孔道，先流出。","小分子进入孔道，保留时间更长。"],"reagents":["葡聚糖蓝","维生素 B12","葡聚糖凝胶","缓冲液"],"steps":["装填凝胶柱，用缓冲液平衡。","加入混合样品，开始洗脱。","分段收集，观察蓝色与大分子先出。"],"tags":["分离提纯","凝胶过滤","蛋白质"],"difficulty":2},
{"id":"sep-electrophoresis","name":"纸上电泳分离色素","category":"分离提纯","hazard":2,"duration":"35 分钟","summary":"在湿润滤纸上加直流电场，分离带不同电荷的染料或氨基酸。","principle":["带电粒子在电场中迁移，速率与电荷/质量比有关。","不同物质等电点不同，迁移方向不同。"],"reagents":["混合染料","缓冲液","滤纸"],"steps":["滤纸用缓冲液润湿，点样。","两端接电极，施加 30–50 V。","通电 20 分钟，观察色带分离。"],"tags":["分离提纯","电泳","带电粒子"],"difficulty":2},
{"id":"sep-acid-base-extraction","name":"酸碱萃取分离","category":"分离提纯","hazard":2,"duration":"30 分钟","summary":"用酸碱调节溶解度，把苯甲酸与苯甲酸甲酯从混合液中依次萃取分离。","principle":["苯甲酸与碱成盐进入水相，酯留在有机相。","酸化后苯甲酸重新析出。"],"reagents":["苯甲酸","苯甲酸甲酯","乙醚","碳酸钠","盐酸"],"steps":["混合物溶于乙醚，用碳酸钠溶液萃取。","水相酸化，观察苯甲酸析出。","有机相蒸去乙醚得酯。"],"tags":["分离提纯","萃取","酸碱"],"difficulty":2},
{"id":"sep-precipitation-fractionation","name":"分级沉淀分离蛋白质","category":"分离提纯","hazard":1,"duration":"30 分钟","summary":"用不同浓度硫酸铵盐析，分段沉淀鸡蛋清中的蛋白质。","principle":["高盐浓度破坏水化层与电荷，使蛋白质按溶解度先后沉淀。","盐析可逆，不使蛋白质变性。"],"reagents":["鸡蛋清","硫酸铵","缓冲液"],"steps":["蛋清稀释、过滤。","缓慢加入硫酸铵至 30% 饱和度，离心收集沉淀。","上清继续加至 60%，分别收集并透析。"],"tags":["分离提纯","盐析","蛋白质"],"difficulty":1},
{"id":"sep-membrane-osmosis","name":"半透膜与渗透压","category":"分离提纯","hazard":1,"duration":"25 分钟","summary":"用鸡蛋膜或透析袋分隔糖水与纯水，观察液面上升并估算渗透压。","principle":["水分子通过半透膜向高浓度一侧扩散。","渗透压与浓度、温度有关。"],"reagents":["蔗糖溶液","蒸馏水","碘液"],"steps":["透析袋装蔗糖溶液，插玻璃管。","浸入纯水，记录液面初始高度。","每隔 5 分钟记录上升高度。"],"tags":["分离提纯","渗透","半透膜"],"difficulty":1},
{"id":"sep-centrifugal-separation","name":"离心分离与沉降","category":"分离提纯","hazard":1,"duration":"25 分钟","summary":"比较自然沉降与离心沉降的速度，分离碳酸钙悬浊液并计算相对离心力。","principle":["离心力场加速颗粒沉降，沉降速度与粒径、密度差有关。","相对离心力 RCF = 1.118×10⁻⁵·r·n²。"],"reagents":["碳酸钙悬浊液","蒸馏水"],"steps":["配制均匀悬浊液，分装两管。","一管自然静置，一管离心 3 分钟。","比较上清液澄清度与沉降体积。"],"tags":["分离提纯","离心","沉降"],"difficulty":1},
{"id":"quant-partition-coefficient","name":"分配系数的测定","category":"定量测量","hazard":1,"duration":"35 分钟","summary":"用碘在四氯化碳与水中的分配，测定分配系数并验证温度的影响。","principle":["I₂ 在两相中达到平衡时，浓度比在定温下为常数 Kd。","用硫代硫酸钠滴定两相碘浓度。"],"reagents":["碘的四氯化碳溶液","碘化钾","硫代硫酸钠","淀粉指示剂"],"steps":["碘溶液与水在分液漏斗中振荡达平衡。","分出两相，分别用硫代硫酸钠滴定。","计算 Kd 并比较不同温度。"],"tags":["定量测量","分配系数","萃取"],"difficulty":2},
{"id":"quant-adsorption-isotherm","name":"活性炭吸附等温线","category":"定量测量","hazard":1,"duration":"40 分钟","summary":"用不同浓度亚甲基蓝溶液与活性炭平衡，绘制吸附等温线并拟合 Langmuir 模型。","principle":["吸附量 q = (c₀−c)V/m。","Langmuir 模型 q = qmax·Kc/(1+Kc)。"],"reagents":["亚甲基蓝","活性炭","蒸馏水"],"steps":["配制系列浓度亚甲基蓝，加入等量活性炭。","振荡平衡后离心，测上清吸光度。","计算吸附量并作图。"],"tags":["定量测量","吸附","等温线"],"difficulty":2},
{"id":"quant-enzyme-kinetics","name":"酶促反应动力学","category":"定量测量","hazard":1,"duration":"40 分钟","summary":"用过氧化氢酶催化 H₂O₂ 分解，测不同底物浓度下的初速率并求 Km。","principle":["米氏方程 v = Vmax[S]/(Km+[S])。","用排水集气或高锰酸钾滴定测 H₂O₂ 消耗。"],"reagents":["过氧化氢","马铃薯提取液","高锰酸钾","硫酸"],"steps":["配制系列 H₂O₂ 浓度，加入定量酶液。","固定时间终止反应，滴定剩余 H₂O₂。","计算初速率，作 Lineweaver-Burk 图求 Km。"],"tags":["定量测量","酶动力学","米氏方程"],"difficulty":2},
{"id":"quant-refractive-index","name":"折射率法测糖浓度","category":"定量测量","hazard":1,"duration":"30 分钟","summary":"用阿贝折射仪测系列蔗糖溶液的折射率，绘制标准曲线并测定未知样。","principle":["溶液折射率随溶质浓度线性增加。","通过标准曲线由折射率反推浓度。"],"reagents":["蔗糖","蒸馏水","未知糖液"],"steps":["配制 0–30% 蔗糖标准系列。","恒温 20 ℃，依次测折射率。","绘制 n–c 曲线，测未知样并计算浓度。"],"tags":["定量测量","折射率","糖度"],"difficulty":2},
{"id":"quant-turbidimetric-sulfate","name":"浊度法测硫酸根","category":"定量测量","hazard":2,"duration":"35 分钟","summary":"用氯化钡生成硫酸钡悬浊液，在 420 nm 测浊度并绘制标准曲线。","principle":["Ba²⁺ + SO₄²⁻ → BaSO₄↓","悬浊液吸光度与硫酸根浓度在一定范围成正比。"],"reagents":["硫酸钠标准液","氯化钡","明胶溶液","盐酸"],"steps":["配制硫酸根标准系列。","加入酸性氯化钡与稳定剂，摇匀静置。","测吸光度，绘制标准曲线并测水样。"],"tags":["定量测量","浊度","硫酸根"],"difficulty":2},
{"id":"quant-standard-addition","name":"标准加入法测微量铁","category":"定量测量","hazard":2,"duration":"35 分钟","summary":"用邻二氮菲显色，通过标准加入法消除基体干扰，测定水样微量铁。","principle":["Fe²⁺ 与邻二氮菲生成橙红色配合物，λmax≈510 nm。","标准加入法外推求原浓度。"],"reagents":["邻二氮菲","盐酸羟胺","乙酸铵缓冲液","铁标准液"],"steps":["水样分五份，分别加入 0、1、2、3、4 μg 铁标准。","依次加还原剂、缓冲液、显色剂，定容。","测吸光度，作 A–加入量图外推。"],"tags":["定量测量","分光光度法","标准加入法"],"difficulty":2},
{"id":"quant-gas-analysis","name":"气体混合物的吸收分析","category":"定量测量","hazard":2,"duration":"35 分钟","summary":"用不同吸收液依次吸收 CO₂、O₂ 与 CO，通过体积减少量分析混合气体组成。","principle":["CO₂ 被 KOH 吸收，O₂ 被焦性没食子酸吸收，CO 被氯化亚铜吸收。","体积差即各组分体积。"],"reagents":["氢氧化钾","焦性没食子酸","氯化亚铜","混合气体"],"steps":["量取混合气体体积。","依次通过三种吸收液，每次记录体积。","计算各组分体积分数。"],"tags":["定量测量","气体分析","吸收"],"difficulty":2},
{"id":"quant-thermogravimetric","name":"热重法测结晶水","category":"定量测量","hazard":2,"duration":"30 分钟","summary":"用热重分析或分段灼烧测定 CuSO₄·5H₂O 的结晶水数目。","principle":["CuSO₄·5H₂O 分步失水，质量损失对应水的物质的量。","无水 CuSO₄ 继续高温分解。"],"reagents":["硫酸铜晶体","无水乙醇"],"steps":["称量坩埚与晶体，分段加热至 150、250、400 ℃。","每段冷却称量，记录质量。","计算失水百分比与结晶水数。"],"tags":["定量测量","热重","结晶水"],"difficulty":2},
{"id":"fun-magic-sand","name":"防水魔术沙","category":"趣味演示","hazard":1,"duration":"15 分钟","summary":"用疏水涂层处理细沙，制成入水不湿、可水下成型的魔术沙。","principle":["疏水层使水无法润湿沙粒表面。","水下的空气层使沙保持干燥。"],"reagents":["细沙","防水喷雾（含氟或硅烷）","水"],"steps":["细沙铺开，均匀喷防水剂，晾干。","把沙倒入水中，观察不湿。","在水中捏成型后取出。"],"tags":["趣味演示","疏水","表面张力"],"difficulty":1},
{"id":"fun-superabsorbent","name":"高吸水性树脂","category":"趣味演示","hazard":1,"duration":"20 分钟","summary":"从纸尿裤中取出高吸水性树脂，测试其吸水倍率与盐水中的性能下降。","principle":["聚丙烯酸钠 network 通过渗透压与氢键吸水。","盐离子屏蔽电荷，吸水倍率下降。"],"reagents":["纸尿裤","蒸馏水","食盐水","食用色素"],"steps":["剪开纸尿裤，收集白色颗粒。","分别加入纯水与盐水，观察膨胀。","称量并计算吸水倍率。"],"tags":["趣味演示","高分子","吸水"],"difficulty":1},
{"id":"fun-thermochromic","name":"温致变色材料","category":"趣味演示","hazard":1,"duration":"25 分钟","summary":"用热致变色颜料涂在卡片上，用吹风机或冰袋观察颜色可逆变化。","principle":["热致变色体系在晶型或电子结构变化时改变吸收波长。","温度阈值附近颜色可逆切换。"],"reagents":["热致变色颜料","透明胶","卡纸"],"steps":["颜料与透明胶混合，涂在卡纸上晾干。","用热风加热，观察变色。","用冰袋冷却，观察恢复。"],"tags":["趣味演示","变色材料","温度"],"difficulty":1},
{"id":"fun-photochromic","name":"光致变色镜片","category":"趣味演示","hazard":1,"duration":"20 分钟","summary":"用光致变色微胶囊涂层制作感光卡片，在紫外灯下显色、暗处褪色。","principle":["螺吡喃等分子在紫外光下开环显色。","可见光或暗处闭环褪色。"],"reagents":["光致变色颜料","透明胶","卡纸"],"steps":["颜料涂在卡纸上，暗处晾干。","用纸板遮挡一半，紫外灯照射 1 分钟。","比较遮光与曝光区域，移入暗处观察恢复。"],"tags":["趣味演示","光致变色","光化学"],"difficulty":1},
{"id":"fun-bouncing-ball","name":"弹力球的合成","category":"趣味演示","hazard":1,"duration":"25 分钟","summary":"用聚乙烯醇与硼砂交联制成弹性凝胶球，测试不同配比的回弹高度。","principle":["硼砂与 PVA 的羟基形成交联，凝胶具有弹性。","交联密度影响硬度与回弹。"],"reagents":["聚乙烯醇","硼砂","食用色素","水"],"steps":["PVA 加热溶解，冷却。","加入硼砂溶液，搅拌至凝胶。","取出揉成球，测回弹高度并比较配比。"],"tags":["趣味演示","高分子","交联"],"difficulty":1},
{"id":"fun-shape-memory","name":"形状记忆合金","category":"趣味演示","hazard":2,"duration":"20 分钟","summary":"用镍钛合金丝弯折后加热，观察其恢复原状，理解马氏体相变。","principle":["镍钛合金在低温马氏体相可变形，加热到奥氏体相恢复原形。","相变温度约 60–80 ℃。"],"reagents":["镍钛合金丝","热水"],"steps":["把合金丝弯成螺旋，记录形状。","放入热水，观察恢复。","冷却后可再次弯折。"],"tags":["趣味演示","形状记忆","相变"],"difficulty":1},
{"id":"life-vinegar-acidity","name":"食醋酸度的测定","category":"生活化学","hazard":1,"duration":"25 分钟","summary":"用氢氧化钠标准液滴定食醋，测定总酸度并比较不同品牌。","principle":["CH₃COOH + NaOH → CH₃COONa + H₂O","以酚酞为指示剂，终点 pH≈8.2。"],"reagents":["食醋","氢氧化钠标准液","酚酞"],"steps":["食醋稀释 10 倍，取 20 mL。","加酚酞，用 NaOH 滴定至微红。","计算总酸度（以乙酸计）。"],"tags":["生活化学","滴定","食醋"],"difficulty":1},
{"id":"life-baking-powder","name":"泡打粉的产气能力","category":"生活化学","hazard":1,"duration":"25 分钟","summary":"比较泡打粉、小苏打与酵母遇酸/加热的产气量，评价膨松效果。","principle":["碳酸氢钠与酸反应放出 CO₂。","泡打粉含酸性盐，遇水即反应；酵母产气慢。"],"reagents":["泡打粉","小苏打","食醋","酵母","温水"],"steps":["等量样品装入锥形瓶，套气球。","分别加醋或温水，计时观察气球膨胀。","比较产气体积与速度。"],"tags":["生活化学","膨松剂","二氧化碳"],"difficulty":1},
{"id":"life-milk-fat","name":"牛奶脂肪的分离","category":"生活化学","hazard":1,"duration":"30 分钟","summary":"用静置、离心与加热比较全脂与脱脂牛奶的脂肪层，理解乳浊液稳定性。","principle":["脂肪以乳滴分散，静置可上浮。","离心加速乳析；加热破坏部分乳化。"],"reagents":["全脂牛奶","脱脂牛奶","食用色素"],"steps":["两种牛奶分装离心管，静置 30 分钟观察。","离心 5 分钟后测脂肪层厚度。","加热后再次比较。"],"tags":["生活化学","乳浊液","脂肪"],"difficulty":1},
{"id":"life-detergent-foam","name":"洗涤剂泡沫与去污力","category":"生活化学","hazard":1,"duration":"30 分钟","summary":"比较肥皂、洗洁精与洗衣液在硬水中的泡沫高度与去油污效果。","principle":["表面活性剂降低水的表面张力，形成泡沫。","钙镁离子与肥皂生成沉淀，降低去污力。"],"reagents":["肥皂水","洗洁精","洗衣液","硬水","油污布片"],"steps":["等量洗涤剂加入等量软水/硬水，振荡后测泡沫高度。","油污布片分别洗涤，比较去污。","记录硬水对泡沫的影响。"],"tags":["生活化学","表面活性剂","硬水"],"difficulty":1},
{"id":"life-rust-removal","name":"家庭除锈与防锈","category":"生活化学","hazard":2,"duration":"30 分钟","summary":"用食醋、柠檬酸与草酸比较除锈效果，并测试涂油、镀锌的防锈差异。","principle":["酸溶解铁的氧化物：Fe₂O₃ + 6H⁺ → 2Fe³⁺ + 3H₂O。","涂层隔绝氧气与水，减缓腐蚀。"],"reagents":["生锈铁钉","食醋","柠檬酸","草酸","食用油"],"steps":["铁钉分四组：醋、柠檬酸、草酸、清水对照。","浸泡 20 分钟，刷洗比较除锈程度。","一组涂油，与未涂油组放置一周比较锈蚀。"],"tags":["生活化学","除锈","腐蚀"],"difficulty":2},
{"id":"life-water-softening","name":"水的软化与硬度","category":"生活化学","hazard":2,"duration":"30 分钟","summary":"用煮沸、石灰苏打与离子交换比较硬水软化效果，并用肥皂法测硬度。","principle":["煮沸去除暂时硬度，石灰苏打法去除部分永久硬度。","离子交换树脂用 Na⁺ 交换 Ca²⁺、Mg²⁺。"],"reagents":["硬水","石灰水","碳酸钠","肥皂水","离子交换树脂"],"steps":["硬水分四份：煮沸、石灰苏打、离子交换、对照。","各取等量，滴加肥皂水至泡沫稳定，记录用量。","比较软化效果。"],"tags":["生活化学","水硬度","软化"],"difficulty":2},
{"id":"life-water-filter","name":"自制净水器","category":"生活化学","hazard":1,"duration":"30 分钟","summary":"用活性炭、石英砂、棉布分层制作净水器，比较浊度、色度与余氯去除。","principle":["砂层截留悬浮物，活性炭吸附有机物与余氯。","过滤不能去除溶解性无机盐与微生物。"],"reagents":["浑浊水样","活性炭","石英砂","漂白水"],"steps":["瓶底铺棉布，依次装砂、活性炭、砂。","倒入浑浊水样，收集滤液。","比较过滤前后的浊度、颜色与余氯。"],"tags":["生活化学","净水","活性炭"],"difficulty":1},
{"id":"env-water-ph","name":"水样 pH 的现场测定","category":"环境检测","hazard":1,"duration":"25 分钟","summary":"用 pH 试纸、便携 pH 计与指示剂三种方法测定水样 pH，比较精度与适用场景。","principle":["pH = −lg a(H⁺)。","指示剂法精度低，pH 计需两点校准。"],"reagents":["水样","广泛 pH 试纸","溴甲酚绿指示剂","标准缓冲液"],"steps":["水样分三份，分别用试纸、指示剂、pH 计测定。","记录温度与读数。","比较三种方法的偏差。"],"tags":["环境检测","pH","水质"],"difficulty":1},
{"id":"env-water-conductivity","name":"水样电导率与溶解盐","category":"环境检测","hazard":1,"duration":"25 分钟","summary":"测定自来水、矿泉水、纯净水与盐水的电导率，估算溶解性总固体。","principle":["电导率反映水中离子浓度与迁移能力。","TDS ≈ k·EC，k 因水样而异。"],"reagents":["水样","氯化钠标准液","去离子水"],"steps":["用电导率仪依次测水样，记录温度。","用 NaCl 标准液校准电极。","比较电导率并估算 TDS。"],"tags":["环境检测","电导率","TDS"],"difficulty":1},
{"id":"env-residual-chlorine","name":"余氯的比色测定","category":"环境检测","hazard":2,"duration":"30 分钟","summary":"用 DPD 或邻联甲苯胺比色法测定自来水余氯，比较放置前后的变化。","principle":["余氯氧化 DPD 生成红色化合物，颜色与浓度成正比。","余氯随时间挥发或消耗而下降。"],"reagents":["DPD 试剂","余氯标准液","自来水"],"steps":["配制余氯标准系列，显色后测吸光度。","水样显色测定，计算浓度。","放置 2 小时后重复测定。"],"tags":["环境检测","余氯","比色"],"difficulty":2},
{"id":"env-nitrate","name":"水中硝酸盐的快速检测","category":"环境检测","hazard":2,"duration":"30 分钟","summary":"用镉还原-重氮化比色法或硝酸盐试纸测定水样硝酸盐，评价农业面源污染。","principle":["NO₃⁻ 还原为 NO₂⁻ 后重氮化偶联显色。","颜色深浅与硝酸盐浓度相关。"],"reagents":["硝酸盐标准液","镉柱或还原剂","显色试剂","水样"],"steps":["标准系列还原、显色、测吸光度。","水样同样处理。","计算硝酸盐浓度并与标准限值比较。"],"tags":["环境检测","硝酸盐","比色"],"difficulty":2},
{"id":"env-phosphate","name":"水中磷酸盐与富营养化","category":"环境检测","hazard":2,"duration":"35 分钟","summary":"用钼酸铵-抗坏血酸比色法测定磷酸盐，结合藻类培养讨论富营养化。","principle":["磷酸盐与钼酸铵生成磷钼蓝，颜色与浓度成正比。","磷是藻类生长的限制因子。"],"reagents":["磷酸盐标准液","钼酸铵","抗坏血酸","硫酸"],"steps":["标准系列显色，测 700 nm 吸光度。","水样过滤后同样显色。","计算磷酸盐浓度。"],"tags":["环境检测","磷酸盐","富营养化"],"difficulty":2},
{"id":"env-turbidity","name":"浊度的测定与絮凝","category":"环境检测","hazard":1,"duration":"30 分钟","summary":"用浊度计测定水样浊度，并比较明矾、聚合氯化铝的絮凝效果。","principle":["浊度反映悬浮颗粒对光的散射。","絮凝剂中和电荷、架桥使颗粒沉降。"],"reagents":["高岭土悬浊液","明矾","聚合氯化铝","水样"],"steps":["配制系列浊度标准，校准浊度计。","水样测浊度，分三份加不同絮凝剂。","静置后测上清浊度。"],"tags":["环境检测","浊度","絮凝"],"difficulty":1},
{"id":"env-soil-ph","name":"土壤 pH 与缓冲性","category":"环境检测","hazard":1,"duration":"30 分钟","summary":"用土壤浸提液测 pH，并比较加酸/碱后的 pH 变化，评价土壤缓冲能力。","principle":["土壤胶体与碳酸盐、有机质提供缓冲。","缓冲容量大的土壤 pH 变化小。"],"reagents":["土壤样品","蒸馏水","稀盐酸","氢氧化钠","氯化钾"],"steps":["土壤与水按 1:2.5 混合，搅拌静置，测上清 pH。","分两份，分别加等量酸、碱，测 pH 变化。","比较不同土壤的缓冲性。"],"tags":["环境检测","土壤","pH"],"difficulty":1},
{"id":"env-air-co2","name":"室内空气二氧化碳监测","category":"环境检测","hazard":1,"duration":"25 分钟","summary":"用二氧化碳传感器或指示剂吸收法比较通风前后室内 CO₂ 浓度。","principle":["CO₂ 溶于水生成碳酸，使指示剂变色。","通风可稀释室内 CO₂。"],"reagents":["溴百里酚蓝指示剂","氢氧化钡","室内空气"],"steps":["关闭门窗 30 分钟，测 CO₂ 浓度。","开窗通风 10 分钟，再测。","用指示剂吸收法对照。"],"tags":["环境检测","二氧化碳","室内空气"],"difficulty":1},
{"id":"env-acid-rain","name":"模拟酸雨对大理石的侵蚀","category":"环境检测","hazard":2,"duration":"30 分钟","summary":"用不同 pH 的硫酸溶液浸泡大理石片，测质量损失与表面变化，模拟酸雨侵蚀。","principle":["CaCO₃ + H₂SO₄ → CaSO₄ + CO₂↑ + H₂O","酸性越强，侵蚀越快。"],"reagents":["大理石片","稀硫酸","pH 试纸"],"steps":["大理石片称重，分别浸入 pH 2、4、6 的硫酸。","每 10 分钟观察气泡，2 小时后取出干燥称重。","计算质量损失并比较。"],"tags":["环境检测","酸雨","碳酸钙"],"difficulty":2},
{"id":"env-ammonia-nitrogen","name":"水中氨氮的测定","category":"环境检测","hazard":2,"duration":"35 分钟","summary":"用纳氏试剂比色法测定水样氨氮，评价生活污水与养殖废水污染。","principle":["NH₃/NH₄⁺ 与纳氏试剂生成黄棕色配合物。","颜色与氨氮浓度成正比。"],"reagents":["纳氏试剂","氨氮标准液","酒石酸钾钠","水样"],"steps":["标准系列显色，测 420 nm 吸光度。","水样加掩蔽剂后显色测定。","计算氨氮浓度。"],"tags":["环境检测","氨氮","比色"],"difficulty":2},
{"id":"env-cod","name":"化学需氧量的测定","category":"环境检测","hazard":3,"duration":"60 分钟","summary":"用重铬酸钾法测定水样 COD，理解强氧化剂消解与滴定回算。","principle":["有机质被 Cr₂O₇²⁻ 氧化，剩余氧化剂用 Fe²⁺ 回滴。","COD 以消耗 O₂ 的等效量表示。"],"reagents":["重铬酸钾标准液","硫酸亚铁铵","硫酸银","硫酸汞","试亚铁灵"],"steps":["水样加重铬酸钾、硫酸银、硫酸汞，回流 2 小时。","冷却后加指示剂，用硫酸亚铁铵滴定。","空白对照，计算 COD。"],"tags":["环境检测","COD","教师演示"],"difficulty":3},
{"id":"env-bod","name":"生化需氧量的简化测定","category":"环境检测","hazard":2,"duration":"50 分钟","summary":"用溶解氧探头测水样培养 5 天前后的 DO 差，估算 BOD₅。","principle":["微生物分解有机物消耗溶解氧。","BOD₅ = (DO₀ − DO₅) × 稀释倍数。"],"reagents":["水样","稀释水","接种液","营养盐"],"steps":["水样稀释、接种，装满 BOD 瓶。","测初始 DO，20 ℃ 暗处培养 5 天。","测终点 DO，计算 BOD₅。"],"tags":["环境检测","BOD","溶解氧"],"difficulty":2},
{"id":"life-tea-ph","name":"茶汤颜色与 pH","category":"生活化学","hazard":1,"duration":"25 分钟","summary":"比较绿茶、红茶、菊花茶在不同 pH 下的颜色，理解茶多酚的酸碱显色。","principle":["茶多酚在碱性条件下氧化、颜色加深。","柠檬酸降低 pH，颜色变浅。"],"reagents":["茶叶","热水","柠檬酸","小苏打","pH 试纸"],"steps":["三种茶泡制、过滤。","各分三份，分别加酸、碱、对照。","比较颜色与 pH。"],"tags":["生活化学","茶多酚","pH"],"difficulty":1},
{"id":"life-honey-test","name":"蜂蜜掺假的简单鉴别","category":"生活化学","hazard":1,"duration":"25 分钟","summary":"用碘液、酒精与燃烧法比较纯蜂蜜与糖浆掺假样品的差异。","principle":["掺入淀粉糖浆遇碘变蓝。","纯蜂蜜含水量低、燃烧较稳定。"],"reagents":["蜂蜜","糖浆","碘液","乙醇"],"steps":["样品加水溶解，滴碘液观察。","加乙醇观察沉淀。","用玻璃棒蘸取少量在火焰上加热，比较气味与燃烧。"],"tags":["生活化学","蜂蜜","鉴别"],"difficulty":1},
{"id":"life-fruit-ripening","name":"水果成熟与乙烯","category":"生活化学","hazard":1,"duration":"30 分钟","summary":"把未熟水果与熟香蕉同袋放置，观察乙烯对成熟的影响，并用高锰酸钾检验乙烯。","principle":["乙烯是植物天然成熟激素。","高锰酸钾氧化乙烯而褪色。"],"reagents":["未熟猕猴桃","熟香蕉","高锰酸钾溶液"],"steps":["猕猴桃分装两袋，一袋放熟香蕉。","每天观察硬度与颜色。","抽取袋内气体通入高锰酸钾，观察褪色。"],"tags":["生活化学","乙烯","成熟"],"difficulty":1},
{"id":"life-stain-removal","name":"污渍去除与表面活性剂","category":"生活化学","hazard":1,"duration":"30 分钟","summary":"比较冷水、热水、洗涤剂、酶制剂对油渍、血渍、茶渍的去除效果。","principle":["表面活性剂胶束增溶油污。","酶分解蛋白质/淀粉污渍；血渍遇热变性更难去除。"],"reagents":["油渍布","血渍布","茶渍布","洗涤剂","蛋白酶"],"steps":["布片分组，分别用不同温度与洗涤剂处理。","固定时间揉洗，干燥后比较残留。","记录最佳条件。"],"tags":["生活化学","去污","酶"],"difficulty":1},
{"id":"life-egg-freshness","name":"鸡蛋新鲜度的化学判断","category":"生活化学","hazard":1,"duration":"25 分钟","summary":"用盐水浮沉、气室大小与蛋清 pH 判断鸡蛋新鲜度。","principle":["鸡蛋存放后水分蒸发、气室变大、密度下降。","蛋清 pH 随存放上升。"],"reagents":["鸡蛋","食盐水","pH 试纸"],"steps":["配制不同浓度盐水，观察鸡蛋浮沉。","强光照射观察气室大小。","打蛋测蛋清 pH。"],"tags":["生活化学","鸡蛋","新鲜度"],"difficulty":1},
{"id":"life-flour-gluten","name":"面粉筋力与蛋白质","category":"生活化学","hazard":1,"duration":"30 分钟","summary":"洗出面筋比较高筋、中筋、低筋面粉的蛋白质含量与面团弹性。","principle":["面粉中的麦谷蛋白与醇溶蛋白遇水形成面筋。","蛋白质含量决定筋力。"],"reagents":["高筋面粉","低筋面粉","食盐","水"],"steps":["等量面粉加水揉成团，静置。","纱布包住面团在水中揉洗，收集面筋。","称量湿面筋并烘干，计算蛋白质比例。"],"tags":["生活化学","面粉","蛋白质"],"difficulty":1},
{"id":"life-oil-rancidity","name":"油脂酸败的检测","category":"生活化学","hazard":1,"duration":"30 分钟","summary":"用酸价试纸或滴定比较新鲜油与反复加热油的酸败程度。","principle":["油脂水解与氧化产生游离脂肪酸与过氧化物。","酸价越高，酸败越明显。"],"reagents":["新鲜食用油","反复加热油","氢氧化钾乙醇液","酚酞"],"steps":["油样加乙醇-乙醚溶解，加酚酞。","用 KOH 滴定至微红，计算酸价。","比较新鲜油与煎炸油的酸价。"],"tags":["生活化学","油脂","酸价"],"difficulty":2},
{"id":"life-food-dye","name":"食品色素的纸层析鉴别","category":"生活化学","hazard":1,"duration":"30 分钟","summary":"用纸层析分离饮料与糖果中的合成色素，并与标准色素比对。","principle":["不同色素在固定相与流动相中分配系数不同。","比移值 Rf 可用于定性。"],"reagents":["彩色饮料","糖果","标准色素","展开剂"],"steps":["饮料浓缩，糖果用乙醇提取。","点样、展开，记录色斑。","与标准色素比对 Rf。"],"tags":["生活化学","食品色素","层析"],"difficulty":1},
{"id":"nail-rust","name":"铁钉生锈的条件","category":"物质性质","hazard":1,"duration":"30 分钟 + 观察数天","summary":"把铁钉分别放在干燥空气、煮沸的蒸馏水、以及水和空气都有的环境里，几天后对比，找出铁生锈真正需要的两个条件。","principle":["4Fe + 3O₂ + 6H₂O  →  4Fe(OH)₃（进一步脱水生成铁锈 Fe₂O₃·xH₂O）"],"reagents":["铁钉 ×3","蒸馏水","植物油","干燥剂（无水氯化钙）"],"steps":["三支试管编号 A、B、C。","A 管放入干燥剂与铁钉，塞紧；B 管加煮沸后冷却的蒸馏水浸没铁钉，水面加油封；C 管加少量自来水，铁钉一半浸在水里，敞口。","把三支试管放在同一位置，每天观察并记录。","3～5 天后比较三支试管中铁钉的生锈情况。"],"tags":["初中"],"difficulty":1},
{"id":"red-cabbage-indicator-lab","name":"紫甘蓝自制酸碱指示剂","category":"生活化学","hazard":1,"duration":"20 分钟","summary":"用紫甘蓝煮出紫色汁液，分别滴进白醋、小苏打水和肥皂水，看它把酸、碱、中性区分成几种颜色。","principle":["花青素在不同 pH 下结构改变，颜色随之变化（pH＜7 偏红，pH≈7 紫色，pH＞7 偏蓝绿）。"],"reagents":["紫甘蓝叶","白醋","小苏打溶液","肥皂水","蒸馏水"],"steps":["把紫甘蓝叶撕碎，加水煮沸 5 分钟，过滤得到紫色汁液。","把汁液分装到 5 支试管，各约 1 mL。","分别滴入白醋、小苏打溶液、肥皂水、蒸馏水并摇匀。","把颜色与 pH 试纸的结果对照记录。"],"tags":["初中"],"difficulty":1},
{"id":"starch-test","name":"碘液检验淀粉","category":"物质性质","hazard":1,"duration":"15 分钟","summary":"把碘液滴在各种食物上，看谁变蓝：淀粉遇碘生成深蓝色包合物，是食物成分检测里最快的一项。","principle":["I₂ + 淀粉  →  蓝色包合物（碘分子进入淀粉螺旋空腔）"],"reagents":["碘液（卢戈氏碘液）","淀粉溶液","米饭、土豆、苹果切片","蒸馏水"],"steps":["在点滴板上分别放一小块米饭、土豆片、苹果片。","各滴一滴碘液，观察 30 秒内的颜色变化。","用淀粉溶液与蒸馏水做对照。","记录哪些样品变蓝，哪些不变。"],"tags":["初中"],"difficulty":1},
{"id":"protein-salting-out","name":"蛋白质的盐析与变性","category":"有机","hazard":1,"duration":"25 分钟","summary":"向鸡蛋清溶液里加盐、加热、加酸，对比“能变回去”的盐析与“回不去”的变性。","principle":["盐析：加入高浓度中性盐使蛋白质溶解度降低而析出，稀释后可复溶。","变性：加热、强酸强碱、重金属盐使蛋白质空间结构破坏，不可逆。"],"reagents":["鸡蛋清溶液","饱和硫酸铵溶液","稀盐酸","硫酸铜溶液","蒸馏水"],"steps":["取 4 支试管各加 2 mL 蛋清溶液。","第 1 支加入饱和硫酸铵溶液，观察沉淀，再加蒸馏水稀释看是否复溶。","第 2 支加热至沸腾，观察凝固。","第 3 支滴加稀盐酸，第 4 支滴加硫酸铜溶液，分别观察。"],"tags":["高中"],"difficulty":2},
{"id":"hard-water","name":"硬水的检验与软化","category":"生活化学","hazard":1,"duration":"30 分钟","summary":"用肥皂水判断水的硬度，再分别用煮沸和离子交换把它软化，比较两种方法的效果。","principle":["Ca²⁺、Mg²⁺ + 肥皂（硬脂酸钠）  →  难溶的硬脂酸钙/镁沉淀，泡沫减少","加热：Ca(HCO₃)₂  --Δ-->  CaCO₃↓ + CO₂↑ + H₂O"],"reagents":["自来水","蒸馏水","肥皂水","煮沸并冷却的自来水","家用软水树脂（可选）"],"steps":["取蒸馏水与自来水各 5 mL，分别滴加肥皂水并振荡，记录出现稳定泡沫所需的滴数。","把自来水煮沸 3 分钟、冷却后重复上述操作。","若使用软水树脂，让自来水缓慢通过树脂柱，再重复测定。","比较三组滴数。"],"tags":["初中","高中"],"difficulty":2},
{"id":"air-oxygen-content","name":"测定空气中氧气的含量","category":"定量测量","hazard":2,"duration":"30 分钟","summary":"在密闭容器里点燃红磷，等它耗尽氧气后冷却，看水被吸进多少，据此估算氧气约占空气体积的 1/5。","principle":["4P + 5O₂  --点燃-->  2P₂O₅（白色固体，消耗氧气使瓶内压强下降）"],"reagents":["红磷","蒸馏水","氢氧化钠溶液（吸收尾气，可选）"],"steps":["集气瓶内加水并做刻度标记，把剩余容积五等分。","在瓶外点燃燃烧匙中的红磷，迅速伸入瓶中并塞紧。","待红磷熄灭、瓶内冷却至室温后，打开止水夹。","量取进入瓶内水的体积，计算占瓶内空气体积的比例。"],"tags":["初中"],"difficulty":2},
{"id":"burning-conditions","name":"燃烧条件的探究","category":"物质性质","hazard":2,"duration":"20 分钟","summary":"用铜片、白磷与红磷搭一个对照实验：同时看到可燃物、氧气、着火点三个条件各自的作用。","principle":["燃烧需要三个条件同时满足：可燃物、与氧气（空气）接触、温度达到着火点。"],"reagents":["白磷（少量，教师操作）","红磷","热水"],"steps":["在大烧杯中加入约 80 ℃ 热水。","铜片架在杯口，两侧分别放少量白磷与红磷。","（教师）在水中放一小块白磷，作为“有氧气”的对照。","观察铜片上与水中两块白磷是否燃烧，红磷是否燃烧。"],"tags":["初中"],"difficulty":1},
{"id":"catalyst-effect","name":"催化剂对过氧化氢分解的影响","category":"定量测量","hazard":1,"duration":"20 分钟","summary":"同样浓度的过氧化氢，分别加二氧化锰、加土豆碎和什么都不加，用排水集气量出相同时间内产生的氧气。","principle":["2H₂O₂  --MnO₂-->  2H₂O + O₂↑（MnO₂ 作催化剂，反应前后质量与化学性质不变）"],"reagents":["3% 过氧化氢溶液","二氧化锰","新鲜土豆碎","蒸馏水"],"steps":["三套装置各加 30 mL 3% 过氧化氢溶液。","1 号不加、2 号加 0.5 g 二氧化锰、3 号加等量土豆碎。","同时开始计时，用排水法收集 1 分钟内排出的气体体积。","比较三组体积，并观察反应结束后二氧化锰是否仍存在。"],"tags":["初中","高中"],"difficulty":2},
{"id":"temperature-rate","name":"温度对反应速率的影响","category":"定量测量","hazard":2,"duration":"25 分钟","summary":"把硫代硫酸钠与稀硫酸在不同温度下混合，用“出现沉淀遮住标记”的时间来量反应快慢。","principle":["Na₂S₂O₃ + H₂SO₄  →  Na₂SO₄ + SO₂↑ + S↓ + H₂O（生成的硫使溶液变浑浊）"],"reagents":["硫代硫酸钠溶液（0.1 mol/L）","稀硫酸（1 mol/L）","蒸馏水","热水与冷水"],"steps":["在三支试管中分别加入 5 mL 硫代硫酸钠溶液，放入 20 ℃、40 ℃、60 ℃ 的水浴中恒温 3 分钟。","各加入 1 mL 稀硫酸并立即计时、摇匀。","从试管上方看白纸上的黑十字，直到刚好看不见为止，记录时间。","比较三组时间，得出温度与速率的关系。"],"tags":["高中"],"difficulty":2},
{"id":"glucose-reduction","name":"葡萄糖的还原性","category":"有机","hazard":2,"duration":"30 分钟","summary":"葡萄糖与斐林试剂共热生成砖红色沉淀，与银氨溶液水浴生成银镜，两条路线互相印证醛基的还原性。","principle":["RCHO + 2Cu(OH)₂  --Δ-->  RCOOH + Cu₂O↓（砖红）+ 2H₂O","RCHO + 2[Ag(NH₃)₂]⁺ + 2OH⁻  --Δ-->  RCOO⁻ + 2Ag↓ + 3NH₃ + H₂O"],"reagents":["葡萄糖溶液（10%）","斐林试剂（或新制氢氧化铜）","银氨溶液（教师现配）","蒸馏水"],"steps":["试管中加入 2 mL 葡萄糖溶液与 2 mL 斐林试剂，摇匀。","放入沸水浴加热 3～5 分钟，观察沉淀颜色变化。","另一支试管加入 1 mL 银氨溶液与 1 mL 葡萄糖溶液，水浴温热。","观察试管内壁是否出现银镜。"],"tags":["高中"],"difficulty":3}
];
